(window.__COURSES__ = window.__COURSES__ || {})["constitutional-law"] = {"content":{"title":"宪法学","subtitle":"零基础精讲","version":"2026.10.1","chapters":[{"id":"ch1","title":"第一章 基本理论","summary":"本章学习基本理论，依次掌握宪法的概念、宪法渊源、宪法分类、宪法规范、宪法关系。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch1-s1","title":"1.1 宪法的概念","plain":"公共权力也要遵守规则。","body":"先建直觉：公共权力也要遵守规则。\n\n再上定义：教材理论：宪法规定国家根本制度、国家权力组织及公民基本权利，是国家根本法。\n\n一条关系线：国家机关→依宪法履职→保障公民权利。\n\n术语解释：根本法说明制度地位，不是包办所有细节。\n\n对比：宪法规定根本框架，具体纠纷仍需具体法律。 宪法把国家权力的来源、组织和边界放在同一框架中。权利保障不只是列一张权利清单，也需要配置机关职责，使公共权力不能脱离规范任意运作。具体部门法在这一框架中处理交易、犯罪和行政管理等事项。因而根本性与最高效力是理解宪法地位的两个角度，不能以具体法律更详细为由否定其宪法边界。\n\n生活例子：甲以为宪法不管身边事，乙应指出公民基本权利由宪法规定。","keyPoints":["其他法律不能同宪法相抵触","国家机关→依宪法履职→保障公民权利","宪法规定根本框架，具体纠纷仍需具体法律"],"pitfalls":["宪法直接规定每笔借款的还款日期","辨析：宪法规定根本框架，具体纠纷仍需具体法律"],"articles":["《宪法》第五条"]},{"id":"ch1-s2","title":"1.2 宪法渊源","plain":"学习规则要问它从哪里来。","body":"先建直觉：学习规则要问它从哪里来。\n\n再上定义：教材理论：宪法渊源讨论宪法规范的表现形式，我国以成文宪法及修正案为核心，教材评论不当然成为规范。\n\n一条关系线：立法机关→遵守宪法位阶→公民受到制度保障。\n\n术语解释：渊源讨论形式，效力讨论约束地位。\n\n对比：教材解释与法条原文不同，政策文件也不当然等于宪法。 阅读宪法材料时，可分出规范文本、法定机关的解释活动以及教学研究说明。教材能够提供概念工具，但作者的归纳不能直接变成新的国家机关权限。现行文本的核对还包含版本问题：同名文件在不同修正节点可能有不同内容，必须区分文件名称、条文内容和效力状态，不能只凭标题相同便认为全文一致。\n\n生活例子：甲把乙课堂笔记当成正式宪法，应核对原文。","keyPoints":["教材评论不当然具有宪法规范效力","立法机关→遵守宪法位阶→公民受到制度保障","教材解释与法条原文不同，政策文件也不当然等于宪法"],"pitfalls":["所有教材评论都与宪法具有同等效力","辨析：教材解释与法条原文不同，政策文件也不当然等于宪法"],"articles":["《宪法》第五条"]},{"id":"ch1-s3","title":"1.3 宪法分类","plain":"一本书可以按不同标准分类。","body":"先建直觉：一本书可以按不同标准分类。\n\n再上定义：教材理论：成文与不成文按表现形式划分，刚性与柔性按修改程序与普通法律的关系划分，同一宪法可属于不同分类。\n\n一条关系线：法定修宪主体→依程序改变根本规则→影响机关公民关系。\n\n术语解释：不成文不等于没有书面文件，刚性不等于不能修改。\n\n对比：成文与刚性不是同一标准，不能相互替代。 分类需要先固定比较标准。表现形式与修改难度属于不同问题，不能把采用统一法典与设置特别修改程序当成同义语。教材所谓刚性是相对于普通法律修改程序而言，并不是说宪法停止发展；所谓不成文也不是没有任何书面法律。这种双轴理解能避免用一个标签代替另一项制度判断。\n\n生活例子：甲称刚性宪法永不可改，乙应指出分类含义错误。","keyPoints":["刚性宪法并不意味着永远不能修改","法定修宪主体→依程序改变根本规则→影响机关公民关系","成文与刚性不是同一标准，不能相互替代"],"pitfalls":["刚性宪法是绝对不能修改的宪法","辨析：成文与刚性不是同一标准，不能相互替代"],"articles":["《宪法》第六十四条"]},{"id":"ch1-s4","title":"1.4 宪法规范","plain":"有的规则要求不侵犯，有的要求建设制度。","body":"先建直觉：有的规则要求不侵犯，有的要求建设制度。\n\n再上定义：教材理论：宪法规范涉及权利保障、权力组织和国家任务；部分规范原则性强，需要具体法律制度落实，但仍有规范约束。\n\n一条关系线：国家机关→落实宪法任务→保护公民基本权利。\n\n术语解释：原则性是表达层次，不是可随意选择是否遵守。\n\n对比：国家任务不同于每个人可直接要求固定金额的给付承诺。 组织规范回答哪个机关能做什么，权利规范确认公民受保护的利益，国家任务规范则为制度建设提供方向。三类内容相互联系：例如教育事业建设既是公共任务，也为受教育权实现创造条件。原则条款需要具体化，并不意味着具体化机关可以任意改变其方向；规范落实方式与规范本身效力必须区分。\n\n生活例子：甲说宪法原则抽象所以不必遵守，乙应否定。","keyPoints":["宪法规范原则性强不等于没有约束力","国家机关→落实宪法任务→保护公民基本权利","国家任务不同于每个人可直接要求固定金额的给付承诺"],"pitfalls":["原则性宪法规范可以一概不遵守","辨析：国家任务不同于每个人可直接要求固定金额的给付承诺"],"articles":["《宪法》第五条","《宪法》第三十三条"]},{"id":"ch1-s5","title":"1.5 宪法关系","plain":"私人买卖与政府行使职权不是同一条关系线。","body":"先建直觉：私人买卖与政府行使职权不是同一条关系线。\n\n再上定义：教材理论：宪法关系是宪法规范调整的社会关系，重点包括公共权力配置和基本权利保障，应识别主体内容及对象。\n\n一条关系线：人民→人大→有关国家机关；国家机关→保障公民权利。\n\n术语解释：职权是履行公共职责的权限，不是工作人员私人财产。\n\n对比：民事关系重平等主体请求，宪法关系重公共权力和权利配置。 宪法关系中的主体可以是国家机关，也可以是与国家权力相关的公民等主体。机关之间需分清产生关系、负责关系和监督关系，不应一律画成行政上下级关系。公民与国家之间则要同时观察公民享有什么权利以及机关承担什么保障职责。私人交易虽然可能体现宪法价值，仍不能因此略去具体民事关系。\n\n生活例子：甲研究政府向人大负责，乙应画监督线而非买卖线。","keyPoints":["机关之间的产生负责监督关系是宪法学习的重要内容","人民→人大→有关国家机关；国家机关→保障公民权利","民事关系重平等主体请求，宪法关系重公共权力和权利配置"],"pitfalls":["国家机关职权属于工作人员可私自出售的财产","辨析：民事关系重平等主体请求，宪法关系重公共权力和权利配置"],"articles":["《宪法》第二条","《宪法》第三条","《宪法》第三十三条"]}],"quiz":[{"type":"single","options":["仅列公民权利而排除权力组织","仅设置机关而不规定权利保障","配置机关职权、确认公民基本权利","仅确认国家任务而取消权力边界"],"answer":"C","explain":"前组对应国家权力组织和基本权利。","sectionId":"ch1-s1","articles":["《宪法》第五条"],"tags":["宪法的概念","综合复习"],"q":"下列哪组同时体现宪法的组织与保障功能？","id":"quiz-ch1-001","difficulty":2},{"type":"single","options":["截图未说明是否为正式解释而非宪法条文","截图缺乏可核对的正式出处和版本","截图引用教材结论而未区分学理与原文","截图只列修正年份而没有条文核对"],"answer":"B","explain":"法源可靠性取决于出处版本及内容核对，不由字数配色或个人好恶决定。","sectionId":"ch1-s2","articles":["《宪法》第五条"],"tags":["宪法渊源","综合复习"],"q":"甲以无来源截图逐字引用宪法，哪项最直接指出其原文证据缺口？","id":"quiz-ch1-002","difficulty":2},{"type":"single","options":["用修改程序标准替代了表现形式标准","将刚柔标准理解为规范内容多少","将国家结构标准当作权利分类","将渊源标准当作公民资格条件"],"answer":"A","explain":"成文与刚性分别回答形式和程序问题；其他资料不决定这一概念错误。","sectionId":"ch1-s3","articles":["《宪法》第六十四条"],"tags":["宪法分类","综合复习"],"q":"把成文宪法直接定义为修改程序特别严格，错误在哪里？","id":"quiz-ch1-003","difficulty":2},{"type":"single","options":["仅看是否在工作报告引用条文","仅看是否设立名称相同的机构","仅看是否表达赞成宪法的态度","相关制度措施及实际执行情况"],"answer":"D","explain":"任务落实要观察制度行动，口号和外观不足以证明实际实施。","sectionId":"ch1-s4","articles":["《宪法》第五条","《宪法》第三十三条"],"tags":["宪法规范","综合复习"],"q":"评价某机关是否落实宪法国家任务，哪种材料更有意义？","id":"quiz-ch1-004","difficulty":2},{"type":"single","options":["只列机关名称而不分析权利职责","只列行为目的而不识别主体","主体、权利义务或职权职责、对象","只列条文编号而不辨调整对象"],"answer":"C","explain":"前三项对应法律关系基本分析维度。","sectionId":"ch1-s5","articles":["《宪法》第二条","《宪法》第三条","《宪法》第三十三条"],"tags":["宪法关系","综合复习"],"q":"下列哪组最适合作为宪法关系分析的起点？","id":"quiz-ch1-005","difficulty":2}]},{"id":"ch2","title":"第二章 宪法历史发展","summary":"本章学习宪法历史发展，依次掌握世界宪法发展、共同纲领与1954年宪法、1975年与1978年宪法、1982年宪法及前四次修正、2018年修正与现行文本。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch2-s1","title":"2.1 世界宪法发展","plain":"规则怎样从单方面命令走向制度约束。","body":"先建直觉：规则怎样从单方面命令走向制度约束。\n\n再上定义：教材历史概述：近代宪法发展与限制专断、代表制度和自由保障相关，后续社会权和国家积极任务日益受到重视，各国发展道路不同。\n\n一条关系线：公共权力→受到制度约束→个人生活获得保障。\n\n术语解释：历史类型不是全世界同时采用同一模板。\n\n对比：历史比较不等于把外国制度直接作为我国现行规范。本节历史内容均为教材历史概述，历史文件及独立修正案原文待核验；末尾已核状态仅指所列现行宪法条文，不涵盖历史文件。 教材历史概述：早期立宪的一条重要线索是限制专断，把权力组织和自由保障写入基本制度。随着工业化与社会生活变化，劳动、教育和社会保障等问题逐步进入宪法讨论。不同国家制度形成的条件并不相同，自由权与社会权也不是简单的新旧替代关系。比较法材料能够帮助提出问题，但不能直接证明我国机关拥有外国机关的同名职权。\n\n生活例子：甲照搬外国法院制度，乙应先辨明法域。","keyPoints":["各国宪法发展道路并非完全相同","公共权力→受到制度约束→个人生活获得保障","历史比较不等于把外国制度直接作为我国现行规范"],"pitfalls":["世界各国宪法均在同年以相同方式形成","辨析：历史比较不等于把外国制度直接作为我国现行规范"],"articles":["《宪法》第五条","《宪法》第三十三条"]},{"id":"ch2-s2","title":"2.2 共同纲领与1954年宪法","plain":"国家初建的过渡安排与正式制度相衔接。","body":"先建直觉：国家初建的过渡安排与正式制度相衔接。\n\n再上定义：教材历史概述：1949年共同纲领在建国初期起临时宪法作用，1954年宪法是新中国第一部宪法；本节未核验历史原文，不逐字引用。\n\n一条关系线：国家组织安排→形成正式宪法框架→人民参与政治生活。\n\n术语解释：临时宪法作用是历史功能概括，不是今日效力认定。\n\n对比：历史功能不同于现行适用，现行问题须看现行文本。本节历史内容均为教材历史概述，历史文件及独立修正案原文待核验；末尾已核状态仅指所列现行宪法条文，不涵盖历史文件。 教材历史概述：1949年共同纲领回应建国初期国家性质、政权组织与建设任务的过渡需要，具有临时宪法作用。1954年宪法以正式宪法形式确立国家基本制度，人民代表大会制度是理解其国家权力组织的重要线索。从过渡安排到正式宪法，应同时观察文本形式与制度建设，不能把当时功能误作今日效力。\n\n生活例子：甲把共同纲领称作今日宪法正文，乙应纠正时间层次。","keyPoints":["共同纲领的临时宪法作用是历史功能概括","国家组织安排→形成正式宪法框架→人民参与政治生活","历史功能不同于现行适用，现行问题须看现行文本"],"pitfalls":["共同纲领如今完全取代现行宪法正文","辨析：历史功能不同于现行适用，现行问题须看现行文本"],"articles":["《宪法》第二条","《宪法》第五条"]},{"id":"ch2-s3","title":"2.3 1975年与1978年宪法","plain":"相同文件名称不意味着内容永远不变。","body":"先建直觉：相同文件名称不意味着内容永远不变。\n\n再上定义：教材历史概述：我国先后有1975年和1978年宪法，处于不同历史背景；应关注国家机构、权利保障与法制建设变化，不凭印象补写旧条文。\n\n一条关系线：历史机关→依当时制度运作；今日机关→依现行宪法履职。\n\n术语解释：制度沿革说明变化，不能替代现行规范判断。\n\n对比：旧宪法与现行宪法不能拼接成任意的适用条文库。本节历史内容均为教材历史概述，历史文件及独立修正案原文待核验；末尾已核状态仅指所列现行宪法条文，不涵盖历史文件。 教材历史概述：1975年宪法处于特殊历史背景，文本较简略，机构与权利安排反映当时政治环境。1978年宪法处于历史转折时期，在保留此前部分表述的同时恢复和调整若干机构与权利安排。这两个节点帮助理解制度曲折及恢复发展，不能将其旧条文同现行规则随意拼接；具体旧条文及改动仍须以历史原文核对。\n\n生活例子：甲用旧资料断言今日机构，乙应提示核对现行法。","keyPoints":["历史宪法材料与现行规范须分开使用","历史机关→依当时制度运作；今日机关→依现行宪法履职","旧宪法与现行宪法不能拼接成任意的适用条文库"],"pitfalls":["旧宪法每项条文都能直接拼入现行宪法适用","辨析：旧宪法与现行宪法不能拼接成任意的适用条文库"],"articles":["《宪法》第五条"]},{"id":"ch2-s4","title":"2.4 1982年宪法及前四次修正","plain":"制度大厦形成后可以持续修缮。","body":"先建直觉：制度大厦形成后可以持续修缮。\n\n再上定义：教材历史概述：1982年宪法构成现行宪法的基本文本，之后1988、1993、1999、2004年修正；这是文本发展，不是四部互不相干的新宪法，本节未逐字核验独立修正案。\n\n一条关系线：修宪机关→依法修正制度→国家机关公民依现行文本活动。\n\n术语解释：修正案是修改形式，合并文本方便阅读现行规则。\n\n对比：修改与重新制定不是同一概念，年份记忆不能替代原文核验。本节历史内容均为教材历史概述，历史文件及独立修正案原文待核验；末尾已核状态仅指所列现行宪法条文，不涵盖历史文件。 教材历史概述：1982年宪法总结制度建设经验，形成较完整的国家机构和基本权利义务体系。1988年修正涉及私营经济与土地使用权转让，1993年修正与社会主义市场经济等制度发展相联系，1999年修正涉及依法治国，2004年修正涉及人权、合法私有财产保护及社会保障。这些节点体现基本文本连续发展，而不是四部完整新宪法并行。\n\n生活例子：甲称四次修正是四部全新宪法，乙应辨析。","keyPoints":["宪法修正不等于每次重新制定一部完整宪法","修宪机关→依法修正制度→国家机关公民依现行文本活动","修改与重新制定不是同一概念，年份记忆不能替代原文核验"],"pitfalls":["1988至2004四次修正就是四部互不相干的新宪法","辨析：修改与重新制定不是同一概念，年份记忆不能替代原文核验"],"articles":["《宪法》第六十四条"]},{"id":"ch2-s5","title":"2.5 2018年修正与现行文本","plain":"更新后的规则不能只用旧版截图理解。","body":"先建直觉：更新后的规则不能只用旧版截图理解。\n\n再上定义：教材历史概述：2018年修正是本课程现行宪法版本节点，国家监察机关定位可从现行条文理解；核验现行合并条文不等于逐字核验全部独立修正案。\n\n一条关系线：监察机关→依宪法法律履职→接受制度约束。\n\n术语解释：版本标识与效力状态是两个字段，均须核对实际资料。\n\n对比：现行条文核验与修正案历史文字核验是不同任务。本节历史内容均为教材历史概述，历史文件及独立修正案原文待核验；末尾已核状态仅指所列现行宪法条文，不涵盖历史文件。 教材历史概述：2018年修正涉及国家监察体制等多方面内容，监察委员会进入宪法国家机构体系。更新机构图不仅是增加名称，还需理解监察权同行政、审判、检察职能的区分及配合制约关系。现行合并文本便于读取修正后的条文；独立修正案则呈现具体修改动作，两种文件的核验对象不同。\n\n生活例子：甲的旧机构图漏掉监察机关，乙应依现行文本校正。","keyPoints":["现行条文核验不能替代全部独立修正案原文核验","监察机关→依宪法法律履职→接受制度约束","现行条文核验与修正案历史文字核验是不同任务"],"pitfalls":["核验一个现行条文就等于核验所有历史修正案","辨析：现行条文核验与修正案历史文字核验是不同任务"],"articles":["《宪法》第一百二十三条","《宪法》第五条"]}],"quiz":[{"type":"single","options":["仅确认文件名称而未辨现行版本","制度形成背景与权力权利安排的变化","仅划成文类型而未说明分类依据","仅列现行条号而未说明规范内容"],"answer":"B","explain":"历史学习需要理解变化与背景，后三项不属于宪法发展史的核心解释变量。","sectionId":"ch2-s1","articles":["《宪法》第五条","《宪法》第三十三条"],"tags":["世界宪法发展","综合复习"],"q":"甲研究宪法史只记年份不看制度问题，主要遗漏了什么？","id":"quiz-ch2-001","difficulty":2},{"type":"single","options":["两份历史文件的可靠原文","仅以现行合并文本反推全部旧条文","仅以历史评价论文代替两份原文","仅以制宪年份确定逐字内容"],"answer":"A","explain":"逐字比较需要各自原文。","sectionId":"ch2-s2","articles":["《宪法》第二条","《宪法》第五条"],"tags":["共同纲领与1954年宪法","综合复习"],"q":"甲希望逐字比较共同纲领和1954年宪法，首先还需补充什么？","id":"quiz-ch2-002","difficulty":2},{"type":"single","options":["一律按最早版本处理","随意挑选有利条文","按文本篇幅决定优先","另核现行文本，避免直接沿用旧结论"],"answer":"D","explain":"历史评价与现行适用是不同任务，早晚、利弊和篇幅不是任选旧条文的依据。","sectionId":"ch2-s3","articles":["《宪法》第五条"],"tags":["1975年与1978年宪法","综合复习"],"q":"对旧宪法作历史评价后，如何处理现行法问题？","id":"quiz-ch2-003","difficulty":2},{"type":"single","options":["只看原始版不看更新","把所有修正都当普通政策","说明随后修正已纳入现行阅读版本","宣称其后从无修改"],"answer":"C","explain":"说明更新能避免误读为只适用最初文字；其余均割裂文本发展。","sectionId":"ch2-s4","articles":["《宪法》第六十四条"],"tags":["1982年宪法及前四次修正","综合复习"],"q":"学生把1982年宪法称为现行宪法基本文本，后面应补哪项才能避免误导？","id":"quiz-ch2-004","difficulty":2},{"type":"single","options":["前者是现行版本，后者是实施状态","前者是效力状态，后者是版本标识","二者均仅表示最初制定时间","前者只说公布机关，后者只说文本形式"],"answer":"B","explain":"状态与版本回答不同问题，不可用它们推断所有历史规范效力。","sectionId":"ch2-s5","articles":["《宪法》第一百二十三条","《宪法》第五条"],"tags":["2018年修正与现行文本","综合复习"],"q":"关于现行有效与2018修正两个信息，哪项准确？","id":"quiz-ch2-005","difficulty":2}]},{"id":"ch3","title":"第三章 基本原则与国体","summary":"本章学习基本原则与国体，依次掌握人民主权、人权保障、社会主义法治、民主集中制、人民民主专政与国体。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch3-s1","title":"3.1 人民主权","plain":"公共权力不是工作人员私人所有。","body":"先建直觉：公共权力不是工作人员私人所有。\n\n再上定义：我国一切权力属于人民，人民通过人大及法律规定的其他途径形式管理国家和社会事务；不能理解为个人可随时替代国家机关。\n\n一条关系线：人民→人大→有关国家机关依法履职。\n\n术语解释：权力归属不同于具体行使权限。\n\n对比：人民主权不等于每人拥有所有国家机关职权。 人民主权回答公共权力最终属于谁，机关权限回答权力通过什么制度行使。人民依法管理国家、经济文化和社会事务，有人大途径也有法律规定的其他途径形式。个人不能从属于人民这一身份直接推出自己具有行政命令权或司法裁判权。人民的权力归属与机关的授权履职，分别处于政治正当性和制度运行层次。\n\n生活例子：甲自己签发行政命令，乙应区分归属与行使。","keyPoints":["权力属于人民不等于个人可行使一切机关职权","人民→人大→有关国家机关依法履职","人民主权不等于每人拥有所有国家机关职权"],"pitfalls":["每位公民均能凭人民主权自行签发国家命令","辨析：人民主权不等于每人拥有所有国家机关职权"],"articles":["《宪法》第二条"]},{"id":"ch3-s2","title":"3.2 人权保障","plain":"国家不能只要求服从而不保护人的基本生活。","body":"先建直觉：国家不能只要求服从而不保护人的基本生活。\n\n再上定义：国家尊重和保障人权；教材理论将尊重理解为避免不当侵犯，将保障理解为通过制度和措施保护权利，两者相互配合。\n\n一条关系线：国家机关→避免侵害并依法保障→公民基本权利。\n\n术语解释：消极义务重不侵犯，积极义务重保障措施。\n\n对比：不干预不是全部保障，保护名义也不是任意干预许可。 教材理论通常把人权保障分为不当侵害的避免与必要保护措施的提供。前者要求机关克制不合法干预，后者要求建立保护和救济制度。两者都以法律框架为边界，保护目的并不能使手段免受审查。分析人权问题既要看到直接行使公权力的行为，也要注意制度是否为遭侵害者提供合法的保护途径。\n\n生活例子：甲权利受他人侵害，乙应理解国家可能需要提供合法保护机制。","keyPoints":["人权保障既有避免侵害也有制度保护的要求","国家机关→避免侵害并依法保障→公民基本权利","不干预不是全部保障，保护名义也不是任意干预许可"],"pitfalls":["国家不直接侵害就永远无须提供任何保护机制","辨析：不干预不是全部保障，保护名义也不是任意干预许可"],"articles":["《宪法》第三十三条"]},{"id":"ch3-s3","title":"3.3 社会主义法治","plain":"规则不能只约束被管理者而不约束管理者。","body":"先建直觉：规则不能只约束被管理者而不约束管理者。\n\n再上定义：国家实行依法治国，维护法制统一；任何组织个人不得有超越宪法法律的特权，良好目的不能自动补足权限和程序。\n\n一条关系线：国家机关→受宪法法律约束→公民免受任意权力侵害。\n\n术语解释：法治强调权力受规则约束，法制偏重制度体系。\n\n对比：有法律文件不等于已依法实施，效率不能替代合法性。 宪法维护法制统一，要求法律、行政法规和地方性法规不得与宪法抵触。对权力的约束同时涉及权限、行为依据和落实状况。法治并非仅有规范文本，也不是把法律只当作要求公民服从的工具；机关本身必须依法活动。追求效率或便利可以解释行动目标，但不能代替对权限是否存在、程序是否适当的判断。\n\n生活例子：甲为提高效率无视权限，乙应要求核对依据。","keyPoints":["职务高低不影响遵守宪法法律的要求","国家机关→受宪法法律约束→公民免受任意权力侵害","有法律文件不等于已依法实施，效率不能替代合法性"],"pitfalls":["职位越高越可自由选择是否遵守宪法","辨析：有法律文件不等于已依法实施，效率不能替代合法性"],"articles":["《宪法》第五条"]},{"id":"ch3-s4","title":"3.4 民主集中制","plain":"民主讨论与依法形成统一决定需要衔接。","body":"先建直觉：民主讨论与依法形成统一决定需要衔接。\n\n再上定义：国家机构实行民主集中制，人大民主选举产生，有关行政监察审判检察机关由人大产生，对其负责受其监督；中央统一领导下发挥地方积极性。\n\n一条关系线：人民→人大→行政监察审判检察机关。\n\n术语解释：集中不等于个人任意决定，民主不等于不需共同规则。\n\n对比：统一制度联系不取消机关依法分工。 民主集中制把民主产生、依法负责和监督联系起来。人大由民主选举产生，对人民负责并受人民监督；有关国家机关由人大产生，对其负责并受其监督。统一不取消具体职能差别，行政、监察、审判和检察机关仍须分别履职。在中央地方关系上，也应把统一领导与发挥地方主动积极性同时写清，而非只取一面。\n\n生活例子：甲把法院政府画成同一办公室，乙应提示各有职责。","keyPoints":["民主集中制不取消国家机关依法分工","人民→人大→行政监察审判检察机关","统一制度联系不取消机关依法分工"],"pitfalls":["民主集中制意味着各国家机关具体职权完全相同","辨析：统一制度联系不取消机关依法分工"],"articles":["《宪法》第三条"]},{"id":"ch3-s5","title":"3.5 人民民主专政与国体","plain":"问国家性质与问权力怎样组织不是同一个问题。","body":"先建直觉：问国家性质与问权力怎样组织不是同一个问题。\n\n再上定义：我国是工人阶级领导的以工农联盟为基础的人民民主专政的社会主义国家；社会主义制度是根本制度，中国共产党领导是中国特色社会主义最本质的特征。\n\n一条关系线：人民→作为国家主人参与事务；国家机关→依宪法维护制度保障权利。\n\n术语解释：国体回答性质社会基础，政体回答政权组织形式。\n\n对比：人民民主专政与人大制度分别属于国体和政体层次。 第一条的国体表述同时涉及领导阶级、社会基础和国家性质，不能只记最后的国家名称而遗漏前面的结构。社会主义制度属于根本制度，党的领导具有宪法明确定位。教材在此区分国体与政体：前者讨论国家性质，后者讨论政权组织形式。人民代表大会制度与人民民主专政有关联，但并非能够互换的两个词。\n\n生活例子：甲把人大制度填作国体，乙应区分问题层次。","keyPoints":["国体与政体应按国家性质和组织形式区分","人民→作为国家主人参与事务；国家机关→依宪法维护制度保障权利","人民民主专政与人大制度分别属于国体和政体层次"],"pitfalls":["国体和政体完全同义可以在任何语境互换","辨析：人民民主专政与人大制度分别属于国体和政体层次"],"articles":["《宪法》第一条","《宪法》第二条"]}],"quiz":[{"type":"single","options":["人民侧重政治概念，公民以国籍识别","两者都仅按财产确定","公民只包括有投票资格者","人民只指国家工作人员"],"answer":"A","explain":"国籍是公民身份依据；人民是政治概念，不宜用财产职业或投票资格简单替代。","sectionId":"ch3-s1","articles":["《宪法》第二条"],"tags":["人民主权","综合复习"],"q":"区分人民和公民时，哪项更准确？","id":"quiz-ch3-001","difficulty":2},{"type":"single","options":["只审查保护目的而不审查手段","只审查实施主体而不识别受保护利益","只看措施有益而不问权限边界","保护谁的权利、措施本身是否合法"],"answer":"D","explain":"目标与手段都重要，宣传和外观指标不能替代权利与合法性分析。","sectionId":"ch3-s2","articles":["《宪法》第三十三条"],"tags":["人权保障","综合复习"],"q":"分析保障人权措施时，哪组问题应同时提出？","id":"quiz-ch3-002","difficulty":2},{"type":"single","options":["有法制文件就无需落实法治","法治仅约束公民不约束机关","前者突出权力受规范约束，后者常侧重制度体系","二者都仅指文件排版"],"answer":"C","explain":"这一区分帮助理解制度与运行，不能把法治缩减为排版或单方面服从。","sectionId":"ch3-s3","articles":["《宪法》第五条"],"tags":["社会主义法治","综合复习"],"q":"关于法治和法制，教材入门辨析宜怎样说？","id":"quiz-ch3-003","difficulty":2},{"type":"single","options":["混淆民主选举与机关任免的不同环节","混淆制度统一与具体职能分工","混淆人大监督与行政领导关系","混淆中央地方划分与个人基本权利"],"answer":"B","explain":"统一原则不消除行政监察审判检察等职能差别，数量地点并不决定此问题。","sectionId":"ch3-s4","articles":["《宪法》第三条"],"tags":["民主集中制","综合复习"],"q":"把民主集中制解释成所有机关职权完全相同，错在哪里？","id":"quiz-ch3-004","difficulty":2},{"type":"single","options":["对国家性质与社会基础的回答","对代表直接间接产生路径的回答","对中央地方职权划分的回答","对普通法律修改门槛的回答"],"answer":"A","explain":"国体题关注国家性质，不能以机构名录代替概念层面的回答。","sectionId":"ch3-s5","articles":["《宪法》第一条","《宪法》第二条"],"tags":["人民民主专政与国体","综合复习"],"q":"甲把国体题写成中央机关名单，主要欠缺什么？","id":"quiz-ch3-005","difficulty":2}]},{"id":"ch4","title":"第四章 人大制度与选举","summary":"本章学习人大制度与选举，依次掌握人民代表大会制度、代表及履职保障、直接与间接选举、普遍与平等选举、选举程序框架。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch4-s1","title":"4.1 人民代表大会制度","plain":"公共事务需要制度化的代表机关。","body":"先建直觉：公共事务需要制度化的代表机关。\n\n再上定义：教材理论：人大制度是我国根本政治制度，人民选出代表组成国家权力机关，有关其他机关由人大产生并受监督，不能仅理解为召开会议。\n\n一条关系线：人民→代表→人大→有关国家机关。\n\n术语解释：政体是国家政权组织形式。\n\n对比：人大制度不等于普通社会团体活动，也不与政协制度等同。 人大制度的内容不止代表投票或召开大会，还包括国家机关的组织与负责监督联系。全国人大与地方各级人大具有不同层次的权力机关地位，相关其他机关在各自权限内开展工作。教材将人大制度称为根本政治制度，同时还介绍其他重要政治制度；它们共同构成政治生活的制度安排，却不能因此把不同地位直接混为一谈。\n\n生活例子：甲认为人大闭会后国家工作停止，乙应解释常设机关分工。","keyPoints":["人大制度包括产生负责监督等制度联系","人民→代表→人大→有关国家机关","人大制度不等于普通社会团体活动，也不与政协制度等同"],"pitfalls":["人民代表大会只是没有国家权力的普通社团","辨析：人大制度不等于普通社会团体活动，也不与政协制度等同"],"articles":["《宪法》第二条","《宪法》第三条","《宪法》第五十七条"]},{"id":"ch4-s2","title":"4.2 代表及履职保障","plain":"代表敢发言需要保障，但不是私人违法免责卡。","body":"先建直觉：代表敢发言需要保障，但不是私人违法免责卡。\n\n再上定义：全国人大代表在全国人大各种会议上的发言表决不受法律追究；须保留身份场合行为限定，不能扩大为一切言行都免责。\n\n一条关系线：全国人大代表→在法定会议履职→特定发言表决获得保障。\n\n术语解释：言论免责是课堂概括，要同时写清适用范围。\n\n对比：会议发言表决保障不同于所有私人行为均不担责。 代表保障服务于依法履职，不是代表个人生活的全面免责。第七十五条的适用需同时核对全国人大代表身份、全国人大各种会议的场合，以及发言或表决的行为类型。私人经营活动不能因行为人有代表身份就自动纳入这一保障。会议言论表决保障与代表可能涉及的其他保护程序，也须按各自规范分别学习。\n\n生活例子：甲称代表私人欺诈也当然免责，乙应否定扩大解释。","keyPoints":["代表会议发言表决保障不能扩张到一切私人行为","全国人大代表→在法定会议履职→特定发言表决获得保障","会议发言表决保障不同于所有私人行为均不担责"],"pitfalls":["全国人大代表任何场合实施任何行为均不受追究","辨析：会议发言表决保障不同于所有私人行为均不担责"],"articles":["《宪法》第七十五条","《宪法》第五十九条"]},{"id":"ch4-s3","title":"4.3 直接与间接选举","plain":"选民直接投票与下级人大选上级代表路径不同。","body":"先建直觉：选民直接投票与下级人大选上级代表路径不同。\n\n再上定义：县、不设区的市、市辖区、乡、民族乡、镇人大代表由选民直接选举；省直辖市设区的市代表由下一级人大选举，全国人大代表组成另有宪法框架。\n\n一条关系线：选民→县乡等人大代表；下一级人大→相应上级人大代表。\n\n术语解释：直接间接描述产生路径，不评价重要程度。\n\n对比：选代表不是直接选所有行政负责人，全国人大代表也非全民直接投票产生。 直接和间接选举以代表产生路径为标准，不以代表的重要性排序。县及宪法列明的相应县乡层级代表由选民直接选举，省、直辖市、设区的市代表由下一级人大选举。全国人大代表的组成框架由第五十九条另作规定。选举代表与产生政府负责人不是同一职位问题，不能因参加了县级投票就说成直接选举县长。\n\n生活例子：甲参加县代表选举，乙应识别为直接选举。","keyPoints":["县人大代表由选民直接选举","选民→县乡等人大代表；下一级人大→相应上级人大代表","选代表不是直接选所有行政负责人，全国人大代表也非全民直接投票产生"],"pitfalls":["所有层级人大代表都由全体选民直接选举","辨析：选代表不是直接选所有行政负责人，全国人大代表也非全民直接投票产生"],"articles":["《宪法》第九十七条","《宪法》第五十九条"]},{"id":"ch4-s4","title":"4.4 普遍与平等选举","plain":"不能仅按财产学历随意决定参与资格。","body":"先建直觉：不能仅按财产学历随意决定参与资格。\n\n再上定义：年满十八周岁的中国公民原则上有选举权被选举权，依法被剥夺政治权利者除外，宪法排除民族性别教育程度财产状况等歧视性门槛。\n\n一条关系线：国家选举组织工作→依法保障符合条件公民参与。\n\n术语解释：普遍看参与范围，平等看参与地位。\n\n对比：普遍选举不等于没有年龄和法定例外条件。 第三十四条把国籍、年龄和依法被剥夺政治权利的例外结合起来，并列明不得因民族、性别、教育程度和财产状况等条件作任意排除。普遍性关注谁能够进入选举，平等性关注参与的法律地位。二者都不要求所有选民拥有同样观点，也不意味着组织者可以用自己的偏好增设学历财产门槛。\n\n生活例子：甲因学历低被说成没有选举权，乙应核对宪法资格条件。","keyPoints":["教育程度不是任意剥夺选举权的理由","国家选举组织工作→依法保障符合条件公民参与","普遍选举不等于没有年龄和法定例外条件"],"pitfalls":["只有大学毕业且财产充足者才享有选举权","辨析：普遍选举不等于没有年龄和法定例外条件"],"articles":["《宪法》第三十四条"]},{"id":"ch4-s5","title":"4.5 选举程序框架","plain":"投票之前之后还有多个程序环节。","body":"先建直觉：投票之前之后还有多个程序环节。\n\n再上定义：教材框架：按资格确认、组织、候选人形成、投票、结果确认和监督理解选举；宪法只给基本框架，具体期限差额有效票数须另核选举法，本包未核这些细节。\n\n一条关系线：选举组织者→依法组织→选民代表参与监督。\n\n术语解释：框架是学习导航，不是已核验全部选举法规则。\n\n对比：宪法第三十四条、第五十九条、第九十七条不能替代选举法程序细节。 选举程序可按资格、组织、候选人形成、投票、结果和监督分别梳理。这一顺序帮助理解每个环节解决的不同问题：资格涉及谁能参加，候选人形成涉及供选择的人选，结果确认涉及投票后的依法判断。宪法规定基本权利和产生框架，而具体期限、差额和有效票数等事项须在选举法中查明，不能将框架当成细则。\n\n生活例子：甲问候选人公布天数，乙不能凭宪法猜数字。","keyPoints":["选举具体法定数字须核对选举法","选举组织者→依法组织→选民代表参与监督","宪法第三十四五十九九十七条不能替代选举法程序细节"],"pitfalls":["仅凭宪法第三十四条能确定选举所有法定期限","辨析：宪法第三十四五十九九十七条不能替代选举法程序细节"],"articles":["《宪法》第三十四条","《宪法》第五十九条","《宪法》第九十七条"]}],"quiz":[{"type":"single","options":["仅遗漏会议召集的具体细则","仅遗漏代表名单和组成形式","仅遗漏大会会期而制度联系已完整","权力机关的产生、职责与监督联系"],"answer":"D","explain":"制度包括持续性的组织职权和负责监督机制，不只是会务事项。","sectionId":"ch4-s1","articles":["《宪法》第二条","《宪法》第三条","《宪法》第五十七条"],"tags":["人民代表大会制度","综合复习"],"q":"将人大制度仅理解为一年中召开会议的活动，遗漏了什么？","id":"quiz-ch4-001","difficulty":2},{"type":"single","options":["身份、私人目的、个人声誉","身份、是否退休、是否参会","身份、会议场合、行为类型","任职层级、发表地点、社会反响"],"answer":"C","explain":"身份场合行为对应保障适用范围；其他个人信息不能替代该范围审查。","sectionId":"ch4-s2","articles":["《宪法》第七十五条","《宪法》第五十九条"],"tags":["代表及履职保障","综合复习"],"q":"理解代表履职保障，应同时核对哪三项？","id":"quiz-ch4-002","difficulty":2},{"type":"single","options":["规定由所有居民委员会直接选出","规定组成框架并将名额产生办法交由法律规定","将一切细节全部写完","规定由地方政府统一任命"],"answer":"B","explain":"该条明确组成及主持机关，并有法律具体化要求，不支持任命或居委会产生说。","sectionId":"ch4-s3","articles":["《宪法》第九十七条","《宪法》第五十九条"],"tags":["直接与间接选举","综合复习"],"q":"第五十九条对全国人大代表的组成和产生办法，哪项准确？","id":"quiz-ch4-003","difficulty":2},{"type":"single","options":["不分民族等条件享有选举权的规定","人大与政府的负责监督规定","代表会议发言表决保障","国家机关统一领导原则"],"answer":"A","explain":"第三十四条直接回应选举资格歧视；其他规则保护对象或调整关系不同。","sectionId":"ch4-s4","articles":["《宪法》第三十四条"],"tags":["普遍与平等选举","综合复习"],"q":"甲因民族不同被排除选举资格，首先应核对哪个宪法规则？","id":"quiz-ch4-004","difficulty":2},{"type":"single","options":["按经验随意报出日期","认为程序不重要","把投票日直接当所有公告日","明确需另核选举法，不猜法定天数"],"answer":"D","explain":"具体期限必须有相应法源证据，经验和随意合并环节会误导程序判断。","sectionId":"ch4-s5","articles":["《宪法》第三十四条","《宪法》第五十九条","《宪法》第九十七条"],"tags":["选举程序框架","综合复习"],"q":"甲问某次选举应何时公布名单，现有材料只有宪法框架，乙应怎样回答？","id":"quiz-ch4-005","difficulty":2}]},{"id":"ch5","title":"第五章 国家结构","summary":"本章学习国家结构，依次掌握单一制、行政区划、民族区域自治、特别行政区、基层群众自治。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch5-s1","title":"5.1 单一制","plain":"地方是统一国家内部的组成部分。","body":"先建直觉：地方是统一国家内部的组成部分。\n\n再上定义：教材理论：我国是统一多民族单一制国家，中央统一领导与发挥地方积极性结合，地方依法有权限不等于具有独立国家主权。\n\n一条关系线：中央→统一领导依法配置权限→地方依法管理本地事务。\n\n术语解释：国家结构讨论整体与部分，政体讨论权力组织。\n\n对比：有自治权限不等于联邦制，更不等于独立国家。 国家结构形式关注统一国家同组成部分的关系。我国在中央统一领导下配置地方职权，地方可以依法管理本地事务并发挥主动性。存在地方权限不等于出现独立主权，存在自治制度也不能单凭这一点就判断为联邦制。教材的单一制概念与政体概念处在不同维度，不能把地方关系题改写为机关名单题。\n\n生活例子：甲看到地方自治权便称其独立，乙应区分权限和主权。","keyPoints":["地方依法自治不意味着拥有独立国家主权","中央→统一领导依法配置权限→地方依法管理本地事务","有自治权限不等于联邦制，更不等于独立国家"],"pitfalls":["只要有地方自治该国必然属于联邦制","辨析：有自治权限不等于联邦制，更不等于独立国家"],"articles":["《宪法》第三条","《宪法》第四条"]},{"id":"ch5-s2","title":"5.2 行政区划","plain":"地址层次背后有治理空间的分工。","body":"先建直觉：地址层次背后有治理空间的分工。\n\n再上定义：宪法规定全国省自治区直辖市等基本行政区域划分，县自治县分为乡民族乡镇；自治区自治州自治县是民族自治地方。\n\n一条关系线：国家→依法划分行政区域→地方机关依区域履职。\n\n术语解释：行政区划是空间治理单元，不是机关性质的全部答案。\n\n对比：民族乡不等于宪法所列民族自治地方。 行政区划是组织国家治理的空间基础，不同层级与类型的名称各有规范含义。自治区、自治州、自治县为民族自治地方，民族乡并不在这一列举中。区划本身与机关又应区分，县是一类地域单元，县人大和县政府则是不同性质的组织。不能由同在一个区域就推断机关职权相同，更不能只凭民族二字判断自治地方。\n\n生活例子：甲将民族乡与自治区归入相同自治地方类别，乙应纠正。","keyPoints":["民族乡不是宪法列明的民族自治地方","国家→依法划分行政区域→地方机关依区域履职","民族乡不等于宪法所列民族自治地方"],"pitfalls":["名称含民族的所有行政区域都是民族自治地方","辨析：民族乡不等于宪法所列民族自治地方"],"articles":["《宪法》第三十条"]},{"id":"ch5-s3","title":"5.3 民族区域自治","plain":"统一国家内部可以依法因地制宜治理。","body":"先建直觉：统一国家内部可以依法因地制宜治理。\n\n再上定义：少数民族聚居地方实行区域自治，各民族自治地方是国家不可分离部分；自治机关是自治区自治州自治县人大和政府，依法有相应自治权。\n\n一条关系线：国家→保障各民族平等；自治机关→依法行使自治权。\n\n术语解释：区域自治不是每个民族个人随处拥有独立国家权力。\n\n对比：民族区域自治与基层群众自治特别行政区制度不同。 民族区域自治建立在统一国家和民族平等基础上。各少数民族聚居地方实行区域自治，自治地方人大和政府是自治机关，在履行一般地方职权之外依法行使自治权。民族语言文字和风俗习惯的自由也是相关保障内容。区域自治不是将国家主权分给个人，也不是把当地每个组织都提升为自治机关。\n\n生活例子：甲问自治县法院是否自治机关，乙应按宪法特定范围回答。","keyPoints":["民族自治地方自治机关指相应人大和政府","国家→保障各民族平等；自治机关→依法行使自治权","民族区域自治与基层群众自治特别行政区制度不同"],"pitfalls":["自治地方所有机关都是宪法特指的自治机关","辨析：民族区域自治与基层群众自治特别行政区制度不同"],"articles":["《宪法》第四条","《宪法》第一百一十二条","《宪法》第一百一十五条"]},{"id":"ch5-s4","title":"5.4 特别行政区","plain":"同一国家内特定地区可以依法设置不同制度。","body":"先建直觉：同一国家内特定地区可以依法设置不同制度。\n\n再上定义：国家必要时得设特别行政区，实行的制度由全国人大按具体情况以法律规定，全国人大决定其设立和制度；本节不扩展未经核验的基本法细则。\n\n一条关系线：全国人大→依法决定设立及制度→特别行政区依法治理。\n\n术语解释：特别行政区不是独立主权国家。\n\n对比：特别行政区与民族自治区不能因都有区字而混同。 特别行政区制度在宪法上有专门依据。第三十一条确定区内制度依具体情况由全国人大以法律规定，第六十二条规定全国人大决定设立及制度的职权。特殊制度与统一国家地位可以并存，不能从特殊二字推出独立主权。民族自治区与特别行政区的制度性质不同，需要分别从各自依据出发理解。\n\n生活例子：甲说相关制度由地方任意决定，乙应指出全国人大职责。","keyPoints":["特别行政区制度由全国人大以法律规定","全国人大→依法决定设立及制度→特别行政区依法治理","特别行政区与民族自治区不能因都有区字而混同"],"pitfalls":["特别行政区制度完全由地方任意决定且无国家法律依据","辨析：特别行政区与民族自治区不能因都有区字而混同"],"articles":["《宪法》第三十一条","《宪法》第六十二条"]},{"id":"ch5-s5","title":"5.5 基层群众自治","plain":"居民共同处理社区事务不等于建立一级政府。","body":"先建直觉：居民共同处理社区事务不等于建立一级政府。\n\n再上定义：居委会村委会是基层群众性自治组织，办理本地公共事务公益事业、调解纠纷并反映群众意见，不是国家机关。\n\n一条关系线：居民村民→选出自治组织→办理共同事务；组织→依法协助并反映意见。\n\n术语解释：基层自治不同于基层政权。\n\n对比：协助公共事务不自动转化为国家行政机关。 基层自治以居住地区公共事务和公益事业为重要对象。村居委会可以调解民间纠纷、协助维护治安并向政府反映群众意见，但这些作用不改变其群众性自治组织性质。乡政府属于国家行政机关，二者不能因工作中有协作就混成同一组织。自治组织履职也应有规范边界，不能由协助二字推导出全面行政处罚权。\n\n生活例子：甲称村委会等于乡政府，乙应从性质纠正。","keyPoints":["村民委员会不是一级国家行政机关","居民村民→选出自治组织→办理共同事务；组织→依法协助并反映意见","协助公共事务不自动转化为国家行政机关"],"pitfalls":["村民委员会就是乡人民政府的另一称呼","辨析：协助公共事务不自动转化为国家行政机关"],"articles":["《宪法》第一百一十一条"]}],"quiz":[{"type":"single","options":["将机关之间分工看作产生关系","将代表选举方式看作民主参与方式","将局部权限特点当成国家结构的充分标准","将宪法规范形式看作解释材料"],"answer":"C","explain":"自治权限与整体结构分类不能简单画等号，需要看完整宪制安排。","sectionId":"ch5-s1","articles":["《宪法》第三条","《宪法》第四条"],"tags":["单一制","综合检验"],"q":"甲把有地方自治直接等同于联邦制，应纠正哪个推理？","id":"quiz-ch5-001","difficulty":2},{"type":"single","options":["对自治地方人口规模的核对","对宪法明确分类的核对","对所有地方机关权限相同的确认","对当地是否设民族事务部门的核对"],"answer":"B","explain":"名称直觉不足以替代规范分类，应核对第三十条规定。","sectionId":"ch5-s2","articles":["《宪法》第三十条"],"tags":["行政区划","综合检验"],"q":"甲只凭名字中有民族二字就判断自治地方，欠缺什么？","id":"quiz-ch5-002","difficulty":2},{"type":"single","options":["前者涉及法定自治地方机关，后者为基层群众自治","两者都是独立主权国家制度","两者组织全部为法院","两者仅仅名称不同性质相同"],"answer":"A","explain":"两类自治的主体地域及法律地位不同，不能凭自治二字混同。","sectionId":"ch5-s3","articles":["《宪法》第四条","《宪法》第一百一十二条","《宪法》第一百一十五条"],"tags":["民族区域自治","综合检验"],"q":"区分民族区域自治与村民自治，哪项最准确？","id":"quiz-ch5-003","difficulty":2},{"type":"single","options":["行政机关与司法机关的职能区别","普通权利与选举资格的主体区别","法律解释与学理解释的来源区别","国家内部特别安排与独立国家地位"],"answer":"D","explain":"特别行政区仍在统一国家内，特殊制度不等于成为另一个国家。","sectionId":"ch5-s4","articles":["《宪法》第三十一条","《宪法》第六十二条"],"tags":["特别行政区","综合检验"],"q":"甲认为特殊制度即独立主权，乙应抓住什么区别？","id":"quiz-ch5-004","difficulty":2},{"type":"single","options":["国家权力机关与行政机关","民族自治机关与国家审判机关","国家行政机关与群众自治组织","地方行政机关与其下属行政机关"],"answer":"C","explain":"两者性质不同。","sectionId":"ch5-s5","articles":["《宪法》第一百一十一条"],"tags":["基层群众自治","综合检验"],"q":"乡政府与村委会最重要的入门区分是什么？","id":"quiz-ch5-005","difficulty":2}]},{"id":"ch6","title":"第六章 经济文化社会制度","summary":"本章学习经济文化社会制度，依次掌握经济制度基础、公有制与非公有制、财产权与土地、教育文化事业、社会保障环境。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch6-s1","title":"6.1 经济制度基础","plain":"先问生产资料由谁所有再看具体经营。","body":"先建直觉：先问生产资料由谁所有再看具体经营。\n\n再上定义：生产资料社会主义公有制是我国社会主义经济制度基础，包括全民所有制和劳动群众集体所有制，公有制为主体多种所有制共同发展。\n\n一条关系线：国家→确立经济制度框架→各类主体依法活动。\n\n术语解释：生产资料与个人日常消费品要区分。\n\n对比：公有制主体不等于每件私人生活用品都须公有。 生产资料社会主义公有制包括全民所有制与劳动群众集体所有制。宪法又规定公有制为主体、多种所有制经济共同发展，以及按劳分配为主体、多种分配方式并存。主体不是唯一，所有制与分配制度也不是同一个问题。分析具体财产时仍应分清生产资料和个人消费物，不能以制度基础取代每一种财产权的具体判断。\n\n生活例子：甲说私营店铺也须全部国有，乙应指出多种所有制共同发展。","keyPoints":["生产资料制度不能机械等同于全部个人生活用品归属","国家→确立经济制度框架→各类主体依法活动","公有制主体不等于每件私人生活用品都须公有"],"pitfalls":["公有制意味着全部个人生活用品都必须国家所有","辨析：公有制主体不等于每件私人生活用品都须公有"],"articles":["《宪法》第六条"]},{"id":"ch6-s2","title":"6.2 公有制与非公有制","plain":"市场主体有不同所有制类型。","body":"先建直觉：市场主体有不同所有制类型。\n\n再上定义：法律范围内非公有制经济是社会主义市场经济重要组成部分，国家保护合法权益，鼓励支持引导发展并依法监督管理。\n\n一条关系线：国家→依法保护监管→经营者依法经营。\n\n术语解释：合法权益保护不等于免受一切合法监管。\n\n对比：保护与监管可以并存，依法监管也不是任意干预。 非公有制经济在法律规定范围内属于社会主义市场经济重要组成部分。国家保护合法权益，鼓励、支持、引导发展，同时依法监督管理。这些内容不是彼此排斥的选项：受保护不等于免监管，能监管也不等于可任意干预。公有制主体与非公有制依法发展需放在同一经济制度框架中理解。\n\n生活例子：甲称私企受保护就能拒绝任何合法监管，乙应辨析。","keyPoints":["保护非公有制合法权益与依法监管可以并存","国家→依法保护监管→经营者依法经营","保护与监管可以并存，依法监管也不是任意干预"],"pitfalls":["保护非公有制经济意味着不得有任何合法监管","辨析：保护与监管可以并存，依法监管也不是任意干预"],"articles":["《宪法》第六条","《宪法》第十一条"]},{"id":"ch6-s3","title":"6.3 财产权与土地","plain":"买到房屋不等于取得城市土地私人所有权。","body":"先建直觉：买到房屋不等于取得城市土地私人所有权。\n\n再上定义：宪法保护合法私有财产和继承权；城市土地国家所有，农村城市郊区土地原则集体所有但有法定例外，使用权可依法转让，公共利益征收征用须依法补偿。\n\n一条关系线：国家→依法保护财产并规范征收征用→公民财产获保障。\n\n术语解释：所有权是归属，使用权是利用，房屋与土地也须分开。\n\n对比：财产保护不等于绝对禁止依法征收，使用权转让不是土地所有权买卖。 城市土地国家所有，农村和城市郊区土地原则集体所有但有法律规定的国有例外；宅基地也属集体所有。土地归属与依法使用、转让使用权并非同一事项。合法私产保护与依法征收征用也不是绝对对立，公共利益、法律规定和补偿条件须共同考虑，不能只留公共利益而删除其他限制。\n\n生活例子：甲买房自称私人拥有城市土地，乙应纠正。","keyPoints":["土地所有权与使用权应区分","国家→依法保护财产并规范征收征用→公民财产获保障","财产保护不等于绝对禁止依法征收，使用权转让不是土地所有权买卖"],"pitfalls":["买城市房屋必然取得城市土地私人所有权","辨析：财产保护不等于绝对禁止依法征收，使用权转让不是土地所有权买卖"],"articles":["《宪法》第十条","《宪法》第十三条"]},{"id":"ch6-s4","title":"6.4 教育文化事业","plain":"学校图书馆和文化遗产不只是私人消费。","body":"先建直觉：学校图书馆和文化遗产不只是私人消费。\n\n再上定义：国家发展教育事业和文化事业，提高科学文化水平并保护重要历史文化遗产，这些国家任务需要通过具体制度资源落实。\n\n一条关系线：国家→建设教育文化事业→公民享有相应发展条件。\n\n术语解释：国家任务不是每个具体项目固定金额给付承诺。\n\n对比：公共文化制度建设与个人即时请求无限补贴不同。 国家教育文化任务同时涉及学校教育、学习条件、文化事业和文化遗产保护。教育事业发展为公民受教育创造条件，文化事业也不只指娱乐消费，图书馆、博物馆及重要历史遗产均与公共文化生活有关。国家任务为资源制度投入提供方向，但不直接规定每个个人项目的补贴数额，也不把公共服务单位变成国家权力机关。\n\n生活例子：甲认为图书馆与宪法完全无关，乙可解释国家任务。","keyPoints":["发展教育文化事业属于宪法国家任务","国家→建设教育文化事业→公民享有相应发展条件","公共文化制度建设与个人即时请求无限补贴不同"],"pitfalls":["宪法完全不涉及教育和文化事业","辨析：公共文化制度建设与个人即时请求无限补贴不同"],"articles":["《宪法》第十九条","《宪法》第二十二条"]},{"id":"ch6-s5","title":"6.5 社会保障环境","plain":"困难时有保障日常环境受保护需要制度。","body":"先建直觉：困难时有保障日常环境受保护需要制度。\n\n再上定义：国家建立健全与经济发展水平相适应的社会保障制度，保护改善生活生态环境、防治污染；具体待遇排放标准要看具体法律制度。\n\n一条关系线：国家→建设保障保护环境→改善公民生活条件。\n\n术语解释：制度任务与特定个人的具体给付请求不同。\n\n对比：宪法方向不直接给出每人的统一养老金金额。 社会保障任务要求制度建设与经济发展水平相适应，环境任务则要求保护改善生活和生态环境、防治污染公害，并组织鼓励植树造林。两类任务都需要具体制度实施，但落实对象不同，不能将社会给付和污染治理混为一类请求。个人待遇、排放标准或具体责任须继续查相应规范，不能从原则条款直接计算。\n\n生活例子：甲问每月养老金数额，乙须另核具体制度。","keyPoints":["宪法保障任务不直接确定所有人同额养老金","国家→建设保障保护环境→改善公民生活条件","宪法方向不直接给出每人的统一养老金金额"],"pitfalls":["宪法已规定全国每人完全相同的养老金具体金额","辨析：宪法方向不直接给出每人的统一养老金金额"],"articles":["《宪法》第十四条","《宪法》第二十六条"]}],"quiz":[{"type":"single","options":["公有制与共同发展是否矛盾","生产资料制度与个人生活用品","所有权与依法使用权的不同","基本经济制度与分配制度的不同"],"answer":"B","explain":"讨论对象不同，不能将经济制度基础机械套用为所有消费物的归属规则。","sectionId":"ch6-s1","articles":["《宪法》第六条"],"tags":["经济制度基础","综合检验"],"q":"甲把生产资料公有制理解为乙的衣服必须上交，主要混淆什么？","id":"quiz-ch6-001","difficulty":2},{"type":"single","options":["公有制为主体与依法发展非公有制相结合","非公有制发展必须取消公有制","保护私营经济就能拒绝一切法律","公有制主体意味着私营经济一概违宪"],"answer":"A","explain":"两条共同构成所有制制度框架，主体地位与合法共同发展并不矛盾。","sectionId":"ch6-s2","articles":["《宪法》第六条","《宪法》第十一条"],"tags":["公有制与非公有制","综合检验"],"q":"同时理解第六条与第十一条，哪项更完整？","id":"quiz-ch6-002","difficulty":2},{"type":"single","options":["全部集体所有而无法律例外","全部国家所有而无任何例外","由使用人按占有事实取得私人所有","原则集体所有但法律规定国有的除外"],"answer":"D","explain":"第十条有明确例外结构，绝对化表述及私人归属说均不准确。","sectionId":"ch6-s3","articles":["《宪法》第十条","《宪法》第十三条"],"tags":["财产权与土地","综合检验"],"q":"农村和城市郊区土地归属怎样表述更准确？","id":"quiz-ch6-003","difficulty":2},{"type":"single","options":["它们属于国家权力机关的常设组织","它们一般承担司法审判职责","它们关联国家文化事业任务","它们负责解释宪法文化条款"],"answer":"C","explain":"宪法任务覆盖相应文化事业，但公共服务单位不因服务公共利益就有国家最高权力。","sectionId":"ch6-s4","articles":["《宪法》第十九条","《宪法》第二十二条"],"tags":["教育文化事业","综合检验"],"q":"图书馆和博物馆建设为什么可进入宪法课堂？","id":"quiz-ch6-004","difficulty":2},{"type":"single","options":["后者无需任何合法依据","前者给方向，后者须查相应具体规范","前者使所有标准失效","前者直接列完所有数值"],"answer":"B","explain":"任务与细则层次不同，不能把原则当数值标准或取消细则依据。","sectionId":"ch6-s5","articles":["《宪法》第十四条","《宪法》第二十六条"],"tags":["社会保障环境","综合检验"],"q":"环境宪法任务与具体排放标准是什么关系？","id":"quiz-ch6-005","difficulty":2}]},{"id":"ch7","title":"第七章 公民基本权利","summary":"本章学习公民基本权利，依次掌握公民与平等、政治权利自由、宗教信仰自由、人身自由、人格住宅通信。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch7-s1","title":"7.1 公民与平等","plain":"不能只凭出身身份任意差别对待。","body":"先建直觉：不能只凭出身身份任意差别对待。\n\n再上定义：具有中国国籍的人是中国公民，公民法律面前一律平等；教材理论强调平等不是所有场景完全同样处理，须审查差别理由及相关性。\n\n一条关系线：国家机关→平等适用法律保障人权→公民依法受保护。\n\n术语解释：公民按国籍识别，人民是政治概念。\n\n对比：合理保护未成年人不等于任意歧视，也不否认平等。 公民身份按国籍识别，不以成年、财产或投票资格为一般前提。平等要求避免无正当理由的差别待遇，但不抹去与规则目的有关的实际差异。对儿童的特别保护与对相同条件者平等适法，可以同时成立。教材分析常先选比较对象，再看差别的理由和相关性，避免把所有不同处理都称为歧视或都称为合理。\n\n生活例子：甲认为儿童特别保护必然违法平等，乙应审查相关差异。","keyPoints":["法律面前平等不等于一切情况都完全相同对待","国家机关→平等适用法律保障人权→公民依法受保护","合理保护未成年人不等于任意歧视，也不否认平等"],"pitfalls":["任何差别对待无论理由如何都必然违反平等","辨析：合理保护未成年人不等于任意歧视，也不否认平等"],"articles":["《宪法》第三十三条"]},{"id":"ch7-s2","title":"7.2 政治权利自由","plain":"投票和公共表达是不同参与方式。","body":"先建直觉：投票和公共表达是不同参与方式。\n\n再上定义：宪法规定符合条件公民的选举权被选举权以及言论出版集会结社游行示威自由，行使须依法且不损害他人合法权利。\n\n一条关系线：公民→选举与表达；国家机关→依法保障。\n\n术语解释：选举权不同于言论自由，保护对象不同。\n\n对比：普通公民表达意见不必先取得人大代表身份。 选举权与政治自由都是公民参与政治生活的重要方面，但行为对象不同。投票涉及代表产生及选举条件，言论自由涉及意见表达；表达公共意见不以当选代表为前提。第三十五条列举六项自由，行使时仍需兼顾其他合法权利。表达受保护与表达方式受到规范评价，是能够同时存在的两个问题。\n\n生活例子：甲称只有代表能谈公共事务，乙应指出表达自由主体。","keyPoints":["公共意见表达不以当选人大代表为前提","公民→选举与表达；国家机关→依法保障","普通公民表达意见不必先取得人大代表身份"],"pitfalls":["只有人大代表享有宪法言论自由","辨析：普通公民表达意见不必先取得人大代表身份"],"articles":["《宪法》第三十四条","《宪法》第三十五条","《宪法》第五十一条"]},{"id":"ch7-s3","title":"7.3 宗教信仰自由","plain":"既不能强迫信也不能强迫不信。","body":"先建直觉：既不能强迫信也不能强迫不信。\n\n再上定义：宪法保障宗教信仰自由，禁止强制信教不信教和歧视，保护正常宗教活动，不得利用宗教破坏秩序损害健康妨碍教育制度。\n\n一条关系线：国家机关团体个人→不得强迫歧视→公民依法选择。\n\n术语解释：信仰与以宗教名义进行的所有外部行为不同。\n\n对比：保护信仰不意味着认可所有相关外部行为，不信教者也受保护。 宗教信仰自由同时保护信教与不信教的选择，禁止强制和相应歧视。对正常宗教活动的保护，不等于对一切宗教名义行为无条件认可；破坏秩序、损害健康和妨碍国家教育制度的行为具有宪法明确边界。宗教团体与宗教事务不受外国势力支配，也是该条内容，不能只学个人选择而忽略制度要求。\n\n生活例子：甲强迫乙信教，乙应知自由包含不受强制和不得歧视。","keyPoints":["不信教者也受宗教信仰自由保护","国家机关团体个人→不得强迫歧视→公民依法选择","保护信仰不意味着认可所有相关外部行为，不信教者也受保护"],"pitfalls":["宗教信仰自由从不保护不信教者","辨析：保护信仰不意味着认可所有相关外部行为，不信教者也受保护"],"articles":["《宪法》第三十六条"]},{"id":"ch7-s4","title":"7.4 人身自由","plain":"怀疑一个人不能成为任意拘禁搜身的理由。","body":"先建直觉：怀疑一个人不能成为任意拘禁搜身的理由。\n\n再上定义：宪法保护人身自由，禁止非法拘禁搜身；逮捕须经检察院批准决定或法院决定并由公安执行，具体措施须另核程序法。\n\n一条关系线：检察院法院→依法批准决定；公安→执行逮捕；公民→自由受保护。\n\n术语解释：逮捕是特定措施，不与所有限制自由行为相同。\n\n对比：人身自由保护不是禁止任何合法限制，也不能把所有措施套入逮捕规则。 人身自由规则既保护公民免受非法拘禁搜查，也为逮捕配置严格的批准决定与执行结构。检察院批准或决定、法院决定和公安执行属于不同作用，不宜把整个过程写成单一机关无条件决定。私人讨债或怀疑他人不产生拘禁权。逮捕与拘留等措施还须分开，不能用一个措施的宪法框架代替所有程序细节。\n\n生活例子：甲因欠款把乙锁起，私人讨债不是合法拘禁依据。","keyPoints":["私人讨债不构成非法拘禁他人的正当依据","检察院法院→依法批准决定；公安→执行逮捕；公民→自由受保护","人身自由保护不是禁止任何合法限制，也不能把所有措施套入逮捕规则"],"pitfalls":["只要他人欠钱就可以把他锁到还钱","辨析：人身自由保护不是禁止任何合法限制，也不能把所有措施套入逮捕规则"],"articles":["《宪法》第三十七条"]},{"id":"ch7-s5","title":"7.5 人格住宅通信","plain":"尊严家门和通信保护不同生活边界。","body":"先建直觉：尊严家门和通信保护不同生活边界。\n\n再上定义：宪法保护人格尊严住宅及通信自由秘密，禁止侮辱诽谤诬告、非法搜查侵入住宅和非法侵犯通信；通信检查例外有特定目的主体程序限制。\n\n一条关系线：国家机关及个人→遵守权利边界→公民尊严生活受保障。\n\n术语解释：人格重基本尊重，住宅重空间，通信重信息联系。\n\n对比：法定例外不是任何机关为工作方便随意检查许可。 人格尊严、住宅和通信分别保护人的基本尊重、私人生活空间与信息联系。同一事件可能同时触及多个保护对象，不能机械地只认一个权利。通信检查例外需结合国家安全或追查刑事犯罪目的、法定机关和法律程序理解；住宅规则禁止非法侵入搜查，机关名义本身不能证明行为合法。\n\n生活例子：甲称单位能以方便为由查乙通信，乙应知检查须法定机关和程序。","keyPoints":["通信检查例外不能扩张为任何单位任意检查","国家机关及个人→遵守权利边界→公民尊严生活受保障","法定例外不是任何机关为工作方便随意检查许可"],"pitfalls":["任何单位都能仅以工作方便为由检查公民通信","辨析：法定例外不是任何机关为工作方便随意检查许可"],"articles":["《宪法》第三十八条","《宪法》第三十九条","《宪法》第四十条"]}],"quiz":[{"type":"single","options":["不能仅凭身份偏见任意施加不利待遇","所有案件结论必须完全一样","禁止一切针对特殊困难的帮助","允许工作人员按私人关系执法"],"answer":"A","explain":"平等反对无理由歧视，既不抹平事实差异也不排除合理保护。","sectionId":"ch7-s1","articles":["《宪法》第三十三条"],"tags":["公民与平等","综合检验"],"q":"法律面前平等与人权保障共同要求什么？","id":"quiz-ch7-001","difficulty":2},{"type":"single","options":["只看观点是否受欢迎","只看表达者财产多寡","凡涉及公共事务就完全不受约束","同时考察表达保护和不侵害他人合法权利"],"answer":"D","explain":"自由保护与边界须共同分析，欢迎程度财产不替代规范审查。","sectionId":"ch7-s2","articles":["《宪法》第三十四条","《宪法》第三十五条","《宪法》第五十一条"],"tags":["政治权利自由","综合检验"],"q":"分析公共表达与他人权益冲突，哪项处理更准确？","id":"quiz-ch7-002","difficulty":2},{"type":"single","options":["只要甲信教即可任意区别","宗教条款只约束外国人","不信教者也受不得歧视的保护","不信教者没有任何自由"],"answer":"C","explain":"不得歧视保护两类公民，并非给信教者侵害他人选择的特权。","sectionId":"ch7-s3","articles":["《宪法》第三十六条"],"tags":["宗教信仰自由","综合检验"],"q":"甲因乙不信教而歧视乙，宪法评价重点是什么？","id":"quiz-ch7-003","difficulty":2},{"type":"single","options":["当然行使公安逮捕执行职权","非法限制人身自由","依私人所有权取得拘禁权限","因存在怀疑便免于程序审查"],"answer":"B","explain":"怀疑或私人经营需求不产生拘禁权限，更不使商店成为公检法机关。","sectionId":"ch7-s4","articles":["《宪法》第三十七条"],"tags":["人身自由","综合检验"],"q":"私人商店怀疑顾客偷物，便自行将其长时间锁起，哪项最应警惕？","id":"quiz-ch7-004","difficulty":2},{"type":"single","options":["不能，还须核对权限依据和程序","能够，机关名义已证明全部程序","能够，目的正当即无需权限","能够，受影响者未反对即总合法"],"answer":"A","explain":"禁止非法搜查的限定要求实质合法性审查，名称人数面积都不足以证明合法。","sectionId":"ch7-s5","articles":["《宪法》第三十八条","《宪法》第三十九条","《宪法》第四十条"],"tags":["人格住宅通信","综合检验"],"q":"以公权力名义搜查住宅，能否仅凭名义就认定合法？","id":"quiz-ch7-005","difficulty":2}]},{"id":"ch8","title":"第八章 权利保障与基本义务","summary":"本章学习权利保障与基本义务，依次掌握社会经济权利、教育文化权利、监督与救济、权利限制边界、基本义务。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch8-s1","title":"8.1 社会经济权利","plain":"工作休息和困难帮助解决不同生活需要。","body":"先建直觉：工作休息和困难帮助解决不同生活需要。\n\n再上定义：宪法规定劳动权利义务、劳动者休息权及年老疾病丧失劳动能力时物质帮助权，具体就业待遇由法律制度落实。\n\n一条关系线：国家→创造条件提供保障→公民劳动者依法享权。\n\n术语解释：休息权的宪法主体是劳动者，物质帮助有相应生活状况前提。\n\n对比：劳动权不等于国家按每人偏好安排任意指定岗位。 劳动既是权利也是义务，休息权的宪法表述主体是劳动者。物质帮助权针对年老、疾病或者丧失劳动能力等情形，相关社会保险救济医疗卫生制度为其实现创造条件。不同权利对应不同生活风险，不能一概改写成人人无条件同额领取。劳动就业保障也不等于国家必须按每个人指定立即安排任意岗位。\n\n生活例子：甲要求国家立刻安排指定工作，乙应区分权利与具体岗位请求。","keyPoints":["劳动权不等于可要求国家提供任意指定职位","国家→创造条件提供保障→公民劳动者依法享权","劳动权不等于国家按每人偏好安排任意指定岗位"],"pitfalls":["劳动权要求国家满足每人对任意指定职位的要求","辨析：劳动权不等于国家按每人偏好安排任意指定岗位"],"articles":["《宪法》第四十二条","《宪法》第四十三条","《宪法》第四十五条"]},{"id":"ch8-s2","title":"8.2 教育文化权利","plain":"上学涉及个人发展和社会共同基础。","body":"先建直觉：上学涉及个人发展和社会共同基础。\n\n再上定义：受教育既是权利也是义务，公民有科学研究文学艺术创作及其他文化活动自由，国家鼓励帮助有益于人民的创造性工作。\n\n一条关系线：国家→发展教育保障文化自由→公民学习创造。\n\n术语解释：权利义务复合指同一领域兼有保护与责任。\n\n对比：受教育义务不等于无限就读所有学校，文化自由不等于作品必获资助。 受教育的双重属性说明个人发展既受到保护，也承担相应学习责任；不能据此推导无限期在所有学校就读的义务。科学研究、文学艺术创作和其他文化活动的自由，重在保障创造活动空间。国家对有益于人民的创造性工作给予鼓励帮助，具体支持措施与个案给付仍需制度落实，而非所有作品自动取得同额资助。\n\n生活例子：甲说受教育只有义务，乙应指出宪法兼列权利。","keyPoints":["受教育具有权利义务双重属性","国家→发展教育保障文化自由→公民学习创造","受教育义务不等于无限就读所有学校，文化自由不等于作品必获资助"],"pitfalls":["受教育在宪法上只有义务没有权利","辨析：受教育义务不等于无限就读所有学校，文化自由不等于作品必获资助"],"articles":["《宪法》第四十六条","《宪法》第四十七条"]},{"id":"ch8-s3","title":"8.3 监督与救济","plain":"机关做错事也要有表达和纠正渠道。","body":"先建直觉：机关做错事也要有表达和纠正渠道。\n\n再上定义：公民可批评建议，对违法失职申诉控告检举，有关机关须查明负责处理，不得压制报复，受侵害损失可依法取得赔偿；不得捏造歪曲事实诬告。\n\n一条关系线：公民→提出监督诉求；机关→负责处理不得报复。\n\n术语解释：批评建议重意见，控告检举指向违法失职，救济重纠正侵害。\n\n对比：监督权不许可编造事实，申诉也不等于所有请求必获支持。 公民可对机关和工作人员批评建议，也可针对违法失职提出申诉、控告和检举。机关负有查清事实和负责处理的职责，并不得压制打击报复。监督需有事实边界，捏造歪曲事实进行诬告不受保护；处理结果不完全符合申请者意愿也不自动等于报复。依法赔偿另有条件，不能将宪法权利写成任意金额请求。\n\n生活例子：甲如实反映失职，不应仅因措辞尖锐便认定诬告。","keyPoints":["监督权不允许捏造歪曲事实诬告陷害","公民→提出监督诉求；机关→负责处理不得报复","监督权不许可编造事实，申诉也不等于所有请求必获支持"],"pitfalls":["只要声称监督就可任意编造违法事实","辨析：监督权不许可编造事实，申诉也不等于所有请求必获支持"],"articles":["《宪法》第四十一条"]},{"id":"ch8-s4","title":"8.4 权利限制边界","plain":"一个人自由可能与另一个人的权利相遇。","body":"先建直觉：一个人自由可能与另一个人的权利相遇。\n\n再上定义：行使权利不得损害国家社会集体利益及他人合法自由权利；教材理论要求限制有依据正当目的适当边界，不能将抽象利益变为无限授权。\n\n一条关系线：国家机关→依法协调冲突→公民合法行使自由。\n\n术语解释：权利边界与比例性是分析工具，不是新增任意限制权。\n\n对比：权利非绝对不意味着国家机关权力无边界。 第五十一条协调自由权利与国家、社会、集体利益及其他公民合法权益。教材上的限制分析仍需追问依据、目的和手段边界，不能因权利非绝对便推导权力无限。处理冲突应明确双方受保护的利益和实际影响，而非只重复其中一方口号。目的正当与措施适当是不同问题，不能用前者省略后者。\n\n生活例子：甲称公共利益能证明任何限制，乙应追问依据和必要范围。","keyPoints":["权利有边界不意味着机关可任意限制","国家机关→依法协调冲突→公民合法行使自由","权利非绝对不意味着国家机关权力无边界"],"pitfalls":["只要说公共利益任何限制就自动合法","辨析：权利非绝对不意味着国家机关权力无边界"],"articles":["《宪法》第五十一条","《宪法》第五条"]},{"id":"ch8-s5","title":"8.5 基本义务","plain":"共同生活也有依法承担的责任。","body":"先建直觉：共同生活也有依法承担的责任。\n\n再上定义：公民有维护统一民族团结、守宪守法、维护安全荣誉利益、依法服兵役参加民兵和依法纳税等义务，劳动受教育另有双重属性。\n\n一条关系线：公民→依法履行义务；机关→依法明确具体要求。\n\n术语解释：依法纳税不是任意收费，兵役义务须依具体法律条件。\n\n对比：基本义务不直接等于具体处罚，责任仍需法律依据。 基本义务包括守宪守法、维护统一民族团结和国家安全荣誉利益，以及依法纳税、服兵役参加民兵组织等。劳动与受教育还有权利义务双重属性。宪法义务提供根本要求，具体承担条件和责任须依法落实；例如纳税不同于任意收费，兵役义务也不能被解释为任何人均可要求所有公民立即服现役。\n\n生活例子：甲把任意摊派称作税，乙应核对法定依据。","keyPoints":["依法纳税不等于接受一切任意收费","公民→依法履行义务；机关→依法明确具体要求","基本义务不直接等于具体处罚，责任仍需法律依据"],"pitfalls":["工作人员临时索取的钱都属于法定税收","辨析：基本义务不直接等于具体处罚，责任仍需法律依据"],"articles":["《宪法》第五十二条","《宪法》第五十三条","《宪法》第五十四条","《宪法》第五十五条","《宪法》第五十六条","《宪法》第四十二条","《宪法》第四十六条"]}],"quiz":[{"type":"single","options":["劳动权的具体岗位请求","社会物质帮助权","文化创作自由","休息权"],"answer":"D","explain":"第四十三条将休息与工作时间休假相联系。","sectionId":"ch8-s1","articles":["《宪法》第四十二条","《宪法》第四十三条","《宪法》第四十五条"],"tags":["社会经济权利","综合检验"],"q":"国家规定工作时间和休假制度，主要落实哪项权利？","id":"quiz-ch8-001","difficulty":2},{"type":"single","options":["用公共任务完全取代个人受教育权","用个人选择完全排除公共教育责任","连接公共制度供给与个人发展保障","将国家事业条款直接等同全部个人入学细则"],"answer":"C","explain":"两个层次相互支撑，但不取消个人保障也不改机关性质。","sectionId":"ch8-s2","articles":["《宪法》第四十六条","《宪法》第四十七条"],"tags":["教育文化权利","综合检验"],"q":"将教育国家任务与个人受教育权放在一起学习，有何意义？","id":"quiz-ch8-002","difficulty":2},{"type":"single","options":["能，凡不同意见都是报复","不能，应核对事实、处理依据及行为性质","能，只看申请人主观不满","能，只看受理机关级别"],"answer":"B","explain":"监督保障不等于预设申请者必胜，报复应结合实际行为事实判别。","sectionId":"ch8-s3","articles":["《宪法》第四十一条"],"tags":["监督与救济","综合检验"],"q":"申诉未获得申请人希望的全部结果，能否据此直接断言属于打击报复？","id":"quiz-ch8-003","difficulty":2},{"type":"single","options":["审视冲突利益并考察是否有更适当边界","只要甲不满就全盘取消","只要乙提自由就拒绝一切协调","仅按双方职业地位决定"],"answer":"A","explain":"权利冲突需要规范协调，不是任一方口号或职业高低决定结果。","sectionId":"ch8-s4","articles":["《宪法》第五十一条","《宪法》第五条"],"tags":["权利限制边界","综合检验"],"q":"甲为保护安宁要求彻底取消乙所有公共表达，哪项分析最妥？","id":"quiz-ch8-004","difficulty":2},{"type":"single","options":["全国人大常委会的修宪权限","国家主席公布法律职权","居民委员会的审判权","第五十三条的公民义务"],"answer":"D","explain":"这些为第五十三条列举义务，不能转写为其他机关职权。","sectionId":"ch8-s5","articles":["《宪法》第五十二条","《宪法》第五十三条","《宪法》第五十四条","《宪法》第五十五条","《宪法》第五十六条","《宪法》第四十二条","《宪法》第四十六条"],"tags":["基本义务","综合检验"],"q":"遵守宪法法律、保守国家秘密、爱护公共财产，可归入哪项内容？","id":"quiz-ch8-005","difficulty":2}]},{"id":"ch9","title":"第九章 中央国家机构上","summary":"本章学习中央国家机构上，依次掌握全国人大、全国人大常委会、国家主席、国务院、中央军委。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch9-s1","title":"9.1 全国人大","plain":"国家重大制度事项要由法定机关决定。","body":"先建直觉：国家重大制度事项要由法定机关决定。\n\n再上定义：全国人大是最高国家权力机关，修改宪法监督实施、制定修改基本法律、选举决定有关人选、审查批准计划预算等依法履职。\n\n一条关系线：全国人大→产生监督有关中央机关→决定重大事项。\n\n术语解释：机关整体职权不同于代表个人履职权利。\n\n对比：最高权力地位不意味着每位代表单独拥有整体全部权限。 全国人大作为最高国家权力机关，其职权涉及宪法、基本法律、重要人事及计划预算等重大事项。机关整体决定与代表个人履职必须区分，不能把参加表决的权利写成个人独立选举任免或修宪。全国人大还可改变撤销常委会不适当的决定，体现其与常设机关之间的制度联系，而非两个互不相关机关并列。\n\n生活例子：甲称自己可个人修宪，乙应指出机关与个人之别。","keyPoints":["修改宪法不是代表个人可单独完成的行为","全国人大→产生监督有关中央机关→决定重大事项","最高权力地位不意味着每位代表单独拥有整体全部权限"],"pitfalls":["任何代表都可以个人决定修改宪法","辨析：最高权力地位不意味着每位代表单独拥有整体全部权限"],"articles":["《宪法》第五十七条","《宪法》第六十二条"]},{"id":"ch9-s2","title":"9.2 全国人大常委会","plain":"人大闭会仍需常设机关持续履职。","body":"先建直觉：人大闭会仍需常设机关持续履职。\n\n再上定义：全国人大常委会是全国人大常设机关，解释宪法监督实施、制定修改权限内法律、监督有关中央机关并依法行使撤销权。\n\n一条关系线：全国人大→其常委会；常委会→依法监督相关机关。\n\n术语解释：常设机关不是另一个无关的最高权力机关。\n\n对比：解释宪法与修改宪法不同，常委会不能替代全国人大全部权限。 常委会在宪法中具有常设机关地位，并有独立列举的职权。全国人大闭会期间，它可以对全国人大制定的法律作部分补充修改，但不得抵触该法基本原则。这里闭会主体是全国人大，不是常委会；部分修改也不同于任意重写。解释宪法、解释法律及监督有关中央机关，须按对象与权限分别理解。\n\n生活例子：甲把最终独立修宪交常委会，乙应区分权限。","keyPoints":["全国人大常委会具有解释宪法职权","全国人大→其常委会；常委会→依法监督相关机关","解释宪法与修改宪法不同，常委会不能替代全国人大全部权限"],"pitfalls":["全国人大常委会可独立替代全国人大最终完成修宪","辨析：解释宪法与修改宪法不同，常委会不能替代全国人大全部权限"],"articles":["《宪法》第五十七条","《宪法》第六十七条","《宪法》第六十二条"]},{"id":"ch9-s3","title":"9.3 国家主席","plain":"公布法律与作出法律决定是不同环节。","body":"先建直觉：公布法律与作出法律决定是不同环节。\n\n再上定义：国家主席根据全国人大及其常委会决定公布法律、任免相关人员、发布相应命令等，本节重点理解决定与公布任免的衔接。\n\n一条关系线：全国人大及常委会→作相应决定→主席依宪法公布任免。\n\n术语解释：公布法律不等于自由重写法律。\n\n对比：国家主席不是最高国家行政机关，公布不同于个人制定。 国家主席依全国人大及其常委会有关决定履行公布法律、任免相关人员和发布相应命令等职责。公布体现法定决定与国家职务行为的衔接，不产生自行删改已通过条文的权限。发布特赦令和作出特赦决定也需区分行为主体与环节。国家主席职权不能与国务院最高行政机关定位混同。\n\n生活例子：甲称公布时可任意改写条文，乙应指出其根据决定履职。","keyPoints":["主席公布法律不能理解为可任意改写通过文本","全国人大及常委会→作相应决定→主席依宪法公布任免","国家主席不是最高国家行政机关，公布不同于个人制定"],"pitfalls":["国家主席公布时可随意删除已通过的法律条文","辨析：国家主席不是最高国家行政机关，公布不同于个人制定"],"articles":["《宪法》第八十条","《宪法》第八十五条"]},{"id":"ch9-s4","title":"9.4 国务院","plain":"法律政策需要全国行政系统落实。","body":"先建直觉：法律政策需要全国行政系统落实。\n\n再上定义：国务院即中央人民政府，是最高国家权力机关的执行机关及最高国家行政机关，并在宪法制度中接受监督。\n\n一条关系线：全国人大及常委会→依法监督；国务院→依法行政。\n\n术语解释：执行机关说明关系，行政机关说明职能。\n\n对比：最高行政机关不同于最高权力机关或审判机关。 国务院即中央人民政府，执行机关定位说明它与最高权力机关的关系，最高行政机关定位说明其职能性质。依法开展行政工作与接受监督并不矛盾，执行也不是说它没有自身法定职责。中央国家机构包括多种性质的机关，不能因名称带中央或国家便一律划为国务院的普通行政部门。\n\n生活例子：甲称国务院是最高国家权力机关，乙应区分性质。","keyPoints":["国务院是最高国家行政机关","全国人大及常委会→依法监督；国务院→依法行政","最高行政机关不同于最高权力机关或审判机关"],"pitfalls":["国务院与全国人大是同一个最高国家权力机关","辨析：最高行政机关不同于最高权力机关或审判机关"],"articles":["《宪法》第八十五条","《宪法》第三条","《宪法》第六十七条"]},{"id":"ch9-s5","title":"9.5 中央军委","plain":"武装力量需要统一领导和明确负责结构。","body":"先建直觉：武装力量需要统一领导和明确负责结构。\n\n再上定义：中央军委领导全国武装力量，由主席副主席若干人委员若干人组成，实行主席负责制，不能仅凭名称把它当国务院普通部门。\n\n一条关系线：中央军委→领导武装力量；全国人大常委会→依法履行相关监督职权。\n\n术语解释：主席负责制有特定宪法依据，不是法外个人权力。\n\n对比：不同委员会负责制不能只看名称推定。 中央军委领导全国武装力量，实行主席负责制，任期与全国人大每届任期相同。其组成中的副主席和委员使用若干人的表述，不能因此编造固定法定人数。不同委员会可能有不同负责制度，名称相似不足以推定制度相同；军事领导、行政管理与权力机关决定监督也应在机构图中分别标示。\n\n生活例子：甲见委员会三字就称均同一种负责制，乙应核对专门条文。","keyPoints":["中央军委实行主席负责制","中央军委→领导武装力量；全国人大常委会→依法履行相关监督职权","不同委员会负责制不能只看名称推定"],"pitfalls":["名称含委员会的机关必然都实行完全相同负责制","辨析：不同委员会负责制不能只看名称推定"],"articles":["《宪法》第九十三条","《宪法》第六十二条","《宪法》第六十七条"]}],"quiz":[{"type":"single","options":["最高行政机关与最高权力机关","最高审判机关与最高监察机关","最高权力机关与最高行政机关","常设权力机关与军事领导机关"],"answer":"C","explain":"两者虽有制度联系但性质不同，最高二字不能抹平具体定位。","sectionId":"ch9-s1","articles":["《宪法》第五十七条","《宪法》第六十二条"],"tags":["全国人大","综合辨析"],"q":"全国人大与国务院最准确的基本区分是哪项？","id":"quiz-ch9-001","difficulty":2},{"type":"single","options":["上下级政府行政领导","宪法规定的机关监督","法院上下级审判监督","人民与人大之间选举联系"],"answer":"B","explain":"第六十七条规定中央机关监督结构，不是合同雇佣或自治团体关系。","sectionId":"ch9-s2","articles":["《宪法》第五十七条","《宪法》第六十七条","《宪法》第六十二条"],"tags":["全国人大常委会","综合辨析"],"q":"常委会监督国务院中央军委国家监察委最高法最高检，属于什么关系？","id":"quiz-ch9-002","difficulty":2},{"type":"single","options":["混淆主席职权与国务院机构定位","混淆国家主席与全国人大常委会常设地位","混淆国家主席与中央军委军事领导职责","混淆国家主席公布与法院审判"],"answer":"A","explain":"第八十五条将最高行政机关定位于国务院，不能因主席国家职务名称而互换。","sectionId":"ch9-s3","articles":["《宪法》第八十条","《宪法》第八十五条"],"tags":["国家主席","综合辨析"],"q":"将国家主席称为最高国家行政机关，主要错在哪里？","id":"quiz-ch9-003","difficulty":2},{"type":"single","options":["国务院仍是最高国家行政机关","国务院因此变成常委会内部部门","国务院因此变成国家审判机关","国务院因此取得宪法修改终决权"],"answer":"A","explain":"监督关系不改变机关基本性质；行政职能、组织地位与监督机制应分别把握。","sectionId":"ch9-s4","articles":["《宪法》第八十五条","《宪法》第三条","《宪法》第六十七条"],"tags":["国务院","综合辨析"],"q":"全国人大常委会依法监督国务院工作，对国务院机构性质有何影响？","id":"quiz-ch9-004","difficulty":2},{"type":"single","options":["以委员会名称统一推定负责制","以所处层级统一推定负责制","逐一核对各机关专门规范","以成员人数推定负责制而不核规范"],"answer":"C","explain":"负责制源于特定规定，不取决于词尾、年龄或简称字数。","sectionId":"ch9-s5","articles":["《宪法》第九十三条","《宪法》第六十二条","《宪法》第六十七条"],"tags":["中央军委","综合辨析"],"q":"比较不同委员会的负责制，最可靠方法是什么？","id":"quiz-ch9-005","difficulty":2}]},{"id":"ch10","title":"第十章 中央机构下与司法监察","summary":"本章学习中央机构下与司法监察，依次掌握监察委员会、人民法院、人民检察院、监察司法相互关系、宪法职责与诉讼。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch10-s1","title":"10.1 监察委员会","plain":"监督公权力不等于直接审判定罪。","body":"先建直觉：监督公权力不等于直接审判定罪。\n\n再上定义：各级监察委员会是国家监察机关，依法独立行使监察权，办职务违法犯罪案件与审判检察机关执法部门配合制约。\n\n一条关系线：人大→产生监督监察机关；监察机关↔相关机关依法配合制约。\n\n术语解释：监察权不同于审判权检察权。\n\n对比：监察委员会不是法院，不能用监察职能替代审判。 监察委员会依法独立行使监察权，并在办理职务违法犯罪案件时与审判、检察机关及执法部门配合制约。独立以依法为前提，不意味着没有法律边界，也不意味着取消人大制度中的监督联系。监察权不同于审判权，办理相关案件并不能直接写成作出法院式刑事判决，更不能把监察与检察因文字相近而合并。\n\n生活例子：甲称监察决定等于法院刑事判决，乙应区分职能。","keyPoints":["监察职能与法院审判职能不同","人大→产生监督监察机关；监察机关↔相关机关依法配合制约","监察委员会不是法院，不能用监察职能替代审判"],"pitfalls":["监察委员会就是人民法院另一名称","辨析：监察委员会不是法院，不能用监察职能替代审判"],"articles":["《宪法》第一百二十三条","《宪法》第一百二十七条","《宪法》第三条"]},{"id":"ch10-s2","title":"10.2 人民法院","plain":"争议裁判须由有审判职权的机关处理。","body":"先建直觉：争议裁判须由有审判职权的机关处理。\n\n再上定义：法院是国家审判机关，不能据此推出其有普遍撤销法律或一般宪法审查权，宪法解释监督另有职责配置。\n\n一条关系线：人大→产生监督法院；法院→依法审判保障当事人权利。\n\n术语解释：审判与合宪性审查不是同一权力。\n\n对比：法院审判定位不同于全国人大常委会解释宪法职权。 法院的审判机关地位回答其基本职能，而非赋予一切监督宪法的权限。个案裁判和一般性撤销国家法律不是同一行为，不能用前者直接推出后者。人大制度中的监督联系与法院依法审判可以并存，但监督也不是由外部机关包办每一个裁判。学习审判制度需同时保持机关性质与具体职权边界。\n\n生活例子：甲要求普通法院一般性撤销全国法律，乙应指出不得作此权限推定。","keyPoints":["不能从审判机关定位推定法院有普遍宪法审查权","人大→产生监督法院；法院→依法审判保障当事人权利","法院审判定位不同于全国人大常委会解释宪法职权"],"pitfalls":["我国所有法院都可一般性撤销全国人大制定的法律","辨析：法院审判定位不同于全国人大常委会解释宪法职权"],"articles":["《宪法》第一百二十八条","《宪法》第六十七条","《宪法》第三条"]},{"id":"ch10-s3","title":"10.3 人民检察院","plain":"法律监督与最终审判不是同一职责。","body":"先建直觉：法律监督与最终审判不是同一职责。\n\n再上定义：检察院是国家法律监督机关，依法独立行使检察权，不受行政机关社会团体个人干涉；具体权限由法律细化。\n\n一条关系线：人大→产生监督检察机关；检察机关→依法行使检察权。\n\n术语解释：检察与监察字近但机关性质不同。\n\n对比：检察院既不是法院也不是监察委员会。 检察院作为法律监督机关，依法独立行使检察权，具有不同于审判与监察的宪法定位。独立不等于法外，不受特定主体干涉也不等于取消人大监督。具体监督方式和案件职能需要法律细化，不能从法律监督四字推断其可以替代所有机关处理所有事务。提出检察意见与法院最终裁判须区分。\n\n生活例子：甲称检察院负责作最终刑事判决，乙应辨明审判检察分工。","keyPoints":["人民检察院是国家法律监督机关","人大→产生监督检察机关；检察机关→依法行使检察权","检察院既不是法院也不是监察委员会"],"pitfalls":["检察院与监察委员会是同一国家机关","辨析：检察院既不是法院也不是监察委员会"],"articles":["《宪法》第一百三十四条","《宪法》第一百三十六条","《宪法》第一百二十八条"]},{"id":"ch10-s4","title":"10.4 监察司法相互关系","plain":"共同维护法治不意味着合为一个大办公室。","body":"先建直觉：共同维护法治不意味着合为一个大办公室。\n\n再上定义：监察机关办理职务违法犯罪案件与审判检察机关执法部门配合制约，法院检察院各有审判法律监督职能。\n\n一条关系线：监察机关↔法院检察院执法部门依法配合制约。\n\n术语解释：配合是衔接，制约防止错误，均不取消分工。\n\n对比：监察相关关系与刑事公检法关系有关联但主体范围不同。 机关之间的配合是依法衔接，制约是防止错误与权力失衡，并非一方取消另一方全部职能。职务违法犯罪场景中监察与有关机关的关系，与公检法刑事案件关系相联系，却不能视为完全相同的主体组合。答题需要同时明确参与机关、案件场景及关系内容，避免只背配合制约而遗漏分工。\n\n生活例子：甲认为配合就是无条件认可他机关结论，乙应强调制约。","keyPoints":["互相配合不取消机关依法分工制约","监察机关↔法院检察院执法部门依法配合制约","监察相关关系与刑事公检法关系有关联但主体范围不同"],"pitfalls":["只要配合就不得相互制约","辨析：监察相关关系与刑事公检法关系有关联但主体范围不同"],"articles":["《宪法》第一百二十七条","《宪法》第一百二十八条","《宪法》第一百三十四条"]},{"id":"ch10-s5","title":"10.5 宪法职责与诉讼","plain":"知道机关分工不等于知道每个诉讼步骤。","body":"先建直觉：知道机关分工不等于知道每个诉讼步骤。\n\n再上定义：法院检察院公安机关办理刑事案件分工负责配合制约；逮捕有宪法结构，拘留期限证据规则等具体程序须另核诉讼法，本包不提供未经核验细数字。\n\n一条关系线：公安↔检察院↔法院：刑事案件依法分工配合制约。\n\n术语解释：职责是制度框架，诉讼程序是具体步骤。\n\n对比：宪法原则不能代替诉讼法，刑事关系不能无差别移用于所有民事案件。 宪法确定公检法办理刑事案件的基本职责关系，诉讼法则进一步规定案件如何推进及当事人如何参与。分工负责、配合与制约是成组要求，既非各自孤立也非只许合作。拘留期限、证据要求和救济步骤不能从组织条款直接推出；刑事案件框架也不能不加区分地移用于全部民事争议。\n\n生活例子：甲问拘留天数，乙不能凭机关定位猜数。","keyPoints":["宪法机关分工不能代替具体诉讼程序规则","公安↔检察院↔法院：刑事案件依法分工配合制约","宪法原则不能代替诉讼法，刑事关系不能无差别移用于所有民事案件"],"pitfalls":["宪法第一百四十条能直接给出一切诉讼期限","辨析：宪法原则不能代替诉讼法，刑事关系不能无差别移用于所有民事案件"],"articles":["《宪法》第一百四十条","《宪法》第三十七条"]}],"quiz":[{"type":"single","options":["依照法律独立行使，并在有关案件中配合制约","独立即排除所有机关监督","独立即不需要法定权限","独立即取消审判检察机关相关职能"],"answer":"A","explain":"独立行使以依法为前提，并不取消配合制约要求；其他项把独立无限扩大。","sectionId":"ch10-s1","articles":["《宪法》第一百二十三条","《宪法》第一百二十七条","《宪法》第三条"],"tags":["监察委员会","综合辨析"],"q":"对监察机关独立行使职权的理解，哪项保留了宪法的完整条件？","id":"quiz-ch10-001","difficulty":2},{"type":"single","options":["个案裁判职责与宪法监督机制不同","二者永远是完全同一行为","凡法院审案均自动修改宪法","凡审查规范都必须是民事调解"],"answer":"A","explain":"应按对象主体权限分析，不可由审案直接推出修宪或把审查一律写成调解。","sectionId":"ch10-s2","articles":["《宪法》第一百二十八条","《宪法》第六十七条","《宪法》第三条"],"tags":["人民法院","综合辨析"],"q":"法院审理具体纠纷与规范合宪性审查，应如何入门区分？","id":"quiz-ch10-002","difficulty":2},{"type":"single","options":["仅区分文书标题而无需区分权限","认为凡涉及犯罪都属同一裁判权","认为监督意见当然改变所有裁判","检察职能与审判裁判职能不同"],"answer":"D","explain":"职能是制度差别，文书外观和人员特征无法替代权限分析。","sectionId":"ch10-s3","articles":["《宪法》第一百三十四条","《宪法》第一百三十六条","《宪法》第一百二十八条"],"tags":["人民检察院","综合辨析"],"q":"甲认为检察机关提出意见就是法院最终判决，乙应怎样区分？","id":"quiz-ch10-003","difficulty":2},{"type":"single","options":["把法律效力高低误作审判层级","把宪法解释误作国家预算批准","忽略监察相关关系与公检法刑事关系的主体差别","把基本权利误作国家结构分类"],"answer":"C","explain":"两条有联系但主体列举场景不同，不可只记配合制约四字便抹平结构。","sectionId":"ch10-s4","articles":["《宪法》第一百二十七条","《宪法》第一百二十八条","《宪法》第一百三十四条"],"tags":["监察司法相互关系","综合辨析"],"q":"将第一百二十七条与第一百四十条直接视为完全相同主体范围，错在哪里？","id":"quiz-ch10-004","difficulty":2},{"type":"single","options":["两者都只取决于当事人喜好","前者确定基本分工，后者细化案件步骤条件","前者仅关文字美观","后者可以无视宪法"],"answer":"B","explain":"分层理解连接根本框架与具体规则，不等于具体程序可违宪或由喜好制定。","sectionId":"ch10-s5","articles":["《宪法》第一百四十条","《宪法》第三十七条"],"tags":["宪法职责与诉讼","综合辨析"],"q":"宪法职责与诉讼程序为什么不能混为一谈？","id":"quiz-ch10-005","difficulty":2}]},{"id":"ch11","title":"第十一章 地方国家机关","summary":"本章学习地方国家机关，依次掌握地方人大、地方人大常委会、地方政府、自治机关、中央地方关系。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch11-s1","title":"11.1 地方人大","plain":"本地重大事务也有法定权力机关。","body":"先建直觉：本地重大事务也有法定权力机关。\n\n再上定义：地方各级人大是地方国家权力机关，县级以上设常委会，不是地方政府下属部门。\n\n一条关系线：本地人民→地方人大→监督有关国家机关。\n\n术语解释：权力机关不同于泛称当地一切有权单位。\n\n对比：地方人大与地方政府性质不同，也不是自治组织。 地方人大是地方国家权力机关，县级以上设常委会，其性质与本级政府不同。地方二字标明层次，并不把它变成基层群众自治组织；人民二字也不表示政府与人大是同一个机关。理解本地机构应先区分权力与行政等职能，再画产生、负责、监督关系，而不是按日常办事地点判断隶属。\n\n生活例子：甲称县人大是县政府科室，乙应指出宪法定位。","keyPoints":["地方人大不是政府下属行政部门","本地人民→地方人大→监督有关国家机关","地方人大与地方政府性质不同，也不是自治组织"],"pitfalls":["地方人大只是本级政府普通办事科室","辨析：地方人大与地方政府性质不同，也不是自治组织"],"articles":["《宪法》第九十六条","《宪法》第三条","《宪法》第一百零五条"]},{"id":"ch11-s2","title":"11.2 地方人大常委会","plain":"闭会期间仍需持续监督和决定重大事项。","body":"先建直觉：闭会期间仍需持续监督和决定重大事项。\n\n再上定义：县级以上地方人大常委会讨论决定重大事项，监督本级政府监察委法院检察院，依法撤销有关决定和任免；乡镇人大不设常委会。\n\n一条关系线：地方常委会→依法监督本级一府一委两院。\n\n术语解释：一府一委两院分别指政府监察委法院检察院。\n\n对比：监督不替代法院逐案裁判，设置规则不能推至乡镇。 地方常委会依法讨论决定重大事项，监督本级政府监察委法院检察院，行使相应撤销与任免权限。县级以上设置这一层级条件不能推及乡镇。监督本级一府一委两院不等于替代其全部业务，也不把相关机关合并为常委会内部部门。掌握设置范围、监督对象与处理权限，才能避免把常设理解为无限。\n\n生活例子：甲给乡人大画常委会，乙应看县级以上条件。","keyPoints":["县级以上设置常委会不等于乡镇也设置","地方常委会→依法监督本级一府一委两院","监督不替代法院逐案裁判，设置规则不能推至乡镇"],"pitfalls":["我国所有乡镇人大都设本级人大常委会","辨析：监督不替代法院逐案裁判，设置规则不能推至乡镇"],"articles":["《宪法》第九十六条","《宪法》第一百零四条"]},{"id":"ch11-s3","title":"11.3 地方政府","plain":"地方行政事务也需依法向权力机关负责。","body":"先建直觉：地方行政事务也需依法向权力机关负责。\n\n再上定义：地方政府是本级国家权力机关执行机关和地方国家行政机关，实行相应行政首长负责制，不排除人大监督。\n\n一条关系线：本级人大常委会→依法监督；地方政府→行政履职。\n\n术语解释：首长负责是领导责任，不是超越法律特权。\n\n对比：行政负责制不同于取得本级人大全部权限。 地方政府既是本级权力机关的执行机关，也是地方行政机关，实行相应行政首长负责制。首长负责明确行政责任，不是拒绝人大监督或取得人大全部职权的理由。地方政府向本级人大负责报告，县级以上在人大会闭会时向相应常委会负责报告。负责制、报告关系与日常行政职能应分别表达。\n\n生活例子：甲说县长负责即可拒绝人大监督，乙应区分两条关系。","keyPoints":["首长负责制不排除政府向本级人大负责","本级人大常委会→依法监督；地方政府→行政履职","行政负责制不同于取得本级人大全部权限"],"pitfalls":["首长负责制使地方政府无需向人大报告工作","辨析：行政负责制不同于取得本级人大全部权限"],"articles":["《宪法》第一百零五条","《宪法》第一百一十条"]},{"id":"ch11-s4","title":"11.4 自治机关","plain":"依法自治同时仍承担一般地方机关职责。","body":"先建直觉：依法自治同时仍承担一般地方机关职责。\n\n再上定义：自治区自治州自治县人大政府是自治机关，同时行使一般地方机关职权和法定自治权，根据本地实际贯彻法律政策。\n\n一条关系线：自治地方人大政府→依法履行地方职权与自治权。\n\n术语解释：自治权有法定权限不是无限授权。\n\n对比：所有当地组织不都属于自治机关，民族乡也不是民族自治地方。 民族自治地方人大政府同时行使一般地方机关职权和依法配置的自治权。自治机关身份需同时符合地域和组织类型：不是当地法院检察院都成为自治机关，也不是民族乡当然属于同类自治地方。根据本地实际贯彻国家法律政策，应在法定权限内理解，不能把因地制宜改写为任意排除国家法律。\n\n生活例子：甲称自治县所有社会组织都有自治机关职权，乙应核对范围。","keyPoints":["自治机关兼有一般地方职权和法定自治权","自治地方人大政府→依法履行地方职权与自治权","所有当地组织不都属于自治机关，民族乡也不是民族自治地方"],"pitfalls":["自治地方任何社会组织都自动取得自治机关职权","辨析：所有当地组织不都属于自治机关，民族乡也不是民族自治地方"],"articles":["《宪法》第一百一十二条","《宪法》第一百一十五条","《宪法》第三十条"]},{"id":"ch11-s5","title":"11.5 中央地方关系","plain":"统一行动与因地制宜需要同时考虑。","body":"先建直觉：统一行动与因地制宜需要同时考虑。\n\n再上定义：中央统一领导下发挥地方积极性，地方政府对本级人大负责报告工作，县级以上闭会对常委会负责，同时对上一级行政机关负责并处国务院统一领导下。\n\n一条关系线：地方政府→本级人大及相应常委会；地方政府→上一级行政机关。\n\n术语解释：双重负责概括不同制度关系不是双重主权。\n\n对比：行政领导线不同于人大监督线，不可混画。 地方政府有横向与纵向两条负责关系：对本级人大以及符合条件时对本级常委会负责，也对上一级国家行政机关负责。全国地方政府都在国务院统一领导下。这些关系不是两种主权并立，人大监督与行政领导也不是同一条线。中央统一与地方主动积极性共同构成理解职权划分的原则。\n\n生活例子：甲把上级政府领导与人大监督混为一线，乙应区分机关性质。","keyPoints":["地方政府有对本级人大和上级行政机关的负责关系","地方政府→本级人大及相应常委会；地方政府→上一级行政机关","行政领导线不同于人大监督线，不可混画"],"pitfalls":["地方政府只对上级负责从不向本级人大负责","辨析：行政领导线不同于人大监督线，不可混画"],"articles":["《宪法》第三条","《宪法》第一百一十条"]}],"quiz":[{"type":"single","options":["宪法确定的国家权力机关性质","人大代表产生与行政首长任命之别","省级区划与县级区划之别","宪法修改与法律解释之别"],"answer":"A","explain":"地域本地性不决定是否为国家机关，须查第九十六条法定定位。","sectionId":"ch11-s1","articles":["《宪法》第九十六条","《宪法》第三条","《宪法》第一百零五条"],"tags":["地方人大","综合辨析"],"q":"甲只因人大设在本地就称其群众自治组织，遗漏了什么？","id":"quiz-ch11-001","difficulty":2},{"type":"single","options":["政府、人大常委会、法院、检察院","政府、监察委员会、公安机关、法院","人大、政府、监察委员会、检察院","政府、监察委员会、法院、检察院"],"answer":"D","explain":"这是课堂简称，其对象必须对应本级法定国家机关，而非字面任意组合。","sectionId":"ch11-s2","articles":["《宪法》第九十六条","《宪法》第一百零四条"],"tags":["地方人大常委会","综合辨析"],"q":"一府一委两院在地方监督结构中的正确展开是哪组？","id":"quiz-ch11-002","difficulty":2},{"type":"single","options":["按名称中的人民二字认定性质相同","按是否在同一县域认定权限相同","按行政机关与权力机关定位区分","按负责人是否当代表认定机关合一"],"answer":"C","explain":"人民一词不取消机关的性质职责差别，外观或人员特征均无决定意义。","sectionId":"ch11-s3","articles":["《宪法》第一百零五条","《宪法》第一百一十条"],"tags":["地方政府","综合辨析"],"q":"甲称地方政府只要名称里有人民就等于人大，如何纠正？","id":"quiz-ch11-003","difficulty":2},{"type":"single","options":["民族乡的人口一律不够自治条件","民族自治地方有宪法明确范围","民族乡不能依法管理地方事务","民族乡所有机关都属于群众自治"],"answer":"B","explain":"地域类别依法界定，人口名称长短不是标准，也不能否认乡级政权。","sectionId":"ch11-s4","articles":["《宪法》第一百一十二条","《宪法》第一百一十五条","《宪法》第三十条"],"tags":["自治机关","综合辨析"],"q":"民族乡为什么不因名称就与自治县拥有相同宪法身份？","id":"quiz-ch11-004","difficulty":2},{"type":"single","options":["分别标出人大监督线和上级行政负责线","把两条线均画成行政上下级领导","把两条线均画成法院审级监督","因同属国家机关而取消负责关系"],"answer":"A","explain":"不同性质关系应分线表达；合并机关或只列姓名无法说明制度联系。","sectionId":"ch11-s5","articles":["《宪法》第三条","《宪法》第一百一十条"],"tags":["中央地方关系","综合辨析"],"q":"画地方政府关系图时，哪种做法最能避免混乱？","id":"quiz-ch11-005","difficulty":2}]},{"id":"ch12","title":"第十二章 宪法实施监督","summary":"本章学习宪法实施监督，依次掌握实施与遵守、监督主体、宪法解释、修宪程序、合宪性与备案审查。重点在概念边界、机关职责和权利保障，不以口号代替规范分析。","sections":[{"id":"ch12-s1","title":"12.1 实施与遵守","plain":"规则写在纸上不等于已经落实。","body":"先建直觉：规则写在纸上不等于已经落实。\n\n再上定义：教材理论：实施是规范进入现实活动，遵守是不违背宪法要求，立法落实依法履职和权利保障均是观察实施的重要方面。\n\n一条关系线：机关组织个人→遵守宪法；相关机关→依法落实职责。\n\n术语解释：实施重总体运行，遵守是其重要方面。\n\n对比：最高效力不等于可跳过具体法律处理所有纠纷。 实施重在规范实际进入国家和社会生活，遵守是其中不违反宪法的重要方面。立法是否落实要求、机关是否依法履职、权利是否得到保障，都是观察实施的具体角度。宣传教育能够支持守宪意识，却不自动纠正抵触宪法的规则。最高效力仍须通过制度和行为发挥作用，而非以宣布重视代替落实。\n\n生活例子：甲称宣读一次即解决所有抵触，乙应强调纠正实际行为。","keyPoints":["宪法实施不能仅靠口头宣示","机关组织个人→遵守宪法；相关机关→依法落实职责","最高效力不等于可跳过具体法律处理所有纠纷"],"pitfalls":["宣读一次宪法所有违宪问题就自动消失","辨析：最高效力不等于可跳过具体法律处理所有纠纷"],"articles":["《宪法》第五条"]},{"id":"ch12-s2","title":"12.2 监督主体","plain":"监督职责须先问由谁依法承担。","body":"先建直觉：监督职责须先问由谁依法承担。\n\n再上定义：全国人大监督宪法实施，常委会解释宪法监督实施；各机关须遵守宪法不等于均有相同专门监督权限。\n\n一条关系线：全国人大及常委会→依宪法监督；其他机关→依法守宪履职。\n\n术语解释：一般遵守义务与专门监督职权不同。\n\n对比：公民提出监督意见不等于可个人撤销法律，法院审案不是普遍宪法审查。 全国人大监督宪法实施，常委会解释宪法并监督实施，属于宪法明确配置的职权。其他机关负有守宪履职义务，公民也可通过合法途径提出意见，但这些不使所有主体取得相同的规范撤销权。分析监督机制要分别看提出问题、依法审查和作出处理的主体与权限，不能把参与监督同最终处置混为一谈。\n\n生活例子：甲称人人守宪所以人人可宣布法律失效，乙应区分。","keyPoints":["守宪义务不等于撤销法律的职权","全国人大及常委会→依宪法监督；其他机关→依法守宪履职","公民提出监督意见不等于可个人撤销法律，法院审案不是普遍宪法审查"],"pitfalls":["任何公民都可以个人意见直接撤销国家法律","辨析：公民提出监督意见不等于可个人撤销法律，法院审案不是普遍宪法审查"],"articles":["《宪法》第六十二条","《宪法》第六十七条","《宪法》第五条"]},{"id":"ch12-s3","title":"12.3 宪法解释","plain":"说明规则含义不应偷偷改写规则。","body":"先建直觉：说明规则含义不应偷偷改写规则。\n\n再上定义：常委会解释宪法；教材理论上解释围绕含义适用，修宪改变文本须法定程序，教师课堂说明是学理解释不是正式有权解释。\n\n一条关系线：全国人大常委会→行使解释宪法职权→支持规范实施。\n\n术语解释：有权解释来自法定权限，学理解释来自研究教学。\n\n对比：解释与修改不能互换，法院审案不自动取得宪法解释权。 宪法解释围绕规范含义和实施展开，有权解释与教材学理说明在主体和性质上不同。教师或学者可以提出有说服力的理解，却不能因此称为常委会正式解释。解释与修改文本又是两件事，前者不能成为绕开修宪程序的捷径。讨论新情形需要说明规范依据，而不是因情形新就假设任何机关均有解释权。\n\n生活例子：甲把老师讲解称正式宪法解释，乙应辨明主体效力。","keyPoints":["课堂学理说明不等于正式宪法解释","全国人大常委会→行使解释宪法职权→支持规范实施","解释与修改不能互换，法院审案不自动取得宪法解释权"],"pitfalls":["所有教师课堂说明自动成为正式宪法解释","辨析：解释与修改不能互换，法院审案不自动取得宪法解释权"],"articles":["《宪法》第六十七条","《宪法》第六十四条"]},{"id":"ch12-s4","title":"12.4 修宪程序","plain":"根本规则可改但程序门槛特殊。","body":"先建直觉：根本规则可改但程序门槛特殊。\n\n再上定义：全国人民代表大会常务委员会或五分之一以上全国人民代表大会代表提议修宪，全国人大以全体代表三分之二以上多数通过；法律其他议案以全体代表过半数通过。\n\n一条关系线：法定提议主体→全国人大表决→达到全体代表特定多数。\n\n术语解释：提议不同于通过，全体不同于出席，以上含本数。\n\n对比：修宪门槛不同于普通法律，也不是常委会独立最终决定。 修宪需分别看提议与通过两个阶段。全国人大常委会或五分之一以上全国人大代表可以提议，全国人大以全体代表三分之二以上多数通过。全体不同于出席，提议比例也不同于通过比例；以上包含本数。普通法律其他议案的通过标准为全体代表过半数，不能将两类标准和各自分母混合套用。\n\n生活例子：甲称出席过半即可修宪，乙应核对分母比例。","keyPoints":["修宪通过门槛以全体代表为分母","法定提议主体→全国人大表决→达到全体代表特定多数","修宪门槛不同于普通法律，也不是常委会独立最终决定"],"pitfalls":["修宪仅需出席代表过半数同意","辨析：修宪门槛不同于普通法律，也不是常委会独立最终决定"],"articles":["《宪法》第六十四条"]},{"id":"ch12-s5","title":"12.5 合宪性与备案审查","plain":"检查标准与检查机制不是同一维度。","body":"先建直觉：检查标准与检查机制不是同一维度。\n\n再上定义：教材制度概述：合宪性审查看是否符合宪法，备案审查是相关规范文件报备受审查机制，可能涉及合宪合法等问题，有交叉但不等同；具体对象期限程序须另核专门规范，本包未核细则。\n\n一条关系线：有权机关→依法审查规范→维护法制统一保障权利。\n\n术语解释：合宪性偏重标准，备案审查偏重机制，这是入门框架。\n\n对比：备案不是当然批准，报备不保证合宪，法院不因此有普遍撤销法律权。 合宪性审查重在是否符合宪法这一标准，备案审查是有关规范报备并接受审查的制度机制，可能涉及合宪合法等问题。标准和机制存在交叉，不代表对象程序处理方式完全一致。文件已报备不等于已被证明合宪，也不表示免于继续审查；更不能由此推定普通法院获得普遍撤销法律的职权。\n\n生活例子：甲认为报备过便永远合宪，乙应区分状态结论。","keyPoints":["备案审查与合宪性审查不能简单等同","有权机关→依法审查规范→维护法制统一保障权利","备案不是当然批准，报备不保证合宪，法院不因此有普遍撤销法律权"],"pitfalls":["文件一经报备就当然合宪并免于审查","辨析：备案不是当然批准，报备不保证合宪，法院不因此有普遍撤销法律权"],"articles":["《宪法》第五条","《宪法》第六十七条"]}],"quiz":[{"type":"single","options":["仅看是否在文件开头引用宪法","仅看是否完成守宪学习记录","仅看是否发表支持宪法的声明","其实际职责行为及有关制度措施"],"answer":"D","explain":"实际制度行为回应实施问题，传播量外观只能是辅助信息。","sectionId":"ch12-s1","articles":["《宪法》第五条"],"tags":["实施与遵守","综合辨析"],"q":"衡量某机关落实宪法，哪项证据更直接？","id":"quiz-ch12-001","difficulty":2},{"type":"single","options":["把宪法解释与法律修改条件混同","把人大代表与全体人民混同","把监督意见误当法定规范处置权","把行政区划与自治机关混同"],"answer":"C","explain":"职权来源不是个人判断或文风，监督参与与作具有法定效力决定应区分。","sectionId":"ch12-s2","articles":["《宪法》第六十二条","《宪法》第六十七条","《宪法》第五条"],"tags":["监督主体","综合辨析"],"q":"甲凭个人认为违宪就宣布法律全国失效，主要问题是什么？","id":"quiz-ch12-002","difficulty":2},{"type":"single","options":["只看文件是否自称宪法说明","作出主体、权限依据与文件性质","只看作者是否从事法律职业","只看论述是否得到广泛赞同"],"answer":"B","explain":"解释效力首先取决于法定主体权限性质，外观传播度不能替代。","sectionId":"ch12-s3","articles":["《宪法》第六十七条","《宪法》第六十四条"],"tags":["宪法解释","综合辨析"],"q":"判断一份宪法说明文件性质，优先核对哪组信息？","id":"quiz-ch12-003","difficulty":2},{"type":"single","options":["没有，还须由全国人大依全体代表特定多数通过","已经完成，提议与通过是同一阶段","只须常委会最后确认无需全国人大表决","只须出席代表过半数无需特别门槛"],"answer":"A","explain":"提议条件满足只是进入修改程序的一个条件，不等于全国人大已作通过决定；主体、阶段、分母和门槛都不能省略。","sectionId":"ch12-s4","articles":["《宪法》第六十四条"],"tags":["修宪程序","综合辨析"],"q":"修宪提议获得足够代表联署后，是否已经完成宪法修改？","id":"quiz-ch12-004","difficulty":2},{"type":"single","options":["将全部备案审查都归入普通案件审判","认为文件报备即自动授予法院撤法权","以法官认为违宪代替法定处理权限","区分有权机关权限与相关审查机制"],"answer":"D","explain":"备案机制不自动赋予法院普遍宪法审查权，须分别核对主体对象处理权限。","sectionId":"ch12-s5","articles":["《宪法》第五条","《宪法》第六十七条"],"tags":["合宪性与备案审查","综合辨析"],"q":"甲把备案审查理解成法院普遍撤销法律的权力，应如何纠正？","id":"quiz-ch12-005","difficulty":2}]}],"sourceNotes":{"lawVersion":"《宪法》2018修正","verifiedArticles":["第一条","第二条","第三条","第四条","第五条","第六条","第十条","第十一条","第十三条","第十四条","第十九条","第二十二条","第二十六条","第三十条","第三十一条","第三十三条","第三十四条","第三十五条","第三十六条","第三十七条","第三十八条","第三十九条","第四十条","第四十一条","第四十二条","第四十三条","第四十五条","第四十六条","第四十七条","第五十一条","第五十二条","第五十三条","第五十四条","第五十五条","第五十六条","第五十七条","第五十九条","第六十二条","第六十四条","第六十七条","第七十五条","第八十条","第八十五条","第九十三条","第九十六条","第九十七条","第一百零四条","第一百零五条","第一百十条","第一百十一条","第一百十二条","第一百十五条","第一百二十三条","第一百二十七条","第一百二十八条","第一百三十四条","第一百三十六条","第一百四十条"],"verifiedCount":58,"pendingScope":["历史宪法文件及独立修正案原文","选举法具体程序","诉讼法具体程序","备案审查专门规范具体程序"],"scope":"已核验状态仅涵盖实际取回原文的现行宪法条文；理论、历史概述、程序导航不冒充原文。"}},"bank":{"meta":{"version":"2026.10.1","count":240,"source":"法学本科导师","lawVersion":"《宪法》2018修正"},"questions":[{"type":"single","stem":"国家机关设置和公民基本权利共同属于哪类法律的核心调整内容？","options":["民法","行政法","宪法","刑法"],"answer":"C","explain":"宪法同时组织公共权力并保障基本权利；合同、刑罚执行及财务制度各有较窄调整对象。","sectionId":"ch1-s1","articles":["《宪法》第五条"],"tags":["宪法的概念","概念识别"],"id":"q-ch1-001","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":1},{"type":"single","stem":"甲认为合同法规则与宪法冲突时仍可因内容具体而优先，这混淆了什么？","options":["规范效力与适用范围","具体程度与效力位阶","一般规则与特别规则","法律解释与法律修改"],"answer":"B","explain":"内容具体不意味着效力高于宪法，适用具体规则仍须尊重宪法最高效力。","sectionId":"ch1-s1","articles":["《宪法》第五条"],"tags":["宪法的概念","制度适用"],"id":"q-ch1-002","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":1},{"type":"judge","stem":"宪法作为根本法，意味着国家根本制度不需要由其他法律具体落实。","options":["正确","错误"],"answer":"错误","explain":"根本法确立框架，不排除立法等制度将基本权利和组织规则具体化。","sectionId":"ch1-s1","articles":["《宪法》第五条"],"tags":["宪法的概念","边界辨析"],"id":"q-ch1-003","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":2},{"type":"judge","stem":"普通民事交易也可能涉及宪法价值，但不能因此省略具体民事规则。","options":["正确","错误"],"answer":"正确","explain":"宪法价值与民法适用处于不同分析层次，二者联系不意味着可以相互替代。","sectionId":"ch1-s1","articles":["《宪法》第五条"],"tags":["宪法的概念","关系分析"],"id":"q-ch1-004","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":2},{"type":"single","stem":"学生在笔记中写下对宪法的个人理解，这首先属于什么？","options":["具有宪法位阶的法规","学习者的学理认识","正式宪法修正案","全国人大常委会解释"],"answer":"B","explain":"个人笔记可以帮助学习，但作者身份与形成程序不足以产生正式规范效力。","sectionId":"ch1-s2","articles":["《宪法》第五条"],"tags":["宪法渊源","概念识别"],"id":"q-ch1-005","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":1},{"type":"single","stem":"核对某个宪法条文是否为现行文本，最应优先做什么？","options":["核对权威文本版本与效力信息","只核公布日期不核修正版本","只核教材出版日期","只核相关政策发布时间"],"answer":"A","explain":"版本和效力信息回应现行文本问题；传播度、引用频次及文风不能替代法源核验。","sectionId":"ch1-s2","articles":["《宪法》第五条"],"tags":["宪法渊源","制度适用"],"id":"q-ch1-006","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":1},{"type":"judge","stem":"宪法修正案与教材对修正案的评论，属于同一性质的材料。","options":["正确","错误"],"answer":"错误","explain":"修正案是规范文件，教材评论属于解释研究材料，不能混同两者的法源地位。","sectionId":"ch1-s2","articles":["《宪法》第五条"],"tags":["宪法渊源","边界辨析"],"id":"q-ch1-007","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":2},{"type":"judge","stem":"讨论渊源时应关注表现形式，讨论效力时应关注规范的约束地位。","options":["正确","错误"],"answer":"正确","explain":"两者虽相关，但前者问规范以何种形式存在，后者问它具有何种约束地位。","sectionId":"ch1-s2","articles":["《宪法》第五条"],"tags":["宪法渊源","关系分析"],"id":"q-ch1-008","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":2},{"type":"single","stem":"以宪法是否具有统一成文法典为标准，主要区分什么？","options":["成文宪法与不成文宪法","刚性宪法与柔性宪法","联邦制与单一制","直接民主与间接民主"],"answer":"A","explain":"这是表现形式的分类；刚柔看修改程序，后两组分别涉及结构与民主方式。","sectionId":"ch1-s3","articles":["《宪法》第六十四条"],"tags":["宪法分类","概念识别"],"id":"q-ch1-009","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":1},{"type":"single","stem":"甲把修改门槛高于普通法律的宪法称为刚性宪法，依据是哪项？","options":["由制定主体单独决定的分类","以是否列举权利为标准","以条文是否需要解释为标准","修改程序的特殊性"],"answer":"D","explain":"刚性强调与普通法律相比的修改程序要求，而非篇幅、名称或物理载体。","sectionId":"ch1-s3","articles":["《宪法》第六十四条"],"tags":["宪法分类","制度适用"],"id":"q-ch1-010","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":1},{"type":"judge","stem":"不成文宪法国家的全部宪法规范都没有书面形式。","options":["正确","错误"],"answer":"错误","explain":"教材分类中的不成文并非完全没有书面文件，而是没有统一的成文宪法法典等形式特征。","sectionId":"ch1-s3","articles":["《宪法》第六十四条"],"tags":["宪法分类","边界辨析"],"id":"q-ch1-011","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":2},{"type":"judge","stem":"同一宪法可以在表现形式上属于成文宪法，在修改程序上属于刚性宪法。","options":["正确","错误"],"answer":"正确","explain":"两个分类依据不同，因此同一对象可以同时落入两类而无矛盾。","sectionId":"ch1-s3","articles":["《宪法》第六十四条"],"tags":["宪法分类","关系分析"],"id":"q-ch1-012","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":2},{"type":"single","stem":"规定国家发展公共事业的条款，主要体现哪种规范内容？","options":["基本权利保障条款","国家机关职权条款","宪法修改程序条款","国家任务"],"answer":"D","explain":"国家任务条款为教育、文化、社会保障等公共事业确定发展方向。它与保障个人权利、配置机关职权、规定修宪程序等规范内容有联系，但不能直接混同。","sectionId":"ch1-s4","articles":["《宪法》第五条","《宪法》第三十三条"],"tags":["宪法规范","概念识别"],"id":"q-ch1-013","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":1},{"type":"single","stem":"面对原则性宪法规定，具体立法的合理作用是什么？","options":["将宪法降为倡议","以部门便利决定效力","在宪法框架内细化落实机制","自行取消宪法约束"],"answer":"C","explain":"细化服务于落实而非取消上位约束；便利不能成为改变规范效力的依据。","sectionId":"ch1-s4","articles":["《宪法》第五条","《宪法》第三十三条"],"tags":["宪法规范","制度适用"],"id":"q-ch1-014","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":1},{"type":"judge","stem":"宪法没有直接写出某项保障待遇的金额，就说明该领域不受宪法调整。","options":["正确","错误"],"answer":"错误","explain":"国家任务和权利保障可以采用原则表达，待遇细则则由具体制度确定。","sectionId":"ch1-s4","articles":["《宪法》第五条","《宪法》第三十三条"],"tags":["宪法规范","边界辨析"],"id":"q-ch1-015","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":2},{"type":"judge","stem":"权利规范与组织规范可以共同服务于约束公共权力。","options":["正确","错误"],"answer":"正确","explain":"权利规范提供应受保护的利益，组织规范配置职责权限，两者相互支持。","sectionId":"ch1-s4","articles":["《宪法》第五条","《宪法》第三十三条"],"tags":["宪法规范","关系分析"],"id":"q-ch1-016","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":2},{"type":"single","stem":"甲与乙约定买卖旧书，首先应画哪条关系线？","options":["中央对地方领导关系","公民与选举组织关系","平等主体间的交易关系","人大对政府监督关系"],"answer":"C","explain":"旧书买卖首先是民事交易，不因参与者是公民就全部转化为宪法机关关系。","sectionId":"ch1-s5","articles":["《宪法》第二条","《宪法》第三条","《宪法》第三十三条"],"tags":["宪法关系","概念识别"],"id":"q-ch1-017","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":1},{"type":"single","stem":"地方政府向本级人大负责，体现哪类关系？","options":["行政系统上下级领导关系","机关间职责监督关系","审判机关审级监督关系","国家与国际组织关系"],"answer":"B","explain":"地方政府向本级人大负责，体现不同国家机关之间的负责和监督关系；政府向上级行政机关负责还涉及行政系统领导关系，两条联系不能混同。","sectionId":"ch1-s5","articles":["《宪法》第二条","《宪法》第三条","《宪法》第三十三条"],"tags":["宪法关系","制度适用"],"id":"q-ch1-018","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":1},{"type":"judge","stem":"工作人员可以像出售个人旧物一样出售机关的法定职权。","options":["正确","错误"],"answer":"错误","explain":"职权与公共职责相联系，不是任职者可以处分的私人财产。","sectionId":"ch1-s5","articles":["《宪法》第二条","《宪法》第三条","《宪法》第三十三条"],"tags":["宪法关系","边界辨析"],"id":"q-ch1-019","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":2},{"type":"judge","stem":"研究某项基本权利时，识别承担保障职责的国家机关有助于画清宪法关系。","options":["正确","错误"],"answer":"正确","explain":"只看到权利名称仍不完整，需要分析谁负有相应尊重保障职责。","sectionId":"ch1-s5","articles":["《宪法》第二条","《宪法》第三条","《宪法》第三十三条"],"tags":["宪法关系","关系分析"],"id":"q-ch1-020","chapterId":"ch1","chapterTitle":"第一章 基本理论","difficulty":2},{"type":"single","stem":"比较各国宪法历史时，哪项最应避免？","options":["关注制度的历史变化","把不同国家发展归结为同一时间表","结合社会背景理解制度","区分权利保障和权力组织"],"answer":"B","explain":"各国历史道路有差异，不能用单一路线抹平；其余都是恰当的比较方法。","sectionId":"ch2-s1","articles":["《宪法》第五条","《宪法》第三十三条"],"tags":["世界宪法发展","概念识别"],"id":"q-ch2-001","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":1},{"type":"single","stem":"教材谈到社会权与国家积极任务更受重视，主要说明什么？","options":["宪法关注领域随历史发展有所拓展","宪法从此不再约束权力","自由权全部失去意义","各国制度已完全相同"],"answer":"A","explain":"国家积极任务拓展保护领域，不等于取消限制权力、自由权或法域差异。","sectionId":"ch2-s1","articles":["《宪法》第五条","《宪法》第三十三条"],"tags":["世界宪法发展","制度适用"],"id":"q-ch2-002","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":1},{"type":"judge","stem":"外国法院拥有某种审查权，就能据此认定我国法院有相同职权。","options":["正确","错误"],"answer":"错误","explain":"比较法介绍不能代替我国法源中的职权配置，应先辨法域制度。","sectionId":"ch2-s1","articles":["《宪法》第五条","《宪法》第三十三条"],"tags":["世界宪法发展","边界辨析"],"id":"q-ch2-003","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":2},{"type":"judge","stem":"近代宪法发展可从限制专断、代表制度及自由保障等线索进行教材层面的理解。","options":["正确","错误"],"answer":"正确","explain":"这是历史概括而非某一国家某部文件的逐字引述，不应混同材料性质。","sectionId":"ch2-s1","articles":["《宪法》第五条","《宪法》第三十三条"],"tags":["世界宪法发展","关系分析"],"id":"q-ch2-004","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":2},{"type":"single","stem":"共同纲领在建国初期的作用，在本课程中应如何表述？","options":["起临时宪法作用的历史概括","新中国第一部正式宪法","1982年宪法的独立修正案","现行宪法的授权解释"],"answer":"A","explain":"这是教材对历史功能的概括，不能变成今日效力或其他规范类型的认定。","sectionId":"ch2-s2","articles":["《宪法》第二条","《宪法》第五条"],"tags":["共同纲领与1954年宪法","概念识别"],"id":"q-ch2-005","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":1},{"type":"single","stem":"1954年宪法在新中国宪法史中的位置是什么？","options":["新中国现行宪法的基本文本","共同纲领的临时适用补充","1978年宪法的第一次修正","新中国第一部宪法"],"answer":"D","explain":"1954年宪法具有第一部宪法的历史位置，不是随后文件的修正或选举法附件。","sectionId":"ch2-s2","articles":["《宪法》第二条","《宪法》第五条"],"tags":["共同纲领与1954年宪法","制度适用"],"id":"q-ch2-006","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":1},{"type":"judge","stem":"共同纲领与1954年宪法都曾发挥重要历史作用，因此两者今天可以直接替代现行宪法。","options":["正确","错误"],"answer":"错误","explain":"历史功能不等于当前效力，现行问题应按现行宪法规范分析。","sectionId":"ch2-s2","articles":["《宪法》第二条","《宪法》第五条"],"tags":["共同纲领与1954年宪法","边界辨析"],"id":"q-ch2-007","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":2},{"type":"judge","stem":"从共同纲领到1954年宪法，可以观察建国初期过渡安排与正式宪法建设的衔接。","options":["正确","错误"],"answer":"正确","explain":"这是制度发展线索，不需要把未核验历史原文写成精确引文。","sectionId":"ch2-s2","articles":["《宪法》第二条","《宪法》第五条"],"tags":["共同纲领与1954年宪法","关系分析"],"id":"q-ch2-008","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":2},{"type":"single","stem":"把1975年机构资料直接用于判断今天机关设置，主要风险是什么？","options":["将制宪与修宪程序混同","将国体与国家结构混同","将学理解释与正式解释混同","混淆历史制度与现行制度"],"answer":"D","explain":"时间上的制度差异会导致规范适用错误，载体细节并非主要风险。","sectionId":"ch2-s3","articles":["《宪法》第五条"],"tags":["1975年与1978年宪法","概念识别"],"id":"q-ch2-009","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":1},{"type":"single","stem":"研究1975年与1978年宪法，哪组问题具有实质学习意义？","options":["仅比较制宪主体名称而不比较制度","仅按是否成文归为同一文本","国家机构安排与权利法制建设变化","仅按国家名称相同认定内容一致"],"answer":"C","explain":"机构权利法制是制度史重点；资料外观和保管信息不能替代实质分析。","sectionId":"ch2-s3","articles":["《宪法》第五条"],"tags":["1975年与1978年宪法","制度适用"],"id":"q-ch2-010","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":1},{"type":"judge","stem":"不能取得旧宪法原文时，可以凭印象补写条号并加引号。","options":["正确","错误"],"answer":"错误","explain":"引号和条号会构成精确引用承诺，缺少原文时只能作有标识的历史概述。","sectionId":"ch2-s3","articles":["《宪法》第五条"],"tags":["1975年与1978年宪法","边界辨析"],"id":"q-ch2-011","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":2},{"type":"judge","stem":"1975年和1978年宪法是不同历史节点，不能因名称相同就认定制度安排从未变化。","options":["正确","错误"],"answer":"正确","explain":"宪法名称相同不排除不同文本和制度变化，需要分别研究背景内容。","sectionId":"ch2-s3","articles":["《宪法》第五条"],"tags":["1975年与1978年宪法","关系分析"],"id":"q-ch2-012","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":2},{"type":"single","stem":"1982年宪法与1988、1993、1999、2004年修正之间，应如何理解？","options":["普通法规逐级替代宪法","地方文件改变国家根本法","基本文本与其后修正的连续关系","五部同时独立适用的完整宪法"],"answer":"C","explain":"修正是在基本文本上发展调整，不是多部互不相干的宪法并行。","sectionId":"ch2-s4","articles":["《宪法》第六十四条"],"tags":["1982年宪法及前四次修正","概念识别"],"id":"q-ch2-013","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":1},{"type":"single","stem":"需要确认2004年某项修改的准确措辞，最应核对什么？","options":["仅核现行文本而不追溯修正文件","对应修正案及相关文本沿革","仅核当年立法计划","仅核后续教材概括"],"answer":"B","explain":"具体修改文字属于沿革核验，应查相应文件；当前任意条文不能证明历史措辞。","sectionId":"ch2-s4","articles":["《宪法》第六十四条"],"tags":["1982年宪法及前四次修正","制度适用"],"id":"q-ch2-014","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":1},{"type":"judge","stem":"记住四次修正年份，就足以证明每次修改的全部原文已经核验。","options":["正确","错误"],"answer":"错误","explain":"时间线记忆与原文核验不同，不能将已知年份包装成逐字证据。","sectionId":"ch2-s4","articles":["《宪法》第六十四条"],"tags":["1982年宪法及前四次修正","边界辨析"],"id":"q-ch2-015","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":2},{"type":"judge","stem":"宪法可以保持基本文本连续性，同时通过修正回应制度发展。","options":["正确","错误"],"answer":"正确","explain":"文本连续和制度调整不矛盾，修正方式正体现这种衔接。","sectionId":"ch2-s4","articles":["《宪法》第六十四条"],"tags":["1982年宪法及前四次修正","关系分析"],"id":"q-ch2-016","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":2},{"type":"single","stem":"数据库返回宪法标题带2018修正后缀，这首先说明什么？","options":["该条文最初制定于2018年","本次取得的是相应修正版本的文本","所有历史修正案均已取得","每个国家都在2018年修宪"],"answer":"B","explain":"版本后缀反映文本版本，不证明全部历史文件已查或该条最初制定年份。","sectionId":"ch2-s5","articles":["《宪法》第一百二十三条","《宪法》第五条"],"tags":["2018年修正与现行文本","概念识别"],"id":"q-ch2-017","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":1},{"type":"single","stem":"现行宪法把各级监察委员会定位为什么？","options":["国家监察机关","国家审判机关","国家行政机关","基层群众自治组织"],"answer":"A","explain":"已核第一百二十三条明确监察机关性质，不能按其他机构分类替代。","sectionId":"ch2-s5","articles":["《宪法》第一百二十三条","《宪法》第五条"],"tags":["2018年修正与现行文本","制度适用"],"id":"q-ch2-018","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":1},{"type":"judge","stem":"只要现行版本已经核验，就可以凭记忆逐字引用2018年修正案全部内容。","options":["正确","错误"],"answer":"错误","explain":"合并文本与独立修正案为不同核验对象，逐字引用仍需文件原文。","sectionId":"ch2-s5","articles":["《宪法》第一百二十三条","《宪法》第五条"],"tags":["2018年修正与现行文本","边界辨析"],"id":"q-ch2-019","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":2},{"type":"judge","stem":"使用过时机构图时，应结合现行文本检查是否遗漏国家监察机关。","options":["正确","错误"],"answer":"正确","explain":"机构图是辅助资料，内容应接受现行宪法机构定位的校正。","sectionId":"ch2-s5","articles":["《宪法》第一百二十三条","《宪法》第五条"],"tags":["2018年修正与现行文本","关系分析"],"id":"q-ch2-020","chapterId":"ch2","chapterTitle":"第二章 宪法历史发展","difficulty":2},{"type":"single","stem":"国家一切权力的归属主体是谁？","options":["人民","全体公民个人分别拥有全部国家职权","国家行政机关","各级人大代表个人"],"answer":"A","explain":"第二条把权力归属确定为人民，不能将其缩小为行政部门企业或个人。","sectionId":"ch3-s1","articles":["《宪法》第二条"],"tags":["人民主权","概念识别"],"id":"q-ch3-001","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":1},{"type":"single","stem":"人民行使国家权力的机关是什么？","options":["全国人大及各级政府","全国人大及各级法院","全国政协及地方政协","全国人大和地方各级人大"],"answer":"D","explain":"第二条明确人大为相应机关；社会经济组织不因参与公共事务就成为国家权力机关。","sectionId":"ch3-s1","articles":["《宪法》第二条"],"tags":["人民主权","制度适用"],"id":"q-ch3-002","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":1},{"type":"judge","stem":"人民通过法律规定的多种途径形式管理国家社会事务，不能只理解为投票一种形式。","options":["正确","错误"],"answer":"正确","explain":"第二条列明多种领域与形式，人大途径重要但不抹去依法参与的其他方式。","sectionId":"ch3-s1","articles":["《宪法》第二条"],"tags":["人民主权","边界辨析"],"id":"q-ch3-003","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":2},{"type":"judge","stem":"甲可以因为自己属于人民而不经授权直接签发国家行政命令。","options":["正确","错误"],"answer":"错误","explain":"权力归属人民不等于每个人取得全部机关权限，具体行使依制度和法律进行。","sectionId":"ch3-s1","articles":["《宪法》第二条"],"tags":["人民主权","关系分析"],"id":"q-ch3-004","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":2},{"type":"single","stem":"国家尊重人权，在教材分析中首先强调什么？","options":["取消所有公共服务","保证任何要求必被满足","放弃全部依法管理","避免不当侵犯"],"answer":"D","explain":"尊重强调不侵害，不等于放弃管理或无条件满足一切个体要求。","sectionId":"ch3-s2","articles":["《宪法》第三十三条"],"tags":["人权保障","概念识别"],"id":"q-ch3-005","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":1},{"type":"single","stem":"国家建立保护受害者权益的合法机制，较突出哪方面？","options":["仅消极不干预而无保护制度","对每人全部要求无条件给付","积极保障","以国家任务取代个人基本权利"],"answer":"C","explain":"建立合法保护机制体现国家积极保障权利的一面，不仅是消极不干预；积极保障仍须依法进行，不意味着满足所有个人请求或以国家任务取消个人权利。","sectionId":"ch3-s2","articles":["《宪法》第三十三条"],"tags":["人权保障","制度适用"],"id":"q-ch3-006","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":1},{"type":"judge","stem":"以保障人权为名采取的措施，也应受宪法和法律约束。","options":["正确","错误"],"answer":"正确","explain":"保护目的不能使措施免于合法性审查，保障本身也不得任意侵犯权利。","sectionId":"ch3-s2","articles":["《宪法》第三十三条"],"tags":["人权保障","边界辨析"],"id":"q-ch3-007","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":2},{"type":"judge","stem":"国家只要没有亲自侵害，便永远不需要应对他人造成的权利侵害。","options":["正确","错误"],"answer":"错误","explain":"保障可能要求国家依法提供保护和救济，不能将尊重的不侵犯义务视为全部义务。","sectionId":"ch3-s2","articles":["《宪法》第三十三条"],"tags":["人权保障","关系分析"],"id":"q-ch3-008","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":2},{"type":"single","stem":"宪法关于特权的规则指向什么？","options":["公益组织不受法律拘束","地方机关可随意排除宪法","任何组织个人不得超越宪法法律","高职务者可决定免守宪法"],"answer":"C","explain":"第五条反对超越宪法法律的特权，没有按职位或组织公益性设法外豁免。","sectionId":"ch3-s3","articles":["《宪法》第五条"],"tags":["社会主义法治","概念识别"],"id":"q-ch3-009","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":1},{"type":"single","stem":"机关认为某法规与宪法相抵触，制度目标首先涉及什么？","options":["明确法律修改是否适用特别程序","维护法制统一和宪法权威","确定哪种规范属于基本法律","划分国家结构与政体的分类标准"],"answer":"B","explain":"抵触问题关系规范统一；不得转化为奖励分配、合同变更或整体免责。","sectionId":"ch3-s3","articles":["《宪法》第五条"],"tags":["社会主义法治","制度适用"],"id":"q-ch3-010","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":1},{"type":"judge","stem":"提高行政效率的目的能够自动补足欠缺的法定权限。","options":["正确","错误"],"answer":"错误","explain":"目的正当与有权限是不同审查问题，效率不能凭空产生职权。","sectionId":"ch3-s3","articles":["《宪法》第五条"],"tags":["社会主义法治","边界辨析"],"id":"q-ch3-011","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":2},{"type":"judge","stem":"拥有较多法律文件并不能单独证明已经实现依法办事。","options":["正确","错误"],"answer":"正确","explain":"法治要求规范在实践中约束行为，文本数量不是落实效果的充分证据。","sectionId":"ch3-s3","articles":["《宪法》第五条"],"tags":["社会主义法治","关系分析"],"id":"q-ch3-012","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":2},{"type":"single","stem":"行政监察审判检察机关与人大是什么制度联系？","options":["行政机关领导全部其他机关","由人大产生，对其负责受其监督","审判机关产生并管理其他机关","各机关相互产生而无需人大"],"answer":"B","explain":"第3条规定行政、监察、审判和检察机关由人民代表大会产生，对它负责，受它监督；不意味着四类机关相互产生，也不是其中一个机关领导全部其他机关。","sectionId":"ch3-s4","articles":["《宪法》第三条"],"tags":["民主集中制","概念识别"],"id":"q-ch3-013","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":1},{"type":"single","stem":"中央地方职权划分应遵循哪项原则？","options":["中央统一领导下发挥地方主动积极性","地方拥有独立国家主权","所有事务只许中央亲办","地方可以不受宪法约束"],"answer":"A","explain":"第三条将统一领导与地方积极性结合，既非地方主权独立也非取消一切地方作用。","sectionId":"ch3-s4","articles":["《宪法》第三条"],"tags":["民主集中制","制度适用"],"id":"q-ch3-014","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":1},{"type":"judge","stem":"民主集中制中的集中，可以被理解为任何工作人员的个人任意决定。","options":["正确","错误"],"answer":"错误","explain":"集中在制度框架内形成统一，并非个人脱离民主与法律程序的任性。","sectionId":"ch3-s4","articles":["《宪法》第三条"],"tags":["民主集中制","边界辨析"],"id":"q-ch3-015","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":2},{"type":"judge","stem":"人大受人民监督，与其他有关机关受人大监督可以处于同一制度链条。","options":["正确","错误"],"answer":"正确","explain":"第三条既规定人大对人民负责受人民监督，也规定有关机关对人大负责受其监督。","sectionId":"ch3-s4","articles":["《宪法》第三条"],"tags":["民主集中制","关系分析"],"id":"q-ch3-016","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":2},{"type":"single","stem":"我国根本制度是什么？","options":["社会主义制度","人民代表大会制度","民族区域自治制度","基层群众自治制度"],"answer":"A","explain":"第一条将社会主义制度定位为根本制度；其他制度不具有这一同等定位。","sectionId":"ch3-s5","articles":["《宪法》第一条","《宪法》第二条"],"tags":["人民民主专政与国体","概念识别"],"id":"q-ch3-017","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":1},{"type":"single","stem":"中国特色社会主义最本质的特征是什么？","options":["人民代表大会制度的具体会议形式","某一层级代表的选举方式","国家行政区域的划分方式","中国共产党领导"],"answer":"D","explain":"第一条确认党的领导的这一地位。","sectionId":"ch3-s5","articles":["《宪法》第一条","《宪法》第二条"],"tags":["人民民主专政与国体","制度适用"],"id":"q-ch3-018","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":1},{"type":"judge","stem":"工人阶级领导和工农联盟基础，是理解我国国体表述的重要内容。","options":["正确","错误"],"answer":"正确","explain":"第一条在国家性质的完整表述中明确领导力量和社会基础，不能只记名称遗漏结构。","sectionId":"ch3-s5","articles":["《宪法》第一条","《宪法》第二条"],"tags":["人民民主专政与国体","边界辨析"],"id":"q-ch3-019","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":2},{"type":"judge","stem":"人民代表大会制度回答的是国体问题，人民民主专政回答的是政体问题。","options":["正确","错误"],"answer":"错误","explain":"两者被对调；国体侧重国家性质，政体侧重政权组织形式。","sectionId":"ch3-s5","articles":["《宪法》第一条","《宪法》第二条"],"tags":["人民民主专政与国体","关系分析"],"id":"q-ch3-020","chapterId":"ch3","chapterTitle":"第三章 基本原则与国体","difficulty":2},{"type":"single","stem":"我国根本政治制度在教材中指什么？","options":["中国共产党领导的多党合作和政治协商制度","民族区域自治制度","基层群众自治制度","人民代表大会制度"],"answer":"D","explain":"人民代表大会制度是根本政治制度；多党合作和政治协商、民族区域自治、基层群众自治是重要制度，但不能与“根本政治制度”的概念互换。","sectionId":"ch4-s1","articles":["《宪法》第二条","《宪法》第三条","《宪法》第五十七条"],"tags":["人民代表大会制度","概念识别"],"id":"q-ch4-001","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":1},{"type":"single","stem":"人大闭会就意味着一切国家工作暂停吗？","options":["是，只有大会期间国家职权才可行使","否，但闭会后全部机关职权自动移交政府","不，常设机关及其他机关依法履职","否，但闭会后常委会即取得全国人大全部专属职权"],"answer":"C","explain":"人大制度并非只有开会一个环节，机关按宪法分工持续运作。","sectionId":"ch4-s1","articles":["《宪法》第二条","《宪法》第三条","《宪法》第五十七条"],"tags":["人民代表大会制度","制度适用"],"id":"q-ch4-002","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":1},{"type":"judge","stem":"全国人大常委会与普通社会团体在宪法机构地位上没有区别。","options":["正确","错误"],"answer":"错误","explain":"常委会为全国人大常设机关，具有宪法规定职权，不是普通社团。","sectionId":"ch4-s1","articles":["《宪法》第二条","《宪法》第三条","《宪法》第五十七条"],"tags":["人民代表大会制度","边界辨析"],"id":"q-ch4-003","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":2},{"type":"judge","stem":"人大制度分析既要看代表产生，也要看其他机关的负责监督关系。","options":["正确","错误"],"answer":"正确","explain":"只有投票而无机构联系的描述不完整，第三条提供了机关制度链条。","sectionId":"ch4-s1","articles":["《宪法》第二条","《宪法》第三条","《宪法》第五十七条"],"tags":["人民代表大会制度","关系分析"],"id":"q-ch4-004","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":2},{"type":"single","stem":"全国人大代表的特定发言表决不受追究，宪法限定的场合是哪里？","options":["任意商业谈判中","所有网络发言中","全国人大各种会议上","所有私人聚会中"],"answer":"C","explain":"第七十五条规定会议场合及发言表决两类行为，不能按代表身份无限扩张。","sectionId":"ch4-s2","articles":["《宪法》第七十五条","《宪法》第五十九条"],"tags":["代表及履职保障","概念识别"],"id":"q-ch4-005","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":1},{"type":"single","stem":"甲代表在私人买卖中欺骗乙，能否直接援引会议发言免责？","options":["能，只要交易金额较小","不能，私人交易不在该条行为场合范围","能，只要出示代表证","能，只要未开会"],"answer":"B","explain":"保障针对特定履职行为，不按代表证、闭会时间或交易金额赋予私人欺诈免责。","sectionId":"ch4-s2","articles":["《宪法》第七十五条","《宪法》第五十九条"],"tags":["代表及履职保障","制度适用"],"id":"q-ch4-006","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":1},{"type":"judge","stem":"代表的会议表决与其私人经营行为应当分开评价。","options":["正确","错误"],"answer":"正确","explain":"履职保障有明确对象，私人行为仍受相应法律规则调整。","sectionId":"ch4-s2","articles":["《宪法》第七十五条","《宪法》第五十九条"],"tags":["代表及履职保障","边界辨析"],"id":"q-ch4-007","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":2},{"type":"judge","stem":"第七十五条本身已经规定了代表被采取所有强制措施时的完整批准程序。","options":["正确","错误"],"answer":"错误","explain":"该条内容是特定发言表决保障，不能冒充其他人身保护条款或程序法的全部内容。","sectionId":"ch4-s2","articles":["《宪法》第七十五条","《宪法》第五十九条"],"tags":["代表及履职保障","关系分析"],"id":"q-ch4-008","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":2},{"type":"single","stem":"县人大代表由谁选举？","options":["县法院决定","选民直接选举","国务院任命","县政府内部推选"],"answer":"B","explain":"第九十七条明确县级相应代表直接选举，并非行政任命或司法决定。","sectionId":"ch4-s3","articles":["《宪法》第九十七条","《宪法》第五十九条"],"tags":["直接与间接选举","概念识别"],"id":"q-ch4-009","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":1},{"type":"single","stem":"省人大代表的宪法产生路径是什么？","options":["下一级人大选举","全省选民直接投票","省政府任命","居民委员会联合决定"],"answer":"A","explain":"省级人大代表适用间接选举路径；不能混同县乡直接选举或其他组织任命。","sectionId":"ch4-s3","articles":["《宪法》第九十七条","《宪法》第五十九条"],"tags":["直接与间接选举","制度适用"],"id":"q-ch4-010","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":1},{"type":"judge","stem":"参加县人大代表选举，就是在直接选举县长。","options":["正确","错误"],"answer":"错误","explain":"所选职位是人大代表，行政首长产生是另一制度问题，不能以投票发生地替代职位判断。","sectionId":"ch4-s3","articles":["《宪法》第九十七条","《宪法》第五十九条"],"tags":["直接与间接选举","边界辨析"],"id":"q-ch4-011","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":2},{"type":"judge","stem":"直接和间接选举描述产生路径，不直接评价代表职位的重要性。","options":["正确","错误"],"answer":"正确","explain":"分类标准是选民直接选还是下级人大选，非重要与不重要。","sectionId":"ch4-s3","articles":["《宪法》第九十七条","《宪法》第五十九条"],"tags":["直接与间接选举","关系分析"],"id":"q-ch4-012","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":2},{"type":"single","stem":"宪法选举权年龄条件是怎样规定的？","options":["年满十八周岁","年满十六周岁","大学毕业时自动取得","参加工作满一年"],"answer":"A","explain":"第三十四条以年满十八周岁为条件之一，学历就业不是替代年龄的标准。","sectionId":"ch4-s4","articles":["《宪法》第三十四条"],"tags":["普遍与平等选举","概念识别"],"id":"q-ch4-013","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":1},{"type":"single","stem":"哪类属于第三十四条明确的选举权例外？","options":["没有房产的人","没有大学学历的人","在当地居住不满自定期限的人","依照法律被剥夺政治权利的人"],"answer":"D","explain":"法定剥夺政治权利属于明确例外，财产教育居住期限不能被任意用作排除理由。","sectionId":"ch4-s4","articles":["《宪法》第三十四条"],"tags":["普遍与平等选举","制度适用"],"id":"q-ch4-014","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":1},{"type":"judge","stem":"普遍性与平等性可以分别从参与范围和参与地位理解。","options":["正确","错误"],"answer":"正确","explain":"前者侧重覆盖谁，后者侧重如何平等参与，两者相关但不完全同义。","sectionId":"ch4-s4","articles":["《宪法》第三十四条"],"tags":["普遍与平等选举","边界辨析"],"id":"q-ch4-015","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":2},{"type":"judge","stem":"投票意愿不同就说明选举权不平等。","options":["正确","错误"],"answer":"错误","explain":"平等保障法律参与地位，不要求每个人作出同样政治选择或表达同样意见。","sectionId":"ch4-s4","articles":["《宪法》第三十四条"],"tags":["普遍与平等选举","关系分析"],"id":"q-ch4-016","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":2},{"type":"single","stem":"要查询代表候选人的法定差额比例，应优先进一步检索什么？","options":["代表法的履职保障条款","地方组织法的机关负责规则","宪法的公民资格条款","选举法相应现行规则"],"answer":"D","explain":"差额属于具体选举程序，宪法原则不能代替选举法细则，其他材料主题不相关。","sectionId":"ch4-s5","articles":["《宪法》第三十四条","《宪法》第五十九条","《宪法》第九十七条"],"tags":["选举程序框架","概念识别"],"id":"q-ch4-017","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":1},{"type":"single","stem":"按照入门框架，哪一组属于选举过程应关注的环节？","options":["提名后直接任命，不再投票","先确认结果再确定候选人","资格、候选人、投票与结果","先任命行政首长再登记选民"],"answer":"C","explain":"资格确认、候选人形成、投票与结果确认属于选举程序的不同环节。提名不等于任命，也不能先确认结果再确定候选人；具体程序仍须依选举法核验。","sectionId":"ch4-s5","articles":["《宪法》第三十四条","《宪法》第五十九条","《宪法》第九十七条"],"tags":["选举程序框架","制度适用"],"id":"q-ch4-018","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":1},{"type":"judge","stem":"只要了解宪法的选举权条件，就已经掌握选举法全部公告期限。","options":["正确","错误"],"answer":"错误","explain":"资格和期限是不同问题，宪法基本框架没有代替具体法定天数。","sectionId":"ch4-s5","articles":["《宪法》第三十四条","《宪法》第五十九条","《宪法》第九十七条"],"tags":["选举程序框架","边界辨析"],"id":"q-ch4-019","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":2},{"type":"judge","stem":"候选人产生和投票结果确认是两个不同环节，不宜混为一个步骤。","options":["正确","错误"],"answer":"正确","explain":"前者涉及供选人选的形成，后者涉及投票结果的依法确定，学习框架应分开梳理。","sectionId":"ch4-s5","articles":["《宪法》第三十四条","《宪法》第五十九条","《宪法》第九十七条"],"tags":["选举程序框架","关系分析"],"id":"q-ch4-020","chapterId":"ch4","chapterTitle":"第四章 人大制度与选举","difficulty":2},{"type":"single","stem":"区分单一制与联邦制，核心观察哪项关系？","options":["国家权力的阶级性质","国家政权的组织形式","国家整体与组成部分的关系","基本权利的保障方式"],"answer":"C","explain":"国家结构形式关注中央地方等整体部分关系，不是交易或诉讼关系。","sectionId":"ch5-s1","articles":["《宪法》第三条","《宪法》第四条"],"tags":["单一制","主体识别"],"id":"q-ch5-001","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":1},{"type":"single","stem":"在我国统一国家框架中，地方职权的正确理解是什么？","options":["可以任意脱离国家的依据","依宪法法律配置的公共权限","地方独立主权的全部体现","地方官员私人授予的权利"],"answer":"B","explain":"地方权限依法配置，不能等同主权或私人财产，也不产生任意分离依据。","sectionId":"ch5-s1","articles":["《宪法》第三条","《宪法》第四条"],"tags":["单一制","规范适用"],"id":"q-ch5-002","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":1},{"type":"judge","stem":"实行单一制就意味着所有地方事务都只能由中央机关直接办理。","options":["正确","错误"],"answer":"错误","explain":"中央统一领导与地方积极性结合，统一并不取消地方机关依法履职。","sectionId":"ch5-s1","articles":["《宪法》第三条","《宪法》第四条"],"tags":["单一制","概念辨析"],"id":"q-ch5-003","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":2},{"type":"judge","stem":"自治地方属于我国不可分离的部分，与其依法享有自治权并不矛盾。","options":["正确","错误"],"answer":"正确","explain":"自治在统一国家内实施，不是主权独立，第四条对此有明确框架。","sectionId":"ch5-s1","articles":["《宪法》第三条","《宪法》第四条"],"tags":["单一制","边界判断"],"id":"q-ch5-004","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":2},{"type":"single","stem":"宪法列明哪组属于民族自治地方？","options":["市辖区、居民组、社区","自治区、自治州、自治县","民族乡、街道、居民区","省、直辖市、普通乡"],"answer":"B","explain":"第三十条明列自治区自治州自治县；不能因名称含民族或地域性质就一律归入。","sectionId":"ch5-s2","articles":["《宪法》第三十条"],"tags":["行政区划","主体识别"],"id":"q-ch5-005","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":1},{"type":"single","stem":"县和自治县分为哪些基本行政单位？","options":["乡、民族乡、镇","省、自治区、直辖市","县、自治县、市辖区","自治区、自治州、自治县"],"answer":"A","explain":"第三十条规定这一划分；第二组是上层区域，第三组是机关，第四组是社区组织。","sectionId":"ch5-s2","articles":["《宪法》第三十条"],"tags":["行政区划","规范适用"],"id":"q-ch5-006","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":1},{"type":"judge","stem":"行政区划与国家机关是同一概念，因而可以把县直接称为审判机关。","options":["正确","错误"],"answer":"错误","explain":"区划是治理地域单元，机关是组织；县与县法院并不是同一对象。","sectionId":"ch5-s2","articles":["《宪法》第三十条"],"tags":["行政区划","概念辨析"],"id":"q-ch5-007","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":2},{"type":"judge","stem":"民族乡与自治县都可在行政区域名称中出现，但宪法分类并不相同。","options":["正确","错误"],"answer":"正确","explain":"民族乡属于乡级区划，宪法民族自治地方列举则包括自治区自治州自治县。","sectionId":"ch5-s2","articles":["《宪法》第三十条"],"tags":["行政区划","边界判断"],"id":"q-ch5-008","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":2},{"type":"single","stem":"民族区域自治以什么为基本地域前提？","options":["各少数民族聚居的地方","不考虑聚居条件的全部民族乡","由民族个人自行声明的任何地区","所有设有民族事务部门的地区"],"answer":"A","explain":"第四条指向少数民族聚居地方的区域自治，不是个人随处创设的国家权力。","sectionId":"ch5-s3","articles":["《宪法》第四条","《宪法》第一百一十二条","《宪法》第一百一十五条"],"tags":["民族区域自治","主体识别"],"id":"q-ch5-009","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":1},{"type":"single","stem":"自治县的下列哪个机关属于宪法所指自治机关？","options":["自治县人民法院","自治县人民检察院","自治县监察委员会","自治县人民政府"],"answer":"D","explain":"第一百一十二条将自治机关限定为相应人大和政府，不能扩张到所有当地机关组织。","sectionId":"ch5-s3","articles":["《宪法》第四条","《宪法》第一百一十二条","《宪法》第一百一十五条"],"tags":["民族区域自治","规范适用"],"id":"q-ch5-010","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":1},{"type":"judge","stem":"民族区域自治意味着各民族自治地方可以任意从国家分离。","options":["正确","错误"],"answer":"错误","explain":"第四条明确自治地方是国家不可分离部分，自治不等于独立主权。","sectionId":"ch5-s3","articles":["《宪法》第四条","《宪法》第一百一十二条","《宪法》第一百一十五条"],"tags":["民族区域自治","概念辨析"],"id":"q-ch5-011","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":2},{"type":"judge","stem":"使用和发展本民族语言文字的自由，是第四条体现的民族平等保障之一。","options":["正确","错误"],"answer":"正确","explain":"该条确认各民族语言文字及风俗习惯相关自由，不能只把民族条款读成区划规定。","sectionId":"ch5-s3","articles":["《宪法》第四条","《宪法》第一百一十二条","《宪法》第一百一十五条"],"tags":["民族区域自治","边界判断"],"id":"q-ch5-012","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":2},{"type":"single","stem":"特别行政区内实行制度的宪法规定主体是谁？","options":["国务院以行政法规规定","全国人大常委会单独任意决定","特别行政区政府自行全面确定","全国人大以法律规定"],"answer":"D","explain":"第三十一条确定全国人大以法律规定相关制度，其他主体不具这一宪法权限。","sectionId":"ch5-s4","articles":["《宪法》第三十一条","《宪法》第六十二条"],"tags":["特别行政区","主体识别"],"id":"q-ch5-013","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":1},{"type":"single","stem":"决定特别行政区设立及其制度属于谁的职权？","options":["全国人大常委会","国务院","全国人大","国家主席"],"answer":"C","explain":"第六十二条规定该项全国人大职权，不能按日常管理便利下移。","sectionId":"ch5-s4","articles":["《宪法》第三十一条","《宪法》第六十二条"],"tags":["特别行政区","规范适用"],"id":"q-ch5-014","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":1},{"type":"judge","stem":"特别行政区与民族自治区因名称都含区字而属于完全相同制度。","options":["正确","错误"],"answer":"错误","explain":"其宪法依据、制度安排与主体不同，名称相似不是法律同一性的依据。","sectionId":"ch5-s4","articles":["《宪法》第三十一条","《宪法》第六十二条"],"tags":["特别行政区","概念辨析"],"id":"q-ch5-015","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":2},{"type":"judge","stem":"本节只核验宪法框架，不能据此声称已逐条核验特别行政区基本法细则。","options":["正确","错误"],"answer":"正确","explain":"法源覆盖应按实际检索范围说明，不能以宪法一条替代另一部法律全部条文。","sectionId":"ch5-s4","articles":["《宪法》第三十一条","《宪法》第六十二条"],"tags":["特别行政区","边界判断"],"id":"q-ch5-016","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":2},{"type":"single","stem":"村民委员会在宪法上的组织性质是什么？","options":["地方国家审判机关","全国人大常设机关","基层群众性自治组织","地方国家行政机关"],"answer":"C","explain":"第一百一十一条明确其自治组织属性，不能以公共事务职能改变性质。","sectionId":"ch5-s5","articles":["《宪法》第一百一十一条"],"tags":["基层群众自治","主体识别"],"id":"q-ch5-017","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":1},{"type":"single","stem":"哪项属于村居委会宪法列举的相关工作？","options":["作出最终刑事判决","办理本居住地区公共事务和公益事业","制定国家基本法律","决定全国战争和平"],"answer":"B","explain":"公共公益事务属于其工作范围，立法战争和审判分属其他国家机关职责。","sectionId":"ch5-s5","articles":["《宪法》第一百一十一条"],"tags":["基层群众自治","规范适用"],"id":"q-ch5-018","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":1},{"type":"judge","stem":"村居委会协助维护治安，就自动取得一切行政处罚权。","options":["正确","错误"],"answer":"错误","explain":"协助职能不能凭空转化为完整行政职权，具体权限仍需明确法律依据。","sectionId":"ch5-s5","articles":["《宪法》第一百一十一条"],"tags":["基层群众自治","概念辨析"],"id":"q-ch5-019","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":2},{"type":"judge","stem":"村居委会可以向人民政府反映群众意见要求并提出建议。","options":["正确","错误"],"answer":"正确","explain":"这是第一百一十一条列举的联系群众与政府的作用，不表示其变为政府下属一级政权。","sectionId":"ch5-s5","articles":["《宪法》第一百一十一条"],"tags":["基层群众自治","边界判断"],"id":"q-ch5-020","chapterId":"ch5","chapterTitle":"第五章 国家结构","difficulty":3},{"type":"single","stem":"社会主义经济制度基础在宪法中指什么？","options":["一切财产都禁止转让","生产资料社会主义公有制","个人消费品一律国家所有","所有经营必须私人独资"],"answer":"B","explain":"第六条指生产资料的所有制基础，不应扩张为全部消费品或一切转让禁令。","sectionId":"ch6-s1","articles":["《宪法》第六条"],"tags":["经济制度基础","主体识别"],"id":"q-ch6-001","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":1},{"type":"single","stem":"公有制包括哪两类基本形式？","options":["全民所有制与劳动群众集体所有制","国家所有制与私营企业所有制","集体所有制与个人独资所有制","全民所有制与个人合伙所有制"],"answer":"A","explain":"第六条列举全民和集体两种公有制形式，其他分类不是这一所有制表述。","sectionId":"ch6-s1","articles":["《宪法》第六条"],"tags":["经济制度基础","规范适用"],"id":"q-ch6-002","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":1},{"type":"judge","stem":"公有制为主体、多种所有制共同发展，可以同时成为基本经济制度的内容。","options":["正确","错误"],"answer":"正确","explain":"这不是两个互斥命题，第六条将主体地位与共同发展结合。","sectionId":"ch6-s1","articles":["《宪法》第六条"],"tags":["经济制度基础","概念辨析"],"id":"q-ch6-003","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":2},{"type":"judge","stem":"按劳分配为主体意味着宪法排除任何其他分配方式。","options":["正确","错误"],"answer":"错误","explain":"第六条同时规定多种分配方式并存，主体不等于唯一。","sectionId":"ch6-s1","articles":["《宪法》第六条"],"tags":["经济制度基础","边界判断"],"id":"q-ch6-004","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":3},{"type":"single","stem":"非公有制经济在宪法中的定位是什么？","options":["社会主义市场经济的重要组成部分","一概被禁止的经济形态","不受法律约束的私人领域","具有高于宪法的经济权限"],"answer":"A","explain":"第十一条明确重要组成部分且以法律范围为前提，既不禁止一切也非法律真空。","sectionId":"ch6-s2","articles":["《宪法》第六条","《宪法》第十一条"],"tags":["公有制与非公有制","主体识别"],"id":"q-ch6-005","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":1},{"type":"single","stem":"国家对非公有制经济发展的正确态度是哪组？","options":["只允许监管而不保护","只予保护完全不能管理","以所有制为由任意侵害","鼓励支持引导并依法监督管理"],"answer":"D","explain":"保护发展与依法监管相结合，不能作单边或任意侵害理解。","sectionId":"ch6-s2","articles":["《宪法》第六条","《宪法》第十一条"],"tags":["公有制与非公有制","规范适用"],"id":"q-ch6-006","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":1},{"type":"judge","stem":"私营企业合法权益受保护，所以其违法行为也当然受宪法保护。","options":["正确","错误"],"answer":"错误","explain":"保护对象为合法权益，不能将违法行为纳入同等保护范围。","sectionId":"ch6-s2","articles":["《宪法》第六条","《宪法》第十一条"],"tags":["公有制与非公有制","概念辨析"],"id":"q-ch6-007","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":2},{"type":"judge","stem":"对经营者实施监管，仍须审查监管权限和程序是否合法。","options":["正确","错误"],"answer":"正确","explain":"依法监管中的依法限制监管者权力，不能将管理理解为任意干涉。","sectionId":"ch6-s2","articles":["《宪法》第六条","《宪法》第十一条"],"tags":["公有制与非公有制","边界判断"],"id":"q-ch6-008","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":3},{"type":"single","stem":"城市土地的宪法所有权归属是什么？","options":["集体所有","国家与购房人共同所有","购房人依法取得土地使用权即取得所有权","国家所有"],"answer":"D","explain":"第十条明确城市土地国家所有。","sectionId":"ch6-s3","articles":["《宪法》第十条","《宪法》第十三条"],"tags":["财产权与土地","主体识别"],"id":"q-ch6-009","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":1},{"type":"single","stem":"公共利益需要下对合法私产征收征用，须满足哪组要求？","options":["只由受益企业决定","完全由经办人员自主定价","依照法律规定并给予补偿","仅有口头公共利益声明"],"answer":"C","explain":"第十三条将公共利益法律规定补偿结合，不能只保留目的而删除规范条件。","sectionId":"ch6-s3","articles":["《宪法》第十条","《宪法》第十三条"],"tags":["财产权与土地","规范适用"],"id":"q-ch6-010","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":1},{"type":"judge","stem":"宅基地所有权与个人依法享有的相关使用利益应区分。","options":["正确","错误"],"answer":"正确","explain":"宪法规定宅基地集体所有，个人使用利益不能直接写成私人土地所有权。","sectionId":"ch6-s3","articles":["《宪法》第十条","《宪法》第十三条"],"tags":["财产权与土地","概念辨析"],"id":"q-ch6-011","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":2},{"type":"judge","stem":"宪法禁止非法转让土地，因此土地使用权在任何条件下都不得转让。","options":["正确","错误"],"answer":"错误","explain":"第十条另明确土地使用权可依法转让，必须区分所有权与使用权及合法非法。","sectionId":"ch6-s3","articles":["《宪法》第十条","《宪法》第十三条"],"tags":["财产权与土地","边界判断"],"id":"q-ch6-012","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":3},{"type":"single","stem":"国家发展教育事业的基本目的之一是什么？","options":["仅为已经就业人员提供训练","仅发展高等教育而不发展其他教育","提高全国人民科学文化水平","仅承担学校行政许可而无发展任务"],"answer":"C","explain":"第十九条把教育发展和提高科学文化水平联系。","sectionId":"ch6-s4","articles":["《宪法》第十九条","《宪法》第二十二条"],"tags":["教育文化事业","主体识别"],"id":"q-ch6-013","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":1},{"type":"single","stem":"保护珍贵文物和重要历史文化遗产，属于哪项宪法任务？","options":["劳动就业训练任务","文化事业与文化遗产保护","社会保险救济任务","生态环境污染防治任务"],"answer":"B","explain":"第二十二条对应文化保护，后三项分别属于国家重大决定人事或人身强制程序。","sectionId":"ch6-s4","articles":["《宪法》第十九条","《宪法》第二十二条"],"tags":["教育文化事业","规范适用"],"id":"q-ch6-014","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":1},{"type":"judge","stem":"国家鼓励社会力量依法办教育，不等于教育活动完全不受法律调整。","options":["正确","错误"],"answer":"正确","explain":"第十九条的鼓励保留依法规定这一条件，不能解释为法外经营。","sectionId":"ch6-s4","articles":["《宪法》第十九条","《宪法》第二十二条"],"tags":["教育文化事业","概念辨析"],"id":"q-ch6-015","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":2},{"type":"judge","stem":"宪法发展文化事业，就意味着每个个人文化项目必须获得同额补贴。","options":["正确","错误"],"answer":"错误","explain":"国家任务不是无条件的统一个人给付承诺，具体资助仍须制度依据。","sectionId":"ch6-s4","articles":["《宪法》第十九条","《宪法》第二十二条"],"tags":["教育文化事业","边界判断"],"id":"q-ch6-016","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":3},{"type":"single","stem":"社会保障制度应当与什么相适应？","options":["仅由个人缴费意愿确定","经济发展水平","仅按地区财政结余确定","与所有具体风险条件无关"],"answer":"B","explain":"第十四条强调与经济发展水平相适应，制度安排不是纯个人意愿或口头承诺。","sectionId":"ch6-s5","articles":["《宪法》第十四条","《宪法》第二十六条"],"tags":["社会保障环境","主体识别"],"id":"q-ch6-017","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":1},{"type":"single","stem":"宪法环境任务直接包括什么？","options":["保护改善生活生态环境并防治污染公害","为每个污染争议规定同一赔偿额","禁止一切生产活动","将所有环境纠纷交居民投票终审"],"answer":"A","explain":"第二十六条规定保护改善和污染防治，未提供所有争议统一赔偿或终审机制。","sectionId":"ch6-s5","articles":["《宪法》第十四条","《宪法》第二十六条"],"tags":["社会保障环境","规范适用"],"id":"q-ch6-018","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":1},{"type":"judge","stem":"养老金具体数额可以仅凭宪法国家任务条款直接算出。","options":["正确","错误"],"answer":"错误","explain":"宪法提供制度方向，个人待遇需依具体保障制度条件与标准确定。","sectionId":"ch6-s5","articles":["《宪法》第十四条","《宪法》第二十六条"],"tags":["社会保障环境","概念辨析"],"id":"q-ch6-019","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":2},{"type":"judge","stem":"国家组织鼓励植树造林和保护林木，与环境保护国家任务相关。","options":["正确","错误"],"answer":"正确","explain":"第二十六条明确这一内容，说明国家任务包含具体方向但不包办所有细则。","sectionId":"ch6-s5","articles":["《宪法》第十四条","《宪法》第二十六条"],"tags":["社会保障环境","边界判断"],"id":"q-ch6-020","chapterId":"ch6","chapterTitle":"第六章 经济文化社会制度","difficulty":3},{"type":"single","stem":"判断是否属于中国公民，宪法上的核心依据是什么？","options":["具有中华人民共和国国籍","是否已成年","是否有大学学历","是否拥有住房"],"answer":"A","explain":"第三十三条以国籍识别公民，不以成年教育财产作为一般身份条件。","sectionId":"ch7-s1","articles":["《宪法》第三十三条"],"tags":["公民与平等","主体识别"],"id":"q-ch7-001","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":1},{"type":"single","stem":"判断两类人受到不同待遇是否违反平等，首先应做什么？","options":["看到不同便立即断言违法","只看哪类人数更多","只看工作人员个人喜好","确定比较对象并审查差别理由"],"answer":"D","explain":"平等分析须考察相关差异与正当理由，不是数量或好恶判断。","sectionId":"ch7-s1","articles":["《宪法》第三十三条"],"tags":["公民与平等","规范适用"],"id":"q-ch7-002","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":1},{"type":"judge","stem":"公民必须先拥有选举权，才具有公民身份。","options":["正确","错误"],"answer":"错误","explain":"公民身份按国籍确定；选举权年龄及例外条件并不反向决定一般公民身份。","sectionId":"ch7-s1","articles":["《宪法》第三十三条"],"tags":["公民与平等","概念辨析"],"id":"q-ch7-003","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":2},{"type":"judge","stem":"对未成年人的特别保护，不因与成人规则不同就必然违反平等。","options":["正确","错误"],"answer":"正确","explain":"与年龄相关的合理保护可有正当依据，平等不等于无视所有相关差异。","sectionId":"ch7-s1","articles":["《宪法》第三十三条"],"tags":["公民与平等","边界判断"],"id":"q-ch7-004","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":3},{"type":"single","stem":"哪组属于第三十五条列举的自由？","options":["劳动休息物质帮助","住宅通信与国籍取得","纳税服兵役保守秘密","言论出版集会结社游行示威"],"answer":"D","explain":"第三十五条列六类自由；其余组涉及其他权利或义务，不能混用条款对象。","sectionId":"ch7-s2","articles":["《宪法》第三十四条","《宪法》第三十五条","《宪法》第五十一条"],"tags":["政治权利自由","主体识别"],"id":"q-ch7-005","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":1},{"type":"single","stem":"普通公民甲未当代表，能否因此被一概否认发表公共意见的资格？","options":["能，公民表达必须经代表授权","能，只有选举产生者才可参与公共讨论","不能，言论自由不以代表身份为一般前提","能，表达自由主体仅限履职机关"],"answer":"C","explain":"第三十五条主体为公民，不将当选身份收入或退休作为一般条件。","sectionId":"ch7-s2","articles":["《宪法》第三十四条","《宪法》第三十五条","《宪法》第五十一条"],"tags":["政治权利自由","规范适用"],"id":"q-ch7-006","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":1},{"type":"judge","stem":"享有政治自由意味着可以通过捏造事实诬告他人而免受任何法律评价。","options":["正确","错误"],"answer":"错误","explain":"权利行使仍有边界，不能借自由名义损害他人合法权利。","sectionId":"ch7-s2","articles":["《宪法》第三十四条","《宪法》第三十五条","《宪法》第五十一条"],"tags":["政治权利自由","概念辨析"],"id":"q-ch7-007","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":2},{"type":"judge","stem":"投票选择代表和发表公共意见是不同类型的参与行为。","options":["正确","错误"],"answer":"正确","explain":"前者对应选举权，后者涉及表达自由，主体条件及制度形式不宜混为一谈。","sectionId":"ch7-s2","articles":["《宪法》第三十四条","《宪法》第三十五条","《宪法》第五十一条"],"tags":["政治权利自由","边界判断"],"id":"q-ch7-008","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":3},{"type":"single","stem":"公民自由选择不信教，受哪项规则保护？","options":["选举权","受教育权","宗教信仰自由及不得强制不信教或信教","物质帮助权"],"answer":"C","explain":"第三十六条同时保护信与不信的选择。","sectionId":"ch7-s3","articles":["《宪法》第三十六条"],"tags":["宗教信仰自由","主体识别"],"id":"q-ch7-009","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":1},{"type":"single","stem":"国家保护的宗教活动，在宪法中怎样限定？","options":["任何妨碍教育的活动","正常的宗教活动","任何以宗教名义进行的行为","只由外国势力支配的活动"],"answer":"B","explain":"第三十六条保留正常活动限定并禁止特定有害行为，不能按宗教标签全盘正当化。","sectionId":"ch7-s3","articles":["《宪法》第三十六条"],"tags":["宗教信仰自由","规范适用"],"id":"q-ch7-010","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":1},{"type":"judge","stem":"宗教团体和宗教事务不受外国势力支配，是本条的重要内容。","options":["正确","错误"],"answer":"正确","explain":"第三十六条除个人自由外还规定相应独立性要求，不能只记首句。","sectionId":"ch7-s3","articles":["《宪法》第三十六条"],"tags":["宗教信仰自由","概念辨析"],"id":"q-ch7-011","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":2},{"type":"judge","stem":"以宗教为名损害公民身体健康，可以直接因信仰自由而当然合法。","options":["正确","错误"],"answer":"错误","explain":"该条明确禁止利用宗教损害身体健康等活动，信仰选择与外部行为须分开。","sectionId":"ch7-s3","articles":["《宪法》第三十六条"],"tags":["宗教信仰自由","边界判断"],"id":"q-ch7-012","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":3},{"type":"single","stem":"依宪法，逮捕的执行机关是谁？","options":["人民法院","公安机关","人民检察院","监察委员会"],"answer":"B","explain":"第37条将逮捕的执行权交给公安机关；人民检察院批准或决定、人民法院决定逮捕与公安机关执行逮捕是不同环节。监察委员会不是该条规定的逮捕执行机关。","sectionId":"ch7-s4","articles":["《宪法》第三十七条"],"tags":["人身自由","主体识别"],"id":"q-ch7-013","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":1},{"type":"single","stem":"依宪法，批准或决定逮捕涉及哪组机关？","options":["人民检察院或人民法院","公安机关单独批准决定","监察机关与公安机关任意决定","乡政府与基层自治组织共同决定"],"answer":"A","explain":"条款规定检察院批准决定或法院决定。","sectionId":"ch7-s4","articles":["《宪法》第三十七条"],"tags":["人身自由","规范适用"],"id":"q-ch7-014","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":1},{"type":"judge","stem":"合法限制自由与非法拘禁，应根据主体权限依据程序区分。","options":["正确","错误"],"answer":"正确","explain":"人身自由不是禁止一切依法措施，但合法性不能仅靠限制者口头说明。","sectionId":"ch7-s4","articles":["《宪法》第三十七条"],"tags":["人身自由","概念辨析"],"id":"q-ch7-015","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":2},{"type":"judge","stem":"宪法逮捕条款可以直接替代所有拘留措施的具体期限规则。","options":["正确","错误"],"answer":"错误","explain":"逮捕与拘留不是同一措施，期限须查具体程序法，不能用一条组织权限规则猜数。","sectionId":"ch7-s4","articles":["《宪法》第三十七条"],"tags":["人身自由","边界判断"],"id":"q-ch7-016","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":3},{"type":"single","stem":"非法闯入公民住宅首先涉及哪项宪法保护？","options":["住宅不受侵犯","通信秘密","人身自由的逮捕程序","平等选举资格"],"answer":"A","explain":"第三十九条直接保护住宅空间。","sectionId":"ch7-s5","articles":["《宪法》第三十八条","《宪法》第三十九条","《宪法》第四十条"],"tags":["人格住宅通信","主体识别"],"id":"q-ch7-017","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":1},{"type":"single","stem":"通信检查的宪法例外要求如何理解？","options":["有特定目的即可无需核对机关","有法定机关即可不遵守程序","只要符合法定程序即可不问检查目的","特定目的、法定机关及法定程序相结合"],"answer":"D","explain":"第四十条对目的主体程序均有限制，不能只摘一项更不能以方便替代。","sectionId":"ch7-s5","articles":["《宪法》第三十八条","《宪法》第三十九条","《宪法》第四十条"],"tags":["人格住宅通信","规范适用"],"id":"q-ch7-018","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":1},{"type":"judge","stem":"人格尊严保护禁止侮辱诽谤和诬告陷害，不仅涉及物品损坏。","options":["正确","错误"],"answer":"正确","explain":"第三十八条保护人的基本尊重，不应缩减为财产损害问题。","sectionId":"ch7-s5","articles":["《宪法》第三十八条","《宪法》第三十九条","《宪法》第四十条"],"tags":["人格住宅通信","概念辨析"],"id":"q-ch7-019","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":2},{"type":"judge","stem":"只要涉及通信内容，就一定只涉及通信权而不可能同时涉及人格尊严。","options":["正确","错误"],"answer":"错误","explain":"同一事件可能侵害多个不同权利，须逐项分析，不能强行只选一个保护对象。","sectionId":"ch7-s5","articles":["《宪法》第三十八条","《宪法》第三十九条","《宪法》第四十条"],"tags":["人格住宅通信","边界判断"],"id":"q-ch7-020","chapterId":"ch7","chapterTitle":"第七章 公民基本权利","difficulty":3},{"type":"single","stem":"休息权在宪法直接表述中的主体是谁？","options":["全体公民且无任何主体区别","仅国家机关工作人员","仅已依法退休人员","劳动者"],"answer":"D","explain":"第四十三条表述为劳动者有休息权，不能按其他身份任意缩小或改写。","sectionId":"ch8-s1","articles":["《宪法》第四十二条","《宪法》第四十三条","《宪法》第四十五条"],"tags":["社会经济权利","主体识别"],"id":"q-ch8-001","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":1},{"type":"single","stem":"物质帮助权在第四十五条列明的情形包括什么？","options":["仅与是否已就业相联系","仅与家庭财产多少相联系","年老、疾病或丧失劳动能力","仅与是否享有选举权相联系"],"answer":"C","explain":"条款针对相应生活风险，个人消费偏好或岗位偏好不等同列明前提。","sectionId":"ch8-s1","articles":["《宪法》第四十二条","《宪法》第四十三条","《宪法》第四十五条"],"tags":["社会经济权利","规范适用"],"id":"q-ch8-002","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":1},{"type":"judge","stem":"劳动在宪法中同时具有权利和义务属性。","options":["正确","错误"],"answer":"正确","explain":"第四十二条明确双重表述，不能只强调其中一面。","sectionId":"ch8-s1","articles":["《宪法》第四十二条","《宪法》第四十三条","《宪法》第四十五条"],"tags":["社会经济权利","概念辨析"],"id":"q-ch8-003","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":2},{"type":"judge","stem":"劳动权意味着每人能要求国家立即提供自己指定的任意职位。","options":["正确","错误"],"answer":"错误","explain":"宪法创造条件和保护劳动的制度要求，不等于无条件满足每个个体岗位指定请求。","sectionId":"ch8-s1","articles":["《宪法》第四十二条","《宪法》第四十三条","《宪法》第四十五条"],"tags":["社会经济权利","边界判断"],"id":"q-ch8-004","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":3},{"type":"single","stem":"受教育在第四十六条中具有什么属性？","options":["只有个人可以放弃的权利","只有国家可要求的义务","权利与义务","仅是学校的管理权限"],"answer":"C","explain":"条款对公民同时规定受教育权利义务，不可只用奖励合同或机关权限替代。","sectionId":"ch8-s2","articles":["《宪法》第四十六条","《宪法》第四十七条"],"tags":["教育文化权利","主体识别"],"id":"q-ch8-005","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":1},{"type":"single","stem":"科学研究与文学艺术创作自由对应哪类保障？","options":["政治选举权","文化活动自由","人身自由权","社会物质帮助权"],"answer":"B","explain":"第47条保障科学研究、文学艺术创作和其他文化活动的自由。政治选举、人身自由和物质帮助属于不同基本权利类型。","sectionId":"ch8-s2","articles":["《宪法》第四十六条","《宪法》第四十七条"],"tags":["教育文化权利","规范适用"],"id":"q-ch8-006","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":1},{"type":"judge","stem":"国家鼓励帮助有益于人民的创造性工作，不等于每件作品当然获同额资助。","options":["正确","错误"],"answer":"正确","explain":"鼓励方向与特定给付条件金额不同，具体支持仍需相应制度。","sectionId":"ch8-s2","articles":["《宪法》第四十六条","《宪法》第四十七条"],"tags":["教育文化权利","概念辨析"],"id":"q-ch8-007","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":2},{"type":"judge","stem":"受教育义务要求每个公民无限期在所有学校持续就读。","options":["正确","错误"],"answer":"错误","explain":"宪法双重属性不产生这种无条件无限义务，具体阶段方式须由法律制度落实。","sectionId":"ch8-s2","articles":["《宪法》第四十六条","《宪法》第四十七条"],"tags":["教育文化权利","边界判断"],"id":"q-ch8-008","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":3},{"type":"single","stem":"公民对机关一般工作提出改进意见，首先属于什么？","options":["对违法失职的控告","批评建议","对已作决定的申诉","依法请求国家赔偿"],"answer":"B","explain":"第四十一条包含批评建议，它不要求意见提供者成为审判征税或指挥机关。","sectionId":"ch8-s3","articles":["《宪法》第四十一条"],"tags":["监督与救济","主体识别"],"id":"q-ch8-009","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":1},{"type":"single","stem":"公民举报违法失职后，有关机关宪法上应如何处理？","options":["查清事实负责处理，不得压制报复","仅接受意见而无需查明事实","只对最终被证实正确者提供保护","一律按举报内容直接认定违法"],"answer":"A","explain":"既要核实事实又要保护监督，不能不核实或压制，更不能随意移交私人。","sectionId":"ch8-s3","articles":["《宪法》第四十一条"],"tags":["监督与救济","规范适用"],"id":"q-ch8-010","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":1},{"type":"judge","stem":"行使监督权时不得捏造歪曲事实诬告陷害。","options":["正确","错误"],"answer":"正确","explain":"第四十一条明确监督权的事实边界，保护监督不是许可造假。","sectionId":"ch8-s3","articles":["《宪法》第四十一条"],"tags":["监督与救济","概念辨析"],"id":"q-ch8-011","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":2},{"type":"judge","stem":"由于国家机关侵犯权利受损，可以不依法律条件任意索取任何金额赔偿。","options":["正确","错误"],"answer":"错误","explain":"条款规定依法取得赔偿，具体成立条件和数额仍须法律规则支撑。","sectionId":"ch8-s3","articles":["《宪法》第四十一条"],"tags":["监督与救济","边界判断"],"id":"q-ch8-012","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":3},{"type":"single","stem":"权利行使不得损害哪些利益，符合第五十一条表述？","options":["国家社会集体利益与其他公民合法自由权利","仅本人经济利益","仅机关工作方便","仅多数人个人喜好"],"answer":"A","explain":"第五十一条列多类受保护利益，不能缩为便利或好恶。","sectionId":"ch8-s4","articles":["《宪法》第五十一条","《宪法》第五条"],"tags":["权利限制边界","主体识别"],"id":"q-ch8-013","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":1},{"type":"single","stem":"教材限制审查为什么需要追问是否有规范依据？","options":["用目的正当取代权限依据","用受益人数取代全部合法性判断","以机关职责抽象表述作为任何限制授权","防止以抽象目的掩盖无权干预"],"answer":"D","explain":"依据审查约束公权力，既不预设取消自由也不免除说明和合法性要求。","sectionId":"ch8-s4","articles":["《宪法》第五十一条","《宪法》第五条"],"tags":["权利限制边界","规范适用"],"id":"q-ch8-014","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":1},{"type":"judge","stem":"权利不是绝对的，并不意味着国家权力没有边界。","options":["正确","错误"],"answer":"正确","explain":"权利限制与权力约束应同时讨论，不能用前者推出无限权限。","sectionId":"ch8-s4","articles":["《宪法》第五十一条","《宪法》第五条"],"tags":["权利限制边界","概念辨析"],"id":"q-ch8-015","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":2},{"type":"judge","stem":"限制目的正当就足以证明手段无论多宽都合法适当。","options":["正确","错误"],"answer":"错误","explain":"目的和手段是不同审查环节，仍需考察权限必要性及适当范围。","sectionId":"ch8-s4","articles":["《宪法》第五十一条","《宪法》第五条"],"tags":["权利限制边界","边界判断"],"id":"q-ch8-016","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":3},{"type":"single","stem":"公民依法纳税的直接宪法依据对应哪项义务？","options":["缴纳行政机关要求的任何费用","为公共项目承担所有摊派","以自愿捐赠代替法定税收","依照法律纳税"],"answer":"D","explain":"第五十六条重依法纳税，任意收费和交易义务不能冒充税收义务。","sectionId":"ch8-s5","articles":["《宪法》第五十二条","《宪法》第五十三条","《宪法》第五十四条","《宪法》第五十五条","《宪法》第五十六条","《宪法》第四十二条","《宪法》第四十六条"],"tags":["基本义务","主体识别"],"id":"q-ch8-017","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":1},{"type":"single","stem":"维护国家统一和民族团结属于什么？","options":["国家机关组织权限","仅对军人规定的特殊职责","公民基本义务","仅作为国家发展目标而非公民义务"],"answer":"C","explain":"第五十二条向中国公民规定该项义务，不是局部单位或特定私法交易要求。","sectionId":"ch8-s5","articles":["《宪法》第五十二条","《宪法》第五十三条","《宪法》第五十四条","《宪法》第五十五条","《宪法》第五十六条","《宪法》第四十二条","《宪法》第四十六条"],"tags":["基本义务","规范适用"],"id":"q-ch8-018","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":1},{"type":"judge","stem":"服兵役和参加民兵组织应依照法律，不等于任何人随时可强令所有公民立即服现役。","options":["正确","错误"],"answer":"正确","explain":"第五十五条保留依法条件，具体对象程序须由相应法律确定。","sectionId":"ch8-s5","articles":["《宪法》第五十二条","《宪法》第五十三条","《宪法》第五十四条","《宪法》第五十五条","《宪法》第五十六条","《宪法》第四十二条","《宪法》第四十六条"],"tags":["基本义务","概念辨析"],"id":"q-ch8-019","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":2},{"type":"judge","stem":"宪法写有基本义务，便足以不经其他依据对所有违背者施以任意刑罚。","options":["正确","错误"],"answer":"错误","explain":"义务与具体责任不同，处罚尤其刑罚仍须相应法律依据及程序。","sectionId":"ch8-s5","articles":["《宪法》第五十二条","《宪法》第五十三条","《宪法》第五十四条","《宪法》第五十五条","《宪法》第五十六条","《宪法》第四十二条","《宪法》第四十六条"],"tags":["基本义务","边界判断"],"id":"q-ch8-020","chapterId":"ch8","chapterTitle":"第八章 权利保障与基本义务","difficulty":3},{"type":"single","stem":"全国人大的宪法机构地位是什么？","options":["最高国家审判机关","国家基层自治组织","最高国家权力机关","最高国家行政机关"],"answer":"C","explain":"第五十七条定位全国人大为最高国家权力机关，不能与国务院法院或自治组织混同。","sectionId":"ch9-s1","articles":["《宪法》第五十七条","《宪法》第六十二条"],"tags":["全国人大","机关定位"],"id":"q-ch9-001","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":1},{"type":"single","stem":"国家预算审查批准属于下列哪一机关的宪法职权？","options":["全国人大常委会","全国人大","国务院","财政部"],"answer":"B","explain":"第62条规定全国人大审查和批准国家预算及预算执行情况的报告。国务院承担预算编制执行等行政职责；常委会另有闭会期间审查批准预算部分调整等职权，财政部不能代替全国人大行使本题职权。","sectionId":"ch9-s1","articles":["《宪法》第五十七条","《宪法》第六十二条"],"tags":["全国人大","权限规则"],"id":"q-ch9-002","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":1},{"type":"judge","stem":"全国人大可以依宪法改变或者撤销其常委会不适当的决定。","options":["正确","错误"],"answer":"正确","explain":"第六十二条规定这一内部监督纠正权限，体现全国人大与常设机关的制度关系。","sectionId":"ch9-s1","articles":["《宪法》第五十七条","《宪法》第六十二条"],"tags":["全国人大","制度联系"],"id":"q-ch9-003","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":2},{"type":"judge","stem":"全国人大代表个人能够自行选举产生国家主席而不需机关程序。","options":["正确","错误"],"answer":"错误","explain":"选举国家主席是全国人大整体职权，不能缩为代表个人决定。","sectionId":"ch9-s1","articles":["《宪法》第五十七条","《宪法》第六十二条"],"tags":["全国人大","适用边界"],"id":"q-ch9-004","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":3},{"type":"single","stem":"全国人大常委会是全国人大的什么机关？","options":["全国人大的执行机关","常设机关","与全国人大平行的最高权力机关","全国人大的行政职能部门"],"answer":"B","explain":"第57条规定全国人大常委会是全国人大的常设机关。国务院是最高国家权力机关的执行机关；常委会既非与全国人大平行的另一个最高权力机关，也非其行政部门。","sectionId":"ch9-s2","articles":["《宪法》第五十七条","《宪法》第六十七条","《宪法》第六十二条"],"tags":["全国人大常委会","机关定位"],"id":"q-ch9-005","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":1},{"type":"single","stem":"解释宪法由哪个机关行使？","options":["全国人大常委会","全国人大","国务院","最高人民法院"],"answer":"A","explain":"第六十七条明确有权主体，行政部门司法机关教学机构不能因此取得同等权力。","sectionId":"ch9-s2","articles":["《宪法》第五十七条","《宪法》第六十七条","《宪法》第六十二条"],"tags":["全国人大常委会","权限规则"],"id":"q-ch9-006","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":1},{"type":"judge","stem":"全国人大闭会期间，全国人大常委会对全国人大制定的法律作部分补充修改，不得同该法基本原则抵触。","options":["正确","错误"],"answer":"正确","explain":"第六十七条第三项规定的闭会主体是全国人大，行使部分补充修改职权的主体是全国人大常委会。该权限受不得抵触该法基本原则的限制，不能改成常委会闭会期间或任意全面修改。","sectionId":"ch9-s2","articles":["《宪法》第五十七条","《宪法》第六十七条","《宪法》第六十二条"],"tags":["全国人大常委会","制度联系"],"id":"q-ch9-007","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":2},{"type":"judge","stem":"全国人大常委会解释法律和解释宪法，是宪法条款中毫无区分的一项私人咨询活动。","options":["正确","错误"],"answer":"错误","explain":"两者都是法定职权且有不同对象，不是私人意见，不能抹平对象和权限属性。","sectionId":"ch9-s2","articles":["《宪法》第五十七条","《宪法》第六十七条","《宪法》第六十二条"],"tags":["全国人大常委会","适用边界"],"id":"q-ch9-008","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":3},{"type":"single","stem":"国家主席根据有关决定公布法律，体现什么制度衔接？","options":["有关机关决定与主席公布的衔接","国家主席提议与个人立法的衔接","法院审判与国家主席改判的衔接","国务院决定与主席独立修宪的衔接"],"answer":"A","explain":"第八十条把主席相关行为与全国人大及常委会决定相联系，不能将公布等同私人立法。","sectionId":"ch9-s3","articles":["《宪法》第八十条","《宪法》第八十五条"],"tags":["国家主席","机关定位"],"id":"q-ch9-009","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":1},{"type":"single","stem":"以下哪项可见于第八十条列举的主席职权？","options":["作出特赦决定","独立修改宪法","审查批准国家预算","发布特赦令"],"answer":"D","explain":"第80条列明国家主席根据有关决定发布特赦令；决定特赦的是全国人大常委会。修宪和审查批准国家预算属于全国人大职权，不能与发布命令混同。","sectionId":"ch9-s3","articles":["《宪法》第八十条","《宪法》第八十五条"],"tags":["国家主席","权限规则"],"id":"q-ch9-010","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":1},{"type":"judge","stem":"国家主席公布法律时，可以因个人不同意见任意删改已通过条文。","options":["正确","错误"],"answer":"错误","explain":"公布根据有关决定履职，不产生任意改写通过文本的权限。","sectionId":"ch9-s3","articles":["《宪法》第八十条","《宪法》第八十五条"],"tags":["国家主席","制度联系"],"id":"q-ch9-011","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":2},{"type":"judge","stem":"任免国务院有关人员的决定与主席依决定任免，应在答题时区分。","options":["正确","错误"],"answer":"正确","explain":"制度分工涉及提名决定任免不同环节，不能把全部权能集中解释给单一主体。","sectionId":"ch9-s3","articles":["《宪法》第八十条","《宪法》第八十五条"],"tags":["国家主席","适用边界"],"id":"q-ch9-012","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":3},{"type":"single","stem":"国务院另一个宪法名称是什么？","options":["全国人大常委会","最高人民法院","国家监察委员会","中央人民政府"],"answer":"D","explain":"第八十五条明确国务院即中央人民政府，错误项为不同机关。","sectionId":"ch9-s4","articles":["《宪法》第八十五条","《宪法》第三条","《宪法》第六十七条"],"tags":["国务院","机关定位"],"id":"q-ch9-013","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":1},{"type":"single","stem":"称国务院为最高国家权力机关的执行机关，主要说明什么？","options":["国务院是全国人大常委会本身","国务院直接行使全部审判权","其与最高权力机关的制度关系","国务院不受其他机关监督"],"answer":"C","explain":"执行机关定位与最高行政机关定位并存，不是法外地位或机关完全同一。","sectionId":"ch9-s4","articles":["《宪法》第八十五条","《宪法》第三条","《宪法》第六十七条"],"tags":["国务院","权限规则"],"id":"q-ch9-014","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":1},{"type":"judge","stem":"国务院受到全国人大常委会监督，与其依法履行最高行政机关职责并不矛盾。","options":["正确","错误"],"answer":"正确","explain":"职能履行与制度监督属于不同层次，相互联系而非彼此取消。","sectionId":"ch9-s4","articles":["《宪法》第八十五条","《宪法》第三条","《宪法》第六十七条"],"tags":["国务院","制度联系"],"id":"q-ch9-015","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":2},{"type":"judge","stem":"一切带有中央名称的机关都属于国务院普通行政部门。","options":["正确","错误"],"answer":"错误","explain":"中央机构中有权力监察审判检察军事等不同机关，名称不能替代性质判断。","sectionId":"ch9-s4","articles":["《宪法》第八十五条","《宪法》第三条","《宪法》第六十七条"],"tags":["国务院","适用边界"],"id":"q-ch9-016","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":3},{"type":"single","stem":"中央军委的基本宪法职责是什么？","options":["监督全国人大常委会的工作","决定全国基本法律的修改","领导全国武装力量","统一行使国家检察权"],"answer":"C","explain":"第九十三条定位其军事领导职责，其他事项不属于这一基本定位。","sectionId":"ch9-s5","articles":["《宪法》第九十三条","《宪法》第六十二条","《宪法》第六十七条"],"tags":["中央军委","机关定位"],"id":"q-ch9-017","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":1},{"type":"single","stem":"中央军委实行哪种负责制？","options":["集体负责制而非主席负责制","主席负责制","总理负责制","地方行政首长负责制"],"answer":"B","explain":"第九十三条明确主席负责制，不可因委员会名称推定为其他负责模式。","sectionId":"ch9-s5","articles":["《宪法》第九十三条","《宪法》第六十二条","《宪法》第六十七条"],"tags":["中央军委","权限规则"],"id":"q-ch9-018","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":1},{"type":"judge","stem":"中央军委委员和副主席的具体人数，可以从条文若干人直接推出固定数字。","options":["正确","错误"],"answer":"错误","explain":"若干人不是固定人数，不能将未确定的数目凭记忆补全为法定定数。","sectionId":"ch9-s5","articles":["《宪法》第九十三条","《宪法》第六十二条","《宪法》第六十七条"],"tags":["中央军委","制度联系"],"id":"q-ch9-019","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":2},{"type":"judge","stem":"中央军委的任期在宪法上与全国人大每届任期相同。","options":["正确","错误"],"answer":"正确","explain":"第九十三条规定任期联系，理解制度联系不需把未核验的细数加入题干。","sectionId":"ch9-s5","articles":["《宪法》第九十三条","《宪法》第六十二条","《宪法》第六十七条"],"tags":["中央军委","适用边界"],"id":"q-ch9-020","chapterId":"ch9","chapterTitle":"第九章 中央国家机构上","difficulty":3},{"type":"single","stem":"各级监察委员会是什么国家机关？","options":["法律监督机关","监察机关","行政机关","审判机关"],"answer":"B","explain":"第123条将各级监察委员会定位为国家监察机关。人民法院是审判机关，人民检察院是法律监督机关，人民政府是行政机关。","sectionId":"ch10-s1","articles":["《宪法》第一百二十三条","《宪法》第一百二十七条","《宪法》第三条"],"tags":["监察委员会","机关定位"],"id":"q-ch10-001","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":1},{"type":"single","stem":"监察机关办职务违法犯罪案件，宪法要求与相关机关怎样联系？","options":["互相配合互相制约","上下级行政领导关系","同一机关内部科室关系","单方决定而其他机关无条件服从"],"answer":"A","explain":"第一百二十七条同时规定配合制约，不支持无联系或单向取消制约。","sectionId":"ch10-s1","articles":["《宪法》第一百二十三条","《宪法》第一百二十七条","《宪法》第三条"],"tags":["监察委员会","权限规则"],"id":"q-ch10-002","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":1},{"type":"judge","stem":"监察机关依法独立行使监察权，意味着不受任何法律约束。","options":["正确","错误"],"answer":"错误","explain":"独立行使以依照法律为前提，并非脱离法律的主权式权力。","sectionId":"ch10-s1","articles":["《宪法》第一百二十三条","《宪法》第一百二十七条","《宪法》第三条"],"tags":["监察委员会","制度联系"],"id":"q-ch10-003","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":2},{"type":"judge","stem":"不能把监察委员会对职务犯罪案件的工作直接等同于法院作出刑事判决。","options":["正确","错误"],"answer":"正确","explain":"监察权与审判权不同，案件衔接不取消机关职能边界。","sectionId":"ch10-s1","articles":["《宪法》第一百二十三条","《宪法》第一百二十七条","《宪法》第三条"],"tags":["监察委员会","适用边界"],"id":"q-ch10-004","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":3},{"type":"single","stem":"人民法院的宪法性质是什么？","options":["国家审判机关","国家监察机关","最高国家行政机关","村民自治组织"],"answer":"A","explain":"第一百二十八条定位审判机关，其余是不同机构类型。","sectionId":"ch10-s2","articles":["《宪法》第一百二十八条","《宪法》第六十七条","《宪法》第三条"],"tags":["人民法院","机关定位"],"id":"q-ch10-005","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":1},{"type":"single","stem":"甲称普通法院有权一般性撤销全国法律，主要应质疑什么？","options":["把解释法律与修改法律混为一谈","把国家权力机关与行政机关定位混同","把直接与间接选举路径颠倒","不能从审判地位推定普遍宪法审查权"],"answer":"D","explain":"职权必须有法源依据，审判地位不能自动产生一般撤法权，人员楼层数量均不能补足。","sectionId":"ch10-s2","articles":["《宪法》第一百二十八条","《宪法》第六十七条","《宪法》第三条"],"tags":["人民法院","权限规则"],"id":"q-ch10-006","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":1},{"type":"judge","stem":"人大监督法院与法院依法履行审判职责可以同时存在。","options":["正确","错误"],"answer":"正确","explain":"制度监督与审判分工并不矛盾，但监督不等于替代机关直接包办全部个案裁判。","sectionId":"ch10-s2","articles":["《宪法》第一百二十八条","《宪法》第六十七条","《宪法》第三条"],"tags":["人民法院","制度联系"],"id":"q-ch10-007","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":2},{"type":"judge","stem":"宪法解释由全国人大常委会行使，因此法院已经不再属于国家审判机关。","options":["正确","错误"],"answer":"错误","explain":"解释与审判分别配置，不是一个权限存在就消灭另一个机关的基本性质。","sectionId":"ch10-s2","articles":["《宪法》第一百二十八条","《宪法》第六十七条","《宪法》第三条"],"tags":["人民法院","适用边界"],"id":"q-ch10-008","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":3},{"type":"single","stem":"人民检察院的宪法性质是什么？","options":["最高行政机关","基层群众自治组织","国家军事领导机关","国家法律监督机关"],"answer":"D","explain":"第一百三十四条明确法律监督定位，其他机关性质与之不同。","sectionId":"ch10-s3","articles":["《宪法》第一百三十四条","《宪法》第一百三十六条","《宪法》第一百二十八条"],"tags":["人民检察院","机关定位"],"id":"q-ch10-009","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":1},{"type":"single","stem":"检察权独立行使的宪法要求，哪项准确？","options":["独立即不受宪法法律约束","独立即不存在人大监督","依法行使，不受行政机关社会团体个人干涉","只有行政机关可以决定检察权行使"],"answer":"C","explain":"第一百三十六条保留依法和特定干涉主体限定，不是法外权力也不否认机构监督。","sectionId":"ch10-s3","articles":["《宪法》第一百三十四条","《宪法》第一百三十六条","《宪法》第一百二十八条"],"tags":["人民检察院","权限规则"],"id":"q-ch10-010","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":1},{"type":"judge","stem":"检察院作为法律监督机关，意味着其可以任意替代所有其他机关办理任何事务。","options":["正确","错误"],"answer":"错误","explain":"机关定位不产生无限权限，具体检察职权与实现方式仍须法律依据。","sectionId":"ch10-s3","articles":["《宪法》第一百三十四条","《宪法》第一百三十六条","《宪法》第一百二十八条"],"tags":["人民检察院","制度联系"],"id":"q-ch10-011","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":2},{"type":"judge","stem":"监察委员会与检察院即使都涉及违法犯罪问题，也不是同一机关。","options":["正确","错误"],"answer":"正确","explain":"二者的宪法性质分别为监察机关和法律监督机关，业务交叉不取消组织区分。","sectionId":"ch10-s3","articles":["《宪法》第一百三十四条","《宪法》第一百三十六条","《宪法》第一百二十八条"],"tags":["人民检察院","适用边界"],"id":"q-ch10-012","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":3},{"type":"single","stem":"职务犯罪案件的配合制约关系，宪法所列相关机关包括哪组？","options":["仅监察机关与政府机关","仅审判机关与人大常委会","审判检察机关及执法部门","仅检察机关与行政机关"],"answer":"C","explain":"第127条要求监察机关办理职务违法和职务犯罪案件时，与审判机关、检察机关、执法部门互相配合、互相制约，不能把法定主体范围缩为某两类机关。","sectionId":"ch10-s4","articles":["《宪法》第一百二十七条","《宪法》第一百二十八条","《宪法》第一百三十四条"],"tags":["监察司法相互关系","机关定位"],"id":"q-ch10-013","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":1},{"type":"single","stem":"配合与制约应如何理解？","options":["配合取代独立法定分工","依法衔接并防止错误权力失衡","制约排除必要机关衔接","案件移送即要求接收机关无条件采纳全部结论"],"answer":"B","explain":"两者互补，不能单方面取消。","sectionId":"ch10-s4","articles":["《宪法》第一百二十七条","《宪法》第一百二十八条","《宪法》第一百三十四条"],"tags":["监察司法相互关系","权限规则"],"id":"q-ch10-014","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":1},{"type":"judge","stem":"监察机关与法院检察院合作，就意味着案件中的法定职责已经合为一个职权。","options":["正确","错误"],"answer":"错误","explain":"配合并未取消监察审判检察的不同性质和职责，仍须分工履职。","sectionId":"ch10-s4","articles":["《宪法》第一百二十七条","《宪法》第一百二十八条","《宪法》第一百三十四条"],"tags":["监察司法相互关系","制度联系"],"id":"q-ch10-015","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":2},{"type":"judge","stem":"讨论三机关相互关系时，写清案件类型比只写机关名字更完整。","options":["正确","错误"],"answer":"正确","explain":"不同条款对应职务违法犯罪或刑事案件等场景，主体和场景共同决定关系内容。","sectionId":"ch10-s4","articles":["《宪法》第一百二十七条","《宪法》第一百二十八条","《宪法》第一百三十四条"],"tags":["监察司法相互关系","适用边界"],"id":"q-ch10-016","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":3},{"type":"single","stem":"宪法关于办理刑事案件的分工关系，明确涉及哪组三机关？","options":["监察委、法院、检察院","法院、检察院、公安机关","人大常委会、法院、公安机关","政府、监察委、检察院"],"answer":"B","explain":"第一百四十条列法院检察院公安，其他组合不对应这一刑事职责框架。","sectionId":"ch10-s5","articles":["《宪法》第一百四十条","《宪法》第三十七条"],"tags":["宪法职责与诉讼","机关定位"],"id":"q-ch10-017","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":1},{"type":"single","stem":"查询刑事拘留的具体期限，应进一步检索什么？","options":["相应现行诉讼法律规则","仅核宪法关于逮捕的规定","仅核机关组织法的职责条款","仅核公安机关名称及层级"],"answer":"A","explain":"期限属于具体程序法，不可仅凭宪法组织原则或无关内部规则回答。","sectionId":"ch10-s5","articles":["《宪法》第一百四十条","《宪法》第三十七条"],"tags":["宪法职责与诉讼","权限规则"],"id":"q-ch10-018","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":1},{"type":"judge","stem":"分工负责与互相配合互相制约，是宪法要求共同把握的内容。","options":["正确","错误"],"answer":"正确","explain":"第一百四十条三方面结合，不能只写合作而抹掉负责和制约。","sectionId":"ch10-s5","articles":["《宪法》第一百四十条","《宪法》第三十七条"],"tags":["宪法职责与诉讼","制度联系"],"id":"q-ch10-019","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":2},{"type":"judge","stem":"公检法刑事案件关系可以不作区分地作为全部民事案件的完整程序。","options":["正确","错误"],"answer":"错误","explain":"案件类型与制度场景不同，刑事条款不是所有诉讼的统一详细步骤。","sectionId":"ch10-s5","articles":["《宪法》第一百四十条","《宪法》第三十七条"],"tags":["宪法职责与诉讼","适用边界"],"id":"q-ch10-020","chapterId":"ch10","chapterTitle":"第十章 中央机构下与司法监察","difficulty":3},{"type":"single","stem":"地方各级人大的基本机构地位是什么？","options":["地方国家权力机关","地方国家行政机关","地方国家审判机关","基层群众性自治组织"],"answer":"A","explain":"第96条规定地方各级人民代表大会是地方国家权力机关；地方政府属于行政机关，地方人民法院属于审判机关，村居民委员会属于基层群众性自治组织。","sectionId":"ch11-s1","articles":["《宪法》第九十六条","《宪法》第三条","《宪法》第一百零五条"],"tags":["地方人大","机关定位"],"id":"q-ch11-001","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":1},{"type":"single","stem":"宪法规定哪些地方人大设常委会？","options":["所有地方人大不分层级","仅省级人大","县级以下所有地方人大","县级以上地方各级人大"],"answer":"D","explain":"第九十六条有层级条件，自治组织和临时会议不是地方人大常委会的设置主体。","sectionId":"ch11-s1","articles":["《宪法》第九十六条","《宪法》第三条","《宪法》第一百零五条"],"tags":["地方人大","权限规则"],"id":"q-ch11-002","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":1},{"type":"judge","stem":"地方人大对政府的监督关系，可以解释成地方人大是政府下属办事科室。","options":["正确","错误"],"answer":"错误","explain":"监督产生等关系不等于行政隶属，更不能颠倒权力机关和行政机关地位。","sectionId":"ch11-s1","articles":["《宪法》第九十六条","《宪法》第三条","《宪法》第一百零五条"],"tags":["地方人大","制度联系"],"id":"q-ch11-003","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":2},{"type":"judge","stem":"分析县人大与县政府，应区分国家权力机关与行政机关。","options":["正确","错误"],"answer":"正确","explain":"两者均是国家机关但性质和职责不同，同一县域不意味着组织同一。","sectionId":"ch11-s1","articles":["《宪法》第九十六条","《宪法》第三条","《宪法》第一百零五条"],"tags":["地方人大","适用边界"],"id":"q-ch11-004","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":3},{"type":"single","stem":"县人大常委会可监督哪组本级机关的工作？","options":["本级政府及上级法院检察院","本级政府及所有上级行政机关","仅本级政府而不涉及其他机关","政府、监察委、法院、检察院"],"answer":"D","explain":"第一百零四条列明本级相关机关，不能替换为国际主体或仅股东会。","sectionId":"ch11-s2","articles":["《宪法》第九十六条","《宪法》第一百零四条"],"tags":["地方人大常委会","机关定位"],"id":"q-ch11-005","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":1},{"type":"single","stem":"地方常委会讨论决定本区域重大事项，属于哪类行为？","options":["代行本级政府全部日常行政权","代行本级法院全部案件裁判权","依法行使法定职权","由常委会成员个人决定公共事项"],"answer":"C","explain":"第一百零四条为常委会规定重大事项职责，不是私法合同或行政企业日常管理。","sectionId":"ch11-s2","articles":["《宪法》第九十六条","《宪法》第一百零四条"],"tags":["地方人大常委会","权限规则"],"id":"q-ch11-006","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":1},{"type":"judge","stem":"乡镇人大依宪法都应设置与县人大同样的常委会。","options":["正确","错误"],"answer":"错误","explain":"第九十六条为县级以上设置常委会，不能无条件推及乡镇。","sectionId":"ch11-s2","articles":["《宪法》第九十六条","《宪法》第一百零四条"],"tags":["地方人大常委会","制度联系"],"id":"q-ch11-007","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":2},{"type":"judge","stem":"县人大常委会可依宪法撤销本级政府不适当决定命令。","options":["正确","错误"],"answer":"正确","explain":"第一百零四条明确这一纠正职权，但不能据此扩大为任意代行所有政府职责。","sectionId":"ch11-s2","articles":["《宪法》第九十六条","《宪法》第一百零四条"],"tags":["地方人大常委会","适用边界"],"id":"q-ch11-008","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":3},{"type":"single","stem":"地方政府具有哪两项相联系的宪法定位？","options":["本级权力机关与国家监察机关","基层自治组织与地方行政机关","本级权力机关执行机关与地方行政机关","审判机关与法律监督机关"],"answer":"C","explain":"第一百零五条同时规定执行与行政定位。","sectionId":"ch11-s3","articles":["《宪法》第一百零五条","《宪法》第一百一十条"],"tags":["地方政府","机关定位"],"id":"q-ch11-009","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":1},{"type":"single","stem":"地方各级政府实行的领导责任制度，宪法怎样规定？","options":["以人大代表个人意见负责制","相应行政首长负责制","以法院院长统一负责地方行政","以集体表决完全排除行政首长责任"],"answer":"B","explain":"第一百零五条列相应省市县区乡镇长负责制，不是企业或审判安排。","sectionId":"ch11-s3","articles":["《宪法》第一百零五条","《宪法》第一百一十条"],"tags":["地方政府","权限规则"],"id":"q-ch11-010","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":1},{"type":"judge","stem":"政府首长负责就可以拒绝向本级人大报告工作。","options":["正确","错误"],"answer":"错误","explain":"负责制与人大监督并存，第一百一十条明确向本级人大负责报告。","sectionId":"ch11-s3","articles":["《宪法》第一百零五条","《宪法》第一百一十条"],"tags":["地方政府","制度联系"],"id":"q-ch11-011","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":2},{"type":"judge","stem":"县政府在本级人大闭会期间，对本级人大常委会负责并报告工作。","options":["正确","错误"],"answer":"正确","explain":"第一百一十条对县级以上闭会期间作此安排，不可遗漏层级与时间条件。","sectionId":"ch11-s3","articles":["《宪法》第一百零五条","《宪法》第一百一十条"],"tags":["地方政府","适用边界"],"id":"q-ch11-012","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":3},{"type":"single","stem":"下列哪组是民族自治地方自治机关？","options":["自治地方的法院和检察院","自治区自治州自治县人大和政府","民族乡人大和政府","自治地方所有国家机关"],"answer":"B","explain":"第一百一十二条限定地域与机关类型，不能泛指当地所有机关社会团体。","sectionId":"ch11-s4","articles":["《宪法》第一百一十二条","《宪法》第一百一十五条","《宪法》第三十条"],"tags":["自治机关","机关定位"],"id":"q-ch11-013","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":1},{"type":"single","stem":"自治机关行使自治权，应依据什么？","options":["宪法和相关法律规定的权限","个别负责人临时偏好","任何社会团体口号","境外机构自由授权"],"answer":"A","explain":"第一百一十五条坚持法定权限，自治不是法外或外部任意授权。","sectionId":"ch11-s4","articles":["《宪法》第一百一十二条","《宪法》第一百一十五条","《宪法》第三十条"],"tags":["自治机关","权限规则"],"id":"q-ch11-014","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":1},{"type":"judge","stem":"自治机关只有自治权，不具有一般地方国家机关的职权。","options":["正确","错误"],"answer":"错误","explain":"第一百一十五条明确同时行使一般地方职权与法定自治权，两方面并存。","sectionId":"ch11-s4","articles":["《宪法》第一百一十二条","《宪法》第一百一十五条","《宪法》第三十条"],"tags":["自治机关","制度联系"],"id":"q-ch11-015","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":2},{"type":"judge","stem":"根据本地实际贯彻执行国家法律政策，不等于任意宣布国家法律不适用。","options":["正确","错误"],"answer":"正确","explain":"因地制宜须处在法定权限内，不能把灵活落实变为无依据排除法律。","sectionId":"ch11-s4","articles":["《宪法》第一百一十二条","《宪法》第一百一十五条","《宪法》第三十条"],"tags":["自治机关","适用边界"],"id":"q-ch11-016","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":3},{"type":"single","stem":"地方政府向上一级国家行政机关负责，体现哪条关系？","options":["行政系统纵向负责关系","权力机关与执行机关的横向监督","司法机关上下级审级关系","自治机关与群众自治组织关系"],"answer":"A","explain":"第一百一十条规定行政系统负责报告，不能与审判层级或自治选举混同。","sectionId":"ch11-s5","articles":["《宪法》第三条","《宪法》第一百一十条"],"tags":["中央地方关系","机关定位"],"id":"q-ch11-017","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":1},{"type":"single","stem":"全国地方各级政府处在哪个机关的统一领导下？","options":["全国人大常委会直接行政领导","最高人民法院","国家监察委员会","国务院"],"answer":"D","explain":"第一百一十条明确国务院统一领导，不是经济组织司法机关或自治组织。","sectionId":"ch11-s5","articles":["《宪法》第三条","《宪法》第一百一十条"],"tags":["中央地方关系","权限规则"],"id":"q-ch11-018","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":1},{"type":"judge","stem":"地方政府对上级负责，就不再对本级人大负责。","options":["正确","错误"],"answer":"错误","explain":"两条负责关系并存，不应以纵向行政联系抹掉横向权力机关监督。","sectionId":"ch11-s5","articles":["《宪法》第三条","《宪法》第一百一十条"],"tags":["中央地方关系","制度联系"],"id":"q-ch11-019","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":2},{"type":"judge","stem":"中央统一领导下发挥地方主动积极性，是理解中央地方职权划分的原则。","options":["正确","错误"],"answer":"正确","explain":"第三条将统一与地方积极性结合，不能只讲一面。","sectionId":"ch11-s5","articles":["《宪法》第三条","《宪法》第一百一十条"],"tags":["中央地方关系","适用边界"],"id":"q-ch11-020","chapterId":"ch11","chapterTitle":"第十一章 地方国家机关","difficulty":3},{"type":"single","stem":"宪法实施的教材含义主要是什么？","options":["仅完成一次朗读","只印刷更多文本","只增加课程考试次数","宪法规范在现实活动中得到落实"],"answer":"D","explain":"实施重实际规范运行，宣传印刷考试可辅助但不能替代落实。","sectionId":"ch12-s1","articles":["《宪法》第五条"],"tags":["实施与遵守","机关定位"],"id":"q-ch12-001","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":1},{"type":"single","stem":"某法规抵触宪法，举办宣传活动之后应怎样认识？","options":["文件印量大即可免责","只要名称正确便不抵触","仍应依机制处理抵触问题","宣传自动使抵触合法"],"answer":"C","explain":"宣传不改变规范抵触性质，须依法纠正而不是用数量名称替代审查。","sectionId":"ch12-s1","articles":["《宪法》第五条"],"tags":["实施与遵守","权限规则"],"id":"q-ch12-002","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":1},{"type":"judge","stem":"宪法遵守是实施的重要方面，但不是实施的全部内容。","options":["正确","错误"],"answer":"正确","explain":"实施还可从立法落实、机关履职和权利保障等方面观察，不能只作消极不违反理解。","sectionId":"ch12-s1","articles":["《宪法》第五条"],"tags":["实施与遵守","制度联系"],"id":"q-ch12-003","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":2},{"type":"judge","stem":"宪法最高效力意味着全部具体法律均不必再适用。","options":["正确","错误"],"answer":"错误","explain":"具体法律在宪法框架内落实规则，最高位阶不等于取代一切细则。","sectionId":"ch12-s1","articles":["《宪法》第五条"],"tags":["实施与遵守","适用边界"],"id":"q-ch12-004","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":3},{"type":"single","stem":"全国人大在宪法实施方面的明确职权是什么？","options":["解释宪法","最终决定每一份备案文件的全部处理","监督宪法实施","直接替代行政机关实施一切法律"],"answer":"C","explain":"第六十二条明确监督实施，不能等同包办所有基层或私法事务。","sectionId":"ch12-s2","articles":["《宪法》第六十二条","《宪法》第六十七条","《宪法》第五条"],"tags":["监督主体","机关定位"],"id":"q-ch12-005","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":1},{"type":"single","stem":"全国人大常委会在宪法实施方面具有哪组职权？","options":["修改宪法并独立最终通过","解释宪法并监督实施","仅解释法律而无宪法解释权","仅听取建议而无监督实施职权"],"answer":"B","explain":"第六十七条配置解释监督，修宪属于全国人大程序，不能任意扩权。","sectionId":"ch12-s2","articles":["《宪法》第六十二条","《宪法》第六十七条","《宪法》第五条"],"tags":["监督主体","权限规则"],"id":"q-ch12-006","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":1},{"type":"judge","stem":"所有机关都有守宪义务，所以所有机关都有完全相同的撤销规范权限。","options":["正确","错误"],"answer":"错误","explain":"一般义务不产生同等专门职权，撤销对象权限程序须依法确定。","sectionId":"ch12-s2","articles":["《宪法》第六十二条","《宪法》第六十七条","《宪法》第五条"],"tags":["监督主体","制度联系"],"id":"q-ch12-007","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":2},{"type":"judge","stem":"公民提出监督意见与有权机关作出规范处理决定，属于不同层次。","options":["正确","错误"],"answer":"正确","explain":"社会参与有意义，但不等于意见提交者直接拥有机关处置权限。","sectionId":"ch12-s2","articles":["《宪法》第六十二条","《宪法》第六十七条","《宪法》第五条"],"tags":["监督主体","适用边界"],"id":"q-ch12-008","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":3},{"type":"single","stem":"全国人大常委会的宪法解释与教师讲解，区别的核心是什么？","options":["两者都属于同效力的正式解释","有权主体正式解释与学理说明","两者都只能修改不能解释","两者都只对教师学生关系发生效力"],"answer":"B","explain":"权限性质决定解释地位，字数职称不产生法定解释权，也不自动修宪。","sectionId":"ch12-s3","articles":["《宪法》第六十七条","《宪法》第六十四条"],"tags":["宪法解释","机关定位"],"id":"q-ch12-009","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":1},{"type":"single","stem":"对条文含义作解释与改变宪法文本，应如何区分？","options":["前者是解释问题，后者须走修宪程序","解释可随时取代法定修改程序","任何机关说明含义即等于完成修宪","修改只需发布学理说明而不表决"],"answer":"A","explain":"第六十七条与第六十四条分别涉及解释与修宪，不能用学习活动或合同程序替代。","sectionId":"ch12-s3","articles":["《宪法》第六十七条","《宪法》第六十四条"],"tags":["宪法解释","权限规则"],"id":"q-ch12-010","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":1},{"type":"judge","stem":"检索到一位学者的解释，就可以称其为全国人大常委会正式宪法解释。","options":["正确","错误"],"answer":"错误","explain":"研究观点不是法定机关行为，必须明确主体和材料性质。","sectionId":"ch12-s3","articles":["《宪法》第六十七条","《宪法》第六十四条"],"tags":["宪法解释","制度联系"],"id":"q-ch12-011","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":2},{"type":"judge","stem":"讨论新情形下条文含义时，仍须避免以解释名义无依据改变制度。","options":["正确","错误"],"answer":"正确","explain":"解释围绕规范含义适用，并不允许绕开修宪程序随意改写文本。","sectionId":"ch12-s3","articles":["《宪法》第六十七条","《宪法》第六十四条"],"tags":["宪法解释","适用边界"],"id":"q-ch12-012","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":3},{"type":"single","stem":"谁可以提出宪法修改提议？","options":["全国人大常委会或五分之一以上全国人大代表","国务院或五分之一以上全国人大代表","全国人大常委会或五分之一以上出席代表","全国人大各专门委员会单独提议"],"answer":"A","explain":"第六十四条明确两类提议主体，不能将常委会泛化为任意地方常委会。","sectionId":"ch12-s4","articles":["《宪法》第六十四条"],"tags":["修宪程序","机关定位"],"id":"q-ch12-013","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":1},{"type":"single","stem":"全国人大通过宪法修改的门槛是什么？","options":["出席代表三分之二以上","全体代表过半数","全体代表五分之一以上","全体代表三分之二以上多数"],"answer":"D","explain":"宪法明确全体代表为分母及三分之二以上比例，出席分母和普通门槛均不准确。","sectionId":"ch12-s4","articles":["《宪法》第六十四条"],"tags":["修宪程序","权限规则"],"id":"q-ch12-014","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":1},{"type":"judge","stem":"宪法修正提议的代表比例，与最终通过的表决比例不是同一个门槛。","options":["正确","错误"],"answer":"正确","explain":"五分之一以上为提议条件之一，三分之二以上为全体代表通过标准，须分阶段理解。","sectionId":"ch12-s4","articles":["《宪法》第六十四条"],"tags":["修宪程序","制度联系"],"id":"q-ch12-015","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":2},{"type":"judge","stem":"普通法律和其他议案也必须按修宪的三分之二以上门槛通过。","options":["正确","错误"],"answer":"错误","explain":"第六十四条另规定法律其他议案以全体代表过半数通过，应区分两类标准。","sectionId":"ch12-s4","articles":["《宪法》第六十四条"],"tags":["修宪程序","适用边界"],"id":"q-ch12-016","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":3},{"type":"single","stem":"合宪性审查首先关注什么？","options":["仅是否符合法律而不考虑宪法","仅报备手续是否完成","仅是否符合制定机关意愿","是否符合宪法"],"answer":"D","explain":"合宪性是规范标准问题，不可缩为形式外观或人员资历。","sectionId":"ch12-s5","articles":["《宪法》第五条","《宪法》第六十七条"],"tags":["合宪性与备案审查","机关定位"],"id":"q-ch12-017","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":1},{"type":"single","stem":"备案审查与合宪性审查的入门区别是什么？","options":["两者在所有对象程序上完全相同","两者都仅指民事调解","制度机制与审查标准维度不同而有交叉","两者完全无联系"],"answer":"C","explain":"备案审查可涉及合宪合法等问题，与合宪性审查交叉，但标准和机制不能直接等同。","sectionId":"ch12-s5","articles":["《宪法》第五条","《宪法》第六十七条"],"tags":["合宪性与备案审查","权限规则"],"id":"q-ch12-018","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":1},{"type":"judge","stem":"文件已经报备，就足以证明内容当然合宪并不再需要审查。","options":["正确","错误"],"answer":"错误","explain":"报备状态与审查结论不同，备案不是对全部内容的自动认可。","sectionId":"ch12-s5","articles":["《宪法》第五条","《宪法》第六十七条"],"tags":["合宪性与备案审查","制度联系"],"id":"q-ch12-019","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":2},{"type":"judge","stem":"有关备案对象期限等具体程序，须进一步核对专门规范，不能只凭宪法第五条猜测。","options":["正确","错误"],"answer":"正确","explain":"宪法统一要求提供方向，具体报备审查细则须有相应法律文件证据。","sectionId":"ch12-s5","articles":["《宪法》第五条","《宪法》第六十七条"],"tags":["合宪性与备案审查","适用边界"],"id":"q-ch12-020","chapterId":"ch12","chapterTitle":"第十二章 宪法实施监督","difficulty":3}]},"articles":{"《宪法》第一条":"第一条　中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家。\n社会主义制度是中华人民共和国的根本制度。中国共产党领导是中国特色社会主义最本质的特征。禁止任何组织或者个人破坏社会主义制度。","《宪法》第一百一十二条":"第一百一十二条　民族自治地方的自治机关是自治区、自治州、自治县的人民代表大会和人民政府。","《宪法》第一百一十条":"第一百一十条　地方各级人民政府对本级人民代表大会负责并报告工作。县级以上的地方各级人民政府在本级人民代表大会闭会期间，对本级人民代表大会常务委员会负责并报告工作。\n地方各级人民政府对上一级国家行政机关负责并报告工作。全国地方各级人民政府都是国务院统一领导下的国家行政机关，都服从国务院。","《宪法》第一百三十四条":"第一百三十四条　中华人民共和国人民检察院是国家的法律监督机关。","《宪法》第一百二十三条":"第一百二十三条　中华人民共和国各级监察委员会是国家的监察机关。","《宪法》第一百四十条":"第一百四十条　人民法院、人民检察院和公安机关办理刑事案件，应当分工负责，互相配合，互相制约，以保证准确有效地执行法律。","《宪法》第一百零四条":"第一百零四条　县级以上的地方各级人民代表大会常务委员会讨论、决定本行政区域内各方面工作的重大事项；监督本级人民政府、监察委员会、人民法院和人民检察院的工作；撤销本级人民政府的不适当的决定和命令；撤销下一级人民代表大会的不适当的决议；依照法律规定的权限决定国家机关工作人员的任免；在本级人民代表大会闭会期间，罢免和补选上一级人民代表大会的个别代表。","《宪法》第三十一条":"第三十一条　国家在必要时得设立特别行政区。在特别行政区内实行的制度按照具体情况由全国人民代表大会以法律规定。","《宪法》第三十三条":"第三十三条　凡具有中华人民共和国国籍的人都是中华人民共和国公民。\n中华人民共和国公民在法律面前一律平等。\n国家尊重和保障人权。\n任何公民享有宪法和法律规定的权利，同时必须履行宪法和法律规定的义务。","《宪法》第三十五条":"第三十五条　中华人民共和国公民有言论、出版、集会、结社、游行、示威的自由。","《宪法》第三十六条":"第三十六条　中华人民共和国公民有宗教信仰自由。\n任何国家机关、社会团体和个人不得强制公民信仰宗教或者不信仰宗教，不得歧视信仰宗教的公民和不信仰宗教的公民。\n国家保护正常的宗教活动。任何人不得利用宗教进行破坏社会秩序、损害公民身体健康、妨碍国家教育制度的活动。\n宗教团体和宗教事务不受外国势力的支配。","《宪法》第三十条":"第三十条　中华人民共和国的行政区域划分如下：\n（一）全国分为省、自治区、直辖市；\n（二）省、自治区分为自治州、县、自治县、市；\n（三）县、自治县分为乡、民族乡、镇。\n直辖市和较大的市分为区、县。自治州分为县、自治县、市。\n自治区、自治州、自治县都是民族自治地方。","《宪法》第九十七条":"第九十七条　省、直辖市、设区的市的人民代表大会代表由下一级的人民代表大会选举；县、不设区的市、市辖区、乡、民族乡、镇的人民代表大会代表由选民直接选举。\n地方各级人民代表大会代表名额和代表产生办法由法律规定。","《宪法》第九十六条":"第九十六条　地方各级人民代表大会是地方国家权力机关。\n县级以上的地方各级人民代表大会设立常务委员会。","《宪法》第二十六条":"第二十六条　国家保护和改善生活环境和生态环境，防治污染和其他公害。\n国家组织和鼓励植树造林，保护林木。","《宪法》第五十一条":"第五十一条　中华人民共和国公民在行使自由和权利的时候，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。","《宪法》第五十三条":"第五十三条　中华人民共和国公民必须遵守宪法和法律，保守国家秘密，爱护公共财产，遵守劳动纪律，遵守公共秩序，尊重社会公德。","《宪法》第五十二条":"第五十二条　中华人民共和国公民有维护国家统一和全国各民族团结的义务。","《宪法》第五十六条":"第五十六条　中华人民共和国公民有依照法律纳税的义务。","《宪法》第五条":"第五条　中华人民共和国实行依法治国，建设社会主义法治国家。\n国家维护社会主义法制的统一和尊严。\n一切法律、行政法规和地方性法规都不得同宪法相抵触。\n一切国家机关和武装力量、各政党和各社会团体、各企业事业组织都必须遵守宪法和法律。一切违反宪法和法律的行为，必须予以追究。\n任何组织或者个人都不得有超越宪法和法律的特权。","《宪法》第八十条":"第八十条　中华人民共和国主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，公布法律，任免国务院总理、副总理、国务委员、各部部长、各委员会主任、审计长、秘书长，授予国家的勋章和荣誉称号，发布特赦令，宣布进入紧急状态，宣布战争状态，发布动员令。","《宪法》第六十二条":"第六十二条　全国人民代表大会行使下列职权：\n（一）修改宪法；\n（二）监督宪法的实施；\n（三）制定和修改刑事、民事、国家机构的和其他的基本法律；\n（四）选举中华人民共和国主席、副主席；\n（五）根据中华人民共和国主席的提名，决定国务院总理的人选；根据国务院总理的提名，决定国务院副总理、国务委员、各部部长、各委员会主任、审计长、秘书长的人选；\n（六）选举中央军事委员会主席；根据中央军事委员会主席的提名，决定中央军事委员会其他组成人员的人选；\n（七）选举国家监察委员会主任；\n（八）选举最高人民法院院长；\n（九）选举最高人民检察院检察长；\n（十）审查和批准国民经济和社会发展计划和计划执行情况的报告；\n（十一）审查和批准国家的预算和预算执行情况的报告；\n（十二）改变或者撤销全国人民代表大会常务委员会不适当的决定；\n（十三）批准省、自治区和直辖市的建置；\n（十四）决定特别行政区的设立及其制度；\n（十五）决定战争和和平的问题；\n（十六）应当由最高国家权力机关行使的其他职权。","《宪法》第六条":"第六条　中华人民共和国的社会主义经济制度的基础是生产资料的社会主义公有制，即全民所有制和劳动群众集体所有制。社会主义公有制消灭人剥削人的制度，实行各尽所能、按劳分配的原则。\n国家在社会主义初级阶段，坚持公有制为主体、多种所有制经济共同发展的基本经济制度，坚持按劳分配为主体、多种分配方式并存的分配制度。","《宪法》第十三条":"第十三条　公民的合法的私有财产不受侵犯。\n国家依照法律规定保护公民的私有财产权和继承权。\n国家为了公共利益的需要，可以依照法律规定对公民的私有财产实行征收或者征用并给予补偿。","《宪法》第十四条":"第十四条　国家通过提高劳动者的积极性和技术水平，推广先进的科学技术，完善经济管理体制和企业经营管理制度，实行各种形式的社会主义责任制，改进劳动组织，以不断提高劳动生产率和经济效益，发展社会生产力。\n国家厉行节约，反对浪费。\n国家合理安排积累和消费，兼顾国家、集体和个人的利益，在发展生产的基础上，逐步改善人民的物质生活和文化生活。\n国家建立健全同经济发展水平相适应的社会保障制度。","《宪法》第四十一条":"第四十一条　中华人民共和国公民对于任何国家机关和国家工作人员，有提出批评和建议的权利；对于任何国家机关和国家工作人员的违法失职行为，有向有关国家机关提出申诉、控告或者检举的权利，但是不得捏造或者歪曲事实进行诬告陷害。\n对于公民的申诉、控告或者检举，有关国家机关必须查清事实，负责处理。任何人不得压制和打击报复。\n由于国家机关和国家工作人员侵犯公民权利而受到损失的人，有依照法律规定取得赔偿的权利。","《宪法》第四十三条":"第四十三条　中华人民共和国劳动者有休息的权利。\n国家发展劳动者休息和休养的设施，规定职工的工作时间和休假制度。","《宪法》第四十五条":"第四十五条　中华人民共和国公民在年老、疾病或者丧失劳动能力的情况下，有从国家和社会获得物质帮助的权利。国家发展为公民享受这些权利所需要的社会保险、社会救济和医疗卫生事业。\n国家和社会保障残废军人的生活，抚恤烈士家属，优待军人家属。\n国家和社会帮助安排盲、聋、哑和其他有残疾的公民的劳动、生活和教育。","《宪法》第四十条":"第四十条　中华人民共和国公民的通信自由和通信秘密受法律的保护。除因国家安全或者追查刑事犯罪的需要，由公安机关或者检察机关依照法律规定的程序对通信进行检查外，任何组织或者个人不得以任何理由侵犯公民的通信自由和通信秘密。","《宪法》第六十四条":"第六十四条　宪法的修改，由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过。\n法律和其他议案由全国人民代表大会以全体代表的过半数通过。","《宪法》第二条":"第二条　中华人民共和国的一切权力属于人民。\n人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。\n人民依照法律规定，通过各种途径和形式，管理国家事务，管理经济和文化事业，管理社会事务。","《宪法》第三条":"第三条　中华人民共和国的国家机构实行民主集中制的原则。\n全国人民代表大会和地方各级人民代表大会都由民主选举产生，对人民负责，受人民监督。\n国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。\n中央和地方的国家机构职权的划分，遵循在中央的统一领导下，充分发挥地方的主动性、积极性的原则。","《宪法》第五十七条":"第五十七条　中华人民共和国全国人民代表大会是最高国家权力机关。它的常设机关是全国人民代表大会常务委员会。","《宪法》第七十五条":"第七十五条　全国人民代表大会代表在全国人民代表大会各种会议上的发言和表决，不受法律追究。","《宪法》第五十九条":"第五十九条　全国人民代表大会由省、自治区、直辖市、特别行政区和军队选出的代表组成。各少数民族都应当有适当名额的代表。\n全国人民代表大会代表的选举由全国人民代表大会常务委员会主持。\n全国人民代表大会代表名额和代表产生办法由法律规定。","《宪法》第三十四条":"第三十四条　中华人民共和国年满十八周岁的公民，不分民族、种族、性别、职业、家庭出身、宗教信仰、教育程度、财产状况、居住期限，都有选举权和被选举权；但是依照法律被剥夺政治权利的人除外。","《宪法》第四条":"第四条　中华人民共和国各民族一律平等。国家保障各少数民族的合法的权利和利益，维护和发展各民族的平等团结互助和谐关系。禁止对任何民族的歧视和压迫，禁止破坏民族团结和制造民族分裂的行为。\n国家根据各少数民族的特点和需要，帮助各少数民族地区加速经济和文化的发展。\n各少数民族聚居的地方实行区域自治，设立自治机关，行使自治权。各民族自治地方都是中华人民共和国不可分离的部分。\n各民族都有使用和发展自己的语言文字的自由，都有保持或者改革自己的风俗习惯的自由。","《宪法》第一百一十五条":"第一百一十五条　自治区、自治州、自治县的自治机关行使宪法第三章第五节规定的地方国家机关的职权，同时依照宪法、民族区域自治法和其他法律规定的权限行使自治权，根据本地方实际情况贯彻执行国家的法律、政策。","《宪法》第一百一十一条":"第一百一十一条　城市和农村按居民居住地区设立的居民委员会或者村民委员会是基层群众性自治组织。居民委员会、村民委员会的主任、副主任和委员由居民选举。居民委员会、村民委员会同基层政权的相互关系由法律规定。\n居民委员会、村民委员会设人民调解、治安保卫、公共卫生等委员会，办理本居住地区的公共事务和公益事业，调解民间纠纷，协助维护社会治安，并且向人民政府反映群众的意见、要求和提出建议。","《宪法》第十一条":"第十一条　在法律规定范围内的个体经济、私营经济等非公有制经济，是社会主义市场经济的重要组成部分。\n国家保护个体经济、私营经济等非公有制经济的合法的权利和利益。国家鼓励、支持和引导非公有制经济的发展，并对非公有制经济依法实行监督和管理。","《宪法》第十条":"第十条　城市的土地属于国家所有。\n农村和城市郊区的土地，除由法律规定属于国家所有的以外，属于集体所有；宅基地和自留地、自留山，也属于集体所有。\n国家为了公共利益的需要，可以依照法律规定对土地实行征收或者征用并给予补偿。\n任何组织或者个人不得侵占、买卖或者以其他形式非法转让土地。土地的使用权可以依照法律的规定转让。\n一切使用土地的组织和个人必须合理地利用土地。","《宪法》第十九条":"第十九条　国家发展社会主义的教育事业，提高全国人民的科学文化水平。\n国家举办各种学校，普及初等义务教育，发展中等教育、职业教育和高等教育，并且发展学前教育。\n国家发展各种教育设施，扫除文盲，对工人、农民、国家工作人员和其他劳动者进行政治、文化、科学、技术、业务的教育，鼓励自学成才。\n国家鼓励集体经济组织、国家企业事业组织和其他社会力量依照法律规定举办各种教育事业。\n国家推广全国通用的普通话。","《宪法》第二十二条":"第二十二条　国家发展为人民服务、为社会主义服务的文学艺术事业、新闻广播电视事业、出版发行事业、图书馆博物馆文化馆和其他文化事业，开展群众性的文化活动。\n国家保护名胜古迹、珍贵文物和其他重要历史文化遗产。","《宪法》第三十七条":"第三十七条　中华人民共和国公民的人身自由不受侵犯。\n任何公民，非经人民检察院批准或者决定或者人民法院决定，并由公安机关执行，不受逮捕。\n禁止非法拘禁和以其他方法非法剥夺或者限制公民的人身自由，禁止非法搜查公民的身体。","《宪法》第三十八条":"第三十八条　中华人民共和国公民的人格尊严不受侵犯。禁止用任何方法对公民进行侮辱、诽谤和诬告陷害。","《宪法》第三十九条":"第三十九条　中华人民共和国公民的住宅不受侵犯。禁止非法搜查或者非法侵入公民的住宅。","《宪法》第四十二条":"第四十二条　中华人民共和国公民有劳动的权利和义务。\n国家通过各种途径，创造劳动就业条件，加强劳动保护，改善劳动条件，并在发展生产的基础上，提高劳动报酬和福利待遇。\n劳动是一切有劳动能力的公民的光荣职责。国有企业和城乡集体经济组织的劳动者都应当以国家主人翁的态度对待自己的劳动。国家提倡社会主义劳动竞赛，奖励劳动模范和先进工作者。国家提倡公民从事义务劳动。\n国家对就业前的公民进行必要的劳动就业训练。","《宪法》第四十六条":"第四十六条　中华人民共和国公民有受教育的权利和义务。\n国家培养青年、少年、儿童在品德、智力、体质等方面全面发展。","《宪法》第四十七条":"第四十七条　中华人民共和国公民有进行科学研究、文学艺术创作和其他文化活动的自由。国家对于从事教育、科学、技术、文学、艺术和其他文化事业的公民的有益于人民的创造性工作，给以鼓励和帮助。","《宪法》第五十四条":"第五十四条　中华人民共和国公民有维护祖国的安全、荣誉和利益的义务，不得有危害祖国的安全、荣誉和利益的行为。","《宪法》第五十五条":"第五十五条　保卫祖国、抵抗侵略是中华人民共和国每一个公民的神圣职责。\n依照法律服兵役和参加民兵组织是中华人民共和国公民的光荣义务。","《宪法》第六十七条":"第六十七条　全国人民代表大会常务委员会行使下列职权：\n（一）解释宪法，监督宪法的实施；\n（二）制定和修改除应当由全国人民代表大会制定的法律以外的其他法律；\n（三）在全国人民代表大会闭会期间，对全国人民代表大会制定的法律进行部分补充和修改，但是不得同该法律的基本原则相抵触；\n（四）解释法律；\n（五）在全国人民代表大会闭会期间，审查和批准国民经济和社会发展计划、国家预算在执行过程中所必须作的部分调整方案；\n（六）监督国务院、中央军事委员会、国家监察委员会、最高人民法院和最高人民检察院的工作；\n（七）撤销国务院制定的同宪法、法律相抵触的行政法规、决定和命令；\n（八）撤销省、自治区、直辖市国家权力机关制定的同宪法、法律和行政法规相抵触的地方性法规和决议；\n（九）在全国人民代表大会闭会期间，根据国务院总理的提名，决定部长、委员会主任、审计长、秘书长的人选；\n（十）在全国人民代表大会闭会期间，根据中央军事委员会主席的提名，决定中央军事委员会其他组成人员的人选；\n（十一）根据国家监察委员会主任的提请，任免国家监察委员会副主任、委员；\n（十二）根据最高人民法院院长的提请，任免最高人民法院副院长、审判员、审判委员会委员和军事法院院长；\n（十三）根据最高人民检察院检察长的提请，任免最高人民检察院副检察长、检察员、检察委员会委员和军事检察院检察长，并且批准省、自治区、直辖市的人民检察院检察长的任免；\n（十四）决定驻外全权代表的任免；\n（十五）决定同外国缔结的条约和重要协定的批准和废除；\n（十六）规定军人和外交人员的衔级制度和其他专门衔级制度；\n（十七）规定和决定授予国家的勋章和荣誉称号；\n（十八）决定特赦；\n（十九）在全国人民代表大会闭会期间，如果遇到国家遭受武装侵犯或者必须履行国际间共同防止侵略的条约的情况，决定战争状态的宣布；\n（二十）决定全国总动员或者局部动员；\n（二十一）决定全国或者个别省、自治区、直辖市进入紧急状态；\n（二十二）全国人民代表大会授予的其他职权。","《宪法》第八十五条":"第八十五条　中华人民共和国国务院，即中央人民政府，是最高国家权力机关的执行机关，是最高国家行政机关。","《宪法》第九十三条":"第九十三条　中华人民共和国中央军事委员会领导全国武装力量。\n中央军事委员会由下列人员组成：\n主席，\n副主席若干人，\n委员若干人。\n中央军事委员会实行主席负责制。\n中央军事委员会每届任期同全国人民代表大会每届任期相同。","《宪法》第一百二十七条":"第一百二十七条　监察委员会依照法律规定独立行使监察权，不受行政机关、社会团体和个人的干涉。\n监察机关办理职务违法和职务犯罪案件，应当与审判机关、检察机关、执法部门互相配合，互相制约。","《宪法》第一百二十八条":"第一百二十八条　中华人民共和国人民法院是国家的审判机关。","《宪法》第一百三十六条":"第一百三十六条　人民检察院依照法律规定独立行使检察权，不受行政机关、社会团体和个人的干涉。","《宪法》第一百零五条":"第一百零五条　地方各级人民政府是地方各级国家权力机关的执行机关，是地方各级国家行政机关。\n地方各级人民政府实行省长、市长、县长、区长、乡长、镇长负责制。"}};
